const maps = { town, ...shops, swamp, skatepark };

// Reshuffles, within EACH location that has one, which of that location's
// own crates holds its collectible record and which hold junk. A record's
// home building/outdoor area never changes (Elm Street Funk is always in
// Green Door Studio, the White Label is always somewhere in the flea
// market corner) -- only the specific crate you have to dig through moves,
// so returning players can't just walk straight to a remembered spot.
// Locations built with no `record` among their crates (Henry's/Nectar's/
// Truth Lab, which are pure themed-junk digs) are skipped automatically,
// since shuffling them would have no player-visible effect anyway.
// Called once below (so even a brand-new save starts from a shuffled
// layout) and again at the top of every newGame().
function shuffleRecordCrates() {
  Object.values(maps).forEach((map) => {
    const crateKeys = map._crateKeys;
    if (!crateKeys || crateKeys.length < 2) return;
    if (!crateKeys.some((k) => map.crates[k] && map.crates[k].record)) return;
    const values = crateKeys.map((k) => map.crates[k]);
    for (let i = values.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [values[i], values[j]] = [values[j], values[i]];
    }
    crateKeys.forEach((k, i) => { map.crates[k] = values[i]; });
  });
}
shuffleRecordCrates();

// ---------------------------------------------------------------- state
const player = {
  map: 'town', x: 19.5 * TILE, y: 12.5 * TILE,
  dir: 'down', moving: false, skating: false, animT: 0,
  holdingCoffee: false, holdingTea: false,
  tempItem: null, tempItemTimer: 0,
};
const collected = new Set();
let state = 'splash'; // travSkatesApp (TALENT Trav Skates overlay) | guitarApp (SPEAKING VOLUMES guitar overlay) | skateHipHopReaderApp (TALENT reader overlay) | splash | title | digChoice | history | slotChoose | select | characterIntro | play | dialog | record | win | danceParty | portal | fifa | minigame | hotkeys | crate | photo | lab | labLocked | shopBackLocked | labApp | chessApp | beatBotApp | organApp | minigolfApp | blackbookApp | crocSwampApp | qsdBalanceApp | vinylSnakeApp | waveformApp | bayouBreakApp | freqAltarApp | reverbReefApp | beatBrewingApp | drumPatternDocApp | gatorJamSlamApp | swampCaveApp | vocalChopBoothApp | vtDirtApp | penaltyKingsApp | digDashApp | digOnApp | rico1200App | ricoDawApp | filterLabApp | vinylNinjaSplash | vinylNinjaApp | diggerApp | hyperSwimApp | linusTugApp | connectFourApp | syrupRoadsApp | scoopBeatsApp | clawMachineApp | kangaidenVideo | kangaidenSplash | kangaidenApp | hiphopLibraryApp | truthKnocksVideo | truthKnocksSplash | truthKnocksApp | johnnySlidesVideo | johnnySlidesSplash | johnnySlidesApp | humbleTreasuresVideo | humbleTreasuresSplash | humbleTreasuresApp | dustRacingApp | cbPressApp | spotDiffApp | arkaiikImpactApp | precisionPointsApp | wishJamApp
// State to snap back to when the [H] hotkeys popup is closed -- currently
// always 'play' since that's the only state H can be opened from, but kept
// as its own var in case another state wants to offer the popup later.
let hotkeysReturnState = 'play';
// The Crate -- a persistent collection book of every record found across
// every world (see WORLD_DEFS + drawCrate()). crateWorldIndex/crateSlotIndex
// track which world tab and which of that world's 5 slots the player is
// currently browsing; both reset to 0 whenever the crate is opened fresh so
// it always starts on the player's current world.
let crateReturnState = 'play';
let crateWorldIndex = 0;
let crateSlotIndex = 0;
// [G] Photo Mode -- same "return state" pattern as hotkeysReturnState/
// crateReturnState above, though in practice it's only ever opened from
// 'play'. photoCamOffset is a small screen-space nudge (see the 'photo'
// branch in update() and the ctx.translate() in render()) that lets the
// player frame a cleaner shot; it resets to centered every time the mode
// is (re)opened.
let photoReturnState = 'play';
let photoCamOffset = { x: 0, y: 0 };
const PHOTO_NUDGE_STEP = 6, PHOTO_NUDGE_MAX = 36;
function openPhotoMode() {
  if (state !== 'play') return;
  photoReturnState = state;
  photoCamOffset = { x: 0, y: 0 };
  state = 'photo';
}
// [T] Turbo Taunt / Trick Button -- purely cosmetic, see triggerTrick()
// below. `trick` drives a brief spin on the player sprite (drawPlayer());
// `trickSparkles` is a small bounded particle burst, same "push, cap,
// shift the oldest off" shape as the skate trail near the top of this file
// so it can never grow unbounded no matter how fast the key is mashed.
let trick = null; // { t, dur }
let trickSparkles = [];
const TRICK_NAMES = ['KICKFLIP!', '360 SPIN!', 'OLLIE!', 'BOARDSLIDE!'];
function triggerTrick() {
  if (state !== 'play' || !player.skating) return;
  trick = { t: 0, dur: 0.5 };
  for (let i = 0; i < 8; i++) {
    const ang = Math.random() * Math.PI * 2;
    const spd = 40 + Math.random() * 55;
    trickSparkles.push({
      x: player.x, y: player.y - 22,
      vx: Math.cos(ang) * spd, vy: Math.sin(ang) * spd - 25,
      life: 0.45, maxLife: 0.45,
    });
  }
  toast = { text: TRICK_NAMES[Math.floor(Math.random() * TRICK_NAMES.length)], t: 0.9 };
  music.trickChime();
}
function updateTrickSparkles(dt) {
  for (let i = trickSparkles.length - 1; i >= 0; i--) {
    const p = trickSparkles[i];
    p.life -= dt;
    if (p.life <= 0) { trickSparkles.splice(i, 1); continue; }
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.vy += 70 * dt; // slight gravity so sparkles arc instead of flying dead straight
  }
}
function drawTrickSparkles() {
  for (const p of trickSparkles) {
    const k = Math.max(0, p.life / p.maxLife);
    ctx.globalAlpha = k;
    ctx.fillStyle = '#fff6d6';
    ctx.beginPath();
    ctx.arc(p.x, p.y, 1.5 + 2 * k, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}
// Personal-best tracker for the 8 scored mini-games (see MINIGAME_TROPHIES +
// recordMinigameScore() below). personalBests maps a mini-game id to the
// best value reached so far; it rides along in the save file exactly like
// `collected`, so bests are per-slot, same as everything else about a
// playthrough. Each mini-game's own 'done' screen reads this to flash
// "NEW BEST!".
let personalBests = {};
// Which of the title screen's two pages is showing: 0 = the main title
// (story + start prompt), 1 = the Hot Keys page. Toggled with left/right
// (or [H]) while state === 'title'; reset to 0 any time the player lands
// back on the title screen fresh, so it never gets stuck on page 2.
let titlePage = 0;
let dialog = null;   // { name, lines, i }
let shownRecord = null;
let activePortal = null; // { x, y } tile the player walked into to open the portal popup
const completedWorlds = new Set(); // worlds whose 5 records have all been found
let toast = null;    // { text, t }

// Level-intro card -- a full-screen "LEVEL N / world name" splash drawn with
// drawRetroTitle() (the same carved-gold look used on character select).
// showLevelIntro() is the one entry point: pass the world id about to be
// entered and a callback for what happens once the card is dismissed, either
// by [E] (after LEVEL_INTRO_SKIP_DELAY_MS, so a held-over interact press
// from the previous screen can't insta-skip it) or automatically after
// LEVEL_INTRO_AUTO_MS. Currently only shown for Level 1 on a fresh game --
// see chooseCharacter() -- but any future world-to-world transition can
// route through showLevelIntro() the same way to get this for free.
let levelIntroWorldId = null;
let levelIntroOnDone = null;
let levelIntroStartTime = 0;
const LEVEL_INTRO_SKIP_DELAY_MS = 400;
const LEVEL_INTRO_AUTO_MS = 2600;
// Numbers a world by its position among the player-visible (non-locked)
// worlds in WORLD_DEFS -- see crateWorldIds() -- so level numbers stay
// correct as more worlds get added/unlocked with no manual renumbering.
function levelNumberFor(worldId) { return crateWorldIds().indexOf(worldId) + 1; }
function showLevelIntro(worldId, onDone) {
  levelIntroWorldId = worldId;
  levelIntroOnDone = onDone;
  levelIntroStartTime = performance.now();
  state = 'levelIntro';
}
function finishLevelIntro() {
  if (!levelIntroOnDone) return; // already finished -- ignore a duplicate press/timeout
  const done = levelIntroOnDone;
  levelIntroOnDone = null;
  done();
}

// ---------------------------------------------------------------- Rico's Lab
// The lab door only opens once every record in the current town has been
// found (see checkLabDoor()). activeLabDoor mirrors activePortal -- it
// records the tile the player walked onto so closing the popup can nudge
// them back off of it. labIndex is the keyboard/tap-selected instrument
// (0-3, matching LAB_OPTIONS below) and labLayout mirrors selectLayout,
// recording where drawLabPopup() last drew the splash art so taps can be
// mapped back onto one of the 4 boxes.
let activeLabDoor = null; // { x, y } tile the player walked into to open the lab popup
// A shop's own locked "back room" door (see makeShop()'s backDoorTile opt),
// mirrors activeLabDoor/activePortal above -- records the tile the player
// walked into so closing the locked popup can nudge them back off of it.
// SHOP_BACK_ROOMS maps a shop's map id to the room its back door leads to
// plus the flavor text for its locked popup -- see checkShopBackDoor()/
// drawShopBackDoor()/drawShopBackLockedPopup() further down.
let activeShopBackDoor = null;
const SHOP_BACK_ROOMS = {
  // TRUTH LAB's back room -- Tha Truth's vocal chop/looper booth, unlocked
  // once every record in the swamp has been found.
  truthlab: {
    room: 'truthlabback',
    title: 'TRUTH LAB — BACK ROOM',
    locked: "This door's not opening yet. Dig up every last record hiding in the swamp first, then come find me back here.",
  },
};
let labIndex = 0;
let labLayout = null; // { originX, originY, scale, imgW, imgH } of the drawn lab splash art
let activeLabApp = null; // id of the instrument currently loaded in the DOM overlay, or null
let labHistoryPushed = false; // true while an extra history entry is sitting under an open instrument (see openInstrument/closeInstrument)

// ---------------------------------------------------------------- save / load
// Save/load only ever run on explicit checkpoints below (never once per
// frame), so this has zero effect on gameplay performance or loading times.
// The payload is a tiny JSON object (well under 1KB), and localStorage
// read/write for something that size is effectively instant.
//
// Three independent save slots (1-3) let a player keep multiple digs going
// at once. `currentSlot` is whichever slot the *active* playthrough reads
// from/writes to; it's set the moment a slot is chosen (fresh or continued)
// and every autosave/manual save from then on goes to that slot only.
const SAVE_KEY_PREFIX = 'ricoVinylQuest_save_v1_slot';
const LEGACY_SAVE_KEY = 'ricoVinylQuest_save_v1'; // pre-slots single save
const SAVE_SLOTS = [1, 2, 3];
let currentSlot = 1;

function slotKey(slot) { return SAVE_KEY_PREFIX + slot; }

function hasSave(slot) {
  try { return !!localStorage.getItem(slotKey(slot)); }
  catch { return false; }
}

// A save exists in ANY slot -- used only for one-time migration below.
function hasAnySave() { return SAVE_SLOTS.some(hasSave); }

// One-time migration: if this is a returning player with the old
// single-save format and slot 1 is empty, move it into slot 1 so nobody's
// progress disappears when this update ships.
(function migrateLegacySave() {
  try {
    const legacy = localStorage.getItem(LEGACY_SAVE_KEY);
    if (legacy && !hasSave(1)) {
      localStorage.setItem(slotKey(1), legacy);
      localStorage.removeItem(LEGACY_SAVE_KEY);
    }
  } catch (err) { console.warn('save migration failed:', err); }
})();

// Reads and validates a slot's save data without applying it to the live
// game state. Returns null for an empty, corrupt, or outdated slot.
function readSlot(slot) {
  try {
    const raw = localStorage.getItem(slotKey(slot));
    if (!raw) return null;
    const data = JSON.parse(raw);
    if (!data || !CHARACTERS[data.character] || !maps[data.map]) return null;
    return data;
  } catch (err) {
    return null;
  }
}

// Short "SANTOS - Burlington" style summary for a slot chooser row, or null
// if the slot is empty/unreadable.
function slotSummary(slot) {
  const data = readSlot(slot);
  if (!data) return null;
  const label = (CHARACTERS[data.character] || {}).label || '???';
  const worldId = (maps[data.map] || {}).world;
  const place = (WORLD_DEFS[worldId] || {}).name || data.map;
  return `${label} \u2014 ${place}`;
}

// Writes the current progress to localStorage under currentSlot. Called
// silently at natural checkpoints (record found, world completed, room
// change) plus on demand from the SAVE button / 'K' key, where showToast
// lets the player know it actually happened.
function saveGame(showToast) {
  try {
    const data = {
      v: 1,
      character: selectedCharacter,
      map: player.map,
      x: player.x,
      y: player.y,
      dir: player.dir,
      collected: [...collected],
      completedWorlds: [...completedWorlds],
      bests: personalBests,
    };
    localStorage.setItem(slotKey(currentSlot), JSON.stringify(data));
    if (showToast) toast = { text: 'Game Saved', t: 1.2 };
  } catch (err) {
    // Private browsing, full storage, disabled storage, etc. -- never let a
    // save failure crash or interrupt the game.
    if (showToast) toast = { text: 'Save failed', t: 1.2 };
    console.warn('saveGame failed:', err);
  }
}

// Saves written before `collected` switched to world-qualified keys
// ("town:elm" instead of a bare "elm") stored the bare id. Every world that
// was actually reachable back then was 'town', so that's the only sensible
// home for a legacy id -- the fallback scan only matters if a bare id ever
// shows up that isn't a town record, which shouldn't happen in practice.
function migrateRecordId(id) {
  if (typeof id !== 'string' || id.includes(':')) return id; // already namespaced
  if (WORLD_DEFS.town.records[id]) return recKey('town', id);
  const worldId = Object.keys(WORLD_DEFS).find((w) => WORLD_DEFS[w].records[id]);
  return worldId ? recKey(worldId, id) : recKey('town', id);
}

// Restores progress from the given slot and drops the player straight into
// 'play' at their last position. Returns false (and leaves the game state
// untouched) if the slot is empty or corrupt/outdated.
function loadGame(slot) {
  const data = readSlot(slot);
  if (!data) return false;

  currentSlot = slot;
  selectedCharacter = data.character;
  player.map = data.map;
  player.x = data.x;
  player.y = data.y;
  player.dir = data.dir || 'down';
  player.moving = false;
  player.skating = false;
  player.holdingCoffee = false;
  player.holdingTea = false;
  player.tempItem = null;
  player.tempItemTimer = 0;

  collected.clear();
  (data.collected || []).forEach((id) => collected.add(migrateRecordId(id)));
  completedWorlds.clear();
  (data.completedWorlds || []).forEach((id) => completedWorlds.add(id));
  personalBests = { ...(data.bests || {}) };

  state = 'play';
  music.setMenuBreak(false);
  toast = { text: 'Game Loaded', t: 1.2 };
  return true;
}

// Wipes the given slot and resets progress, then sends the player to the
// character-select screen just like a first-time launch. currentSlot is
// updated so the checkpoint autosaves that follow land in this slot.
function newGame(slot) {
  currentSlot = slot;
  try { localStorage.removeItem(slotKey(slot)); } catch (err) { console.warn('newGame clear failed:', err); }
  collected.clear();
  completedWorlds.clear();
  personalBests = {};
  shuffleRecordCrates(); // fresh crate layout for the new hunt, see above

  player.map = 'town';
  player.x = 19.5 * TILE;
  player.y = 12.5 * TILE;
  player.dir = 'down';
  player.skating = false;
  player.holdingCoffee = false;
  player.holdingTea = false;
  player.tempItem = null;
  player.tempItemTimer = 0;
  state = 'select';
  music.setMenuBreak(true);
}

// Voice line played the instant a character is locked in at the select
// screen — drop a short vocal clip at assets/lets_do_this.mp3 (or .ogg/.wav,
// see loadSfx below) to hear it. Until that file exists the browser just
// fails to load it silently; nothing breaks.
const letsDoThisSfx = loadSfx('assets/lets_do_this');
function loadSfx(basePath) {
  const a = new Audio();
  a.preload = 'auto';
  a.volume = 0.9;
  // Try each format as a separate <source>, so whichever file actually
  // exists (mp3/ogg/wav) gets picked up rather than only ever looking for
  // .mp3. Per the media spec, the browser falls through to the next
  // <source> both on an unsupported type AND on a failed/missing fetch, so
  // this covers "I dropped in a .wav" as well as "the .mp3 doesn't exist".
  ['mp3', 'ogg', 'wav'].forEach((ext) => {
    const src = document.createElement('source');
    src.src = `${basePath}.${ext}`;
    a.appendChild(src);
  });
  return a;
}

// The Dance Party track, played once start-to-finish by startDanceParty()
// (see the "Dance Party" section further down). Same loadSfx() helper as
// letsDoThisSfx above -- drop danceparty.mp3/.ogg/.wav in assets/ and
// whichever the browser picks up first plays; all three are same-origin
// local files, so this works fully offline with no extra handling. mp3/ogg
// are strongly recommended over a bare .wav here: a ~20-second uncompressed
// WAV runs several MB, while an mp3/ogg encode of the same clip is
// typically 10-20x smaller and just as instant to start once loaded (audio
// decode for a clip this short is effectively free) -- <source> fallback
// order below means the browser always prefers the compressed formats when
// they're present and only falls back to the wav if they're missing.
const dancePartySfx = loadSfx('assets/danceparty');

// Locks in a playable character and boots straight into the game with them.
// Behavior depends on how the player got here (see pendingMode, set by the
// START DIGGING / CONTINUE DIGGING -> slot-chooser flow):
//  - 'new':      fresh save in pendingSlot (already reset by newGame()).
//  - 'continue': loads pendingSlot's save, but the character picked HERE
//                (not the one stored in the save) is who you play as --
//                lets a player reskin a save without losing progress.
function chooseCharacter(id) {
  if (!CHARACTERS[id]) return;
  if (pendingMode === 'continue') {
    if (loadGame(pendingSlot)) {
      selectedCharacter = id;
      saveGame(); // keep the slot's stored character in sync with the pick
    } else {
      // slot vanished/corrupted between selection and now -- fail soft into
      // a fresh start rather than getting stuck.
      newGame(pendingSlot);
      selectedCharacter = id;
      saveGame();
    }
  } else {
    currentSlot = pendingSlot;
    selectedCharacter = id;
    saveGame(); // silent autosave checkpoint -- a save exists from the moment play begins
  }
  // Splash plays between the pick and the first frame of gameplay; state
  // only flips to 'play' (and the menu-break music ducks) once it's done.
  playCharacterIntro(() => {
    if (pendingMode === 'new') {
      // Fresh save: show the "LEVEL 1" card before the player's first frame
      // of gameplay. A continued save skips straight to 'play' since the
      // player is resuming a level already in progress, not starting one.
      showLevelIntro(currentWorldId(), () => {
        state = 'play';
        music.setMenuBreak(false);
      });
    } else {
      state = 'play';
      music.setMenuBreak(false);
    }
  });
}

function toggleSkate() {
  if (state !== 'play' || !maps[player.map].outside) return;
  player.skating = !player.skating;
  toast = { text: player.skating ? 'Skateboard: ON' : 'Skateboard: OFF', t: 1.2 };
}

// Cold brew and iced tea share the same hand, so picking one up puts the
// other down — just like Rico only has two hands to work with.
function toggleCoffee() {
  if (state !== 'play') return;
  player.holdingCoffee = !player.holdingCoffee;
  if (player.holdingCoffee) player.holdingTea = false;
  toast = { text: player.holdingCoffee ? 'Cold Brew: ON' : 'Cold Brew: OFF', t: 1.2 };
}

function toggleTea() {
  if (state !== 'play') return;
  player.holdingTea = !player.holdingTea;
  if (player.holdingTea) player.holdingCoffee = false;
  toast = { text: player.holdingTea ? 'Yerba Mate: ON' : 'Yerba Mate: OFF', t: 1.2 };
}

// ---------------------------------------------------------------- audio
const music = {
  ctx: null, master: null, duckGain: null, noiseBuf: null, muted: false,
  step: 0, nextTime: 0, BPM: 92,
  // Per-world layer tracking: each world keeps its own set of unlocked
  // sampler layers (drums/bass/horns/vox/lead), keyed by worldId, so
  // finding e.g. the swamp's Mud Kick drum layer doesn't also switch on
  // drums back in town, and vice versa -- every map's beat builds up
  // independently, on top of its own beat config (see WORLD_DEFS.*.beat).
  layersByWorld: {},
  menuDusty: false,
  ducked: false,

  start() {
    if (this.ctx) return;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.28;
    // Separate "duck" bus sitting between master and the speakers, so
    // rooms that need the background music fully out of the way (Rico's
    // Beat Lab, where the player is making their own beats on the pads)
    // can silence it without touching -- or being touched by -- the
    // independent mute toggle in `toggleMute()`. Two gain stages instead
    // of one shared value means muted+ducked, muted-only, and ducked-only
    // all resolve correctly no matter what order they're toggled in.
    this.duckGain = this.ctx.createGain();
    this.duckGain.gain.value = this.ducked ? 0 : 1;
    this.master.connect(this.duckGain);
    this.duckGain.connect(this.ctx.destination);
    const len = this.ctx.sampleRate * 0.5;
    this.noiseBuf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const d = this.noiseBuf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    this.nextTime = this.ctx.currentTime + 0.1;
    this.startTicker();
    this.installResumeGuards();
  },

  // The scheduler only works if `pump()` actually gets called on a steady
  // cadence. A plain main-thread setInterval shares its queue with every
  // synchronous bit of canvas drawing the game does each frame — the
  // outdoor map redraws a lot more per frame than an interior (see the
  // LOOKAHEAD comment below) — and on iPad Safari in particular, timer
  // callbacks queued behind that work fire far less consistently than on
  // desktop. A Worker's timers run on their own OS thread with their own
  // event loop, so they keep firing on schedule no matter how busy the
  // main thread's render work is; the worker just pings us and the actual
  // (cheap) scheduling call still happens here. This is the standard fix
  // for Web-Audio-timing-vs-busy-main-thread jank (see Chris Wilson's "A
  // Tale of Two Clocks"). If Workers/Blobs aren't available for some
  // reason, we fall back to the old plain setInterval so nothing breaks.
  startTicker() {
    try {
      const workerSrc = 'setInterval(() => postMessage(1), 25);';
      const blob = new Blob([workerSrc], { type: 'application/javascript' });
      const worker = new Worker(URL.createObjectURL(blob));
      worker.onmessage = () => this.pump();
      this._tickWorker = worker;
    } catch (e) {
      setInterval(() => this.pump(), 25);
    }
  },

  // iPadOS/iOS Safari will silently drop an AudioContext into 'suspended'
  // (backgrounding, multitasking transitions, some low-power situations)
  // without the game doing anything to cause it. A suspended context just
  // stops producing sound entirely rather than glitching, but resuming
  // proactively whenever the tab/page becomes active again means the
  // player never has to notice or work around it.
  installResumeGuards() {
    const tryResume = () => { if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume(); };
    document.addEventListener('visibilitychange', tryResume);
    window.addEventListener('focus', tryResume);
    window.addEventListener('pageshow', tryResume);
  },
  toggleMute() {
    if (!this.ctx) return;
    this.muted = !this.muted;
    this.master.gain.value = this.muted ? 0 : 0.28;
    toast = { text: this.muted ? 'Music: MUTED' : 'Music: ON', t: 1.2 };
  },
  // Returns (creating if needed) the layer Set for a given world id. Starts
  // empty -- a world is silent until the player finds a record that unlocks
  // one of its sampler layers (drums/bass/horns/vox/lead).
  layersFor(worldId) {
    return this.layersByWorld[worldId] || (this.layersByWorld[worldId] = new Set());
  },
  enable(layer) { this.layersFor(currentWorldId()).add(layer); },
  setMenuBreak(on) { this.menuDusty = on; },
  // Fully silences the background music bus (independent of the M-key
  // mute toggle) for rooms like Rico's Beat Lab where the player needs to
  // actually hear the sampler/drum-pad audio they're triggering, not have
  // it fight the ambient town loop. The scheduler keeps running underneath
  // -- only the output is silenced -- so the beat picks back up in perfect
  // sync, at the right volume, the moment the player steps back out.
  duck(on) {
    this.ducked = on;
    if (this.duckGain) this.duckGain.gain.value = on ? 0 : 1;
  },
  crackle(t, s, stepDur) {
    const src = this.ctx.createBufferSource(); src.buffer = this.noiseBuf;
    const f = this.ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 2800;
    const g = this.ctx.createGain();
    const pop = (s % 4 === 3); // occasional louder vinyl pop
    const gain = pop ? 0.05 : 0.016;
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + (pop ? 0.05 : stepDur * 0.6));
    src.connect(f); f.connect(g); g.connect(this.master);
    src.start(t); src.stop(t + (pop ? 0.06 : stepDur));
  },

  // How far ahead of real audio time we keep notes scheduled. The outdoor
  // town map draws a lot more per frame than an interior (fountain, jazz
  // banner, wall painter, parked cars, newsstands, etc. all redrawn from
  // scratch every frame), so main-thread frames/GC pauses run noticeably
  // longer there than indoors. If a stall outlasts this buffer, playback
  // runs dry and you hear a glitch/stutter — so this needs enough margin
  // to comfortably absorb outdoor-map frame spikes, not just indoor ones.
  //
  // This used to be 0.9s, which is plenty for a handful of slow frames but
  // not for a sustained run of heavy outdoor frames (or a GC pause) — once
  // real time ate into the buffer, `nextTime` could end up behind (or only
  // just ahead of) ctx.currentTime. Web Audio clamps any start time that has
  // already passed to "now", so several queued steps would all fire at once
  // — that's the burst/glitch you hear right when you step outside. Bumping
  // this up gives a much bigger cushion before that can happen at all.
  LOOKAHEAD: 2.0,
  // Minimum gap we insist a scheduled note sits ahead of real audio time.
  // Even with a big LOOKAHEAD, the *last* step scheduled in a catch-up pass
  // could still land within a few ms of "now" — this margin guarantees every
  // note is genuinely in the future, so nothing gets clamped and doubled up.
  MIN_MARGIN: 0.06,

  pump() {
    if (this.ctx.state === 'suspended') this.ctx.resume();
    // Each world sets its own tempo via WORLD_DEFS.<id>.beat.bpm (see the
    // worlds & records section above) -- falls back to the classic 92 BPM
    // default if a world hasn't defined a beat yet.
    const bpm = (worldDef().beat && worldDef().beat.bpm) || this.BPM;
    const stepDur = 60 / bpm / 4;
    const now = this.ctx.currentTime;
    // If something stalled the main thread for a long stretch (tab backgrounded,
    // a very long GC pause, etc.), don't dump a burst of overdue notes all at
    // once — resync onto the next clean beat boundary and carry on from there,
    // silently (no note is scheduled for the missed span, rather than cramming
    // several into the same instant). This should only trigger for genuinely
    // extreme stalls, well beyond LOOKAHEAD, so ordinary outdoor-map frame
    // jank gets absorbed by the buffer instead of resyncing.
    if (this.nextTime < now - this.LOOKAHEAD) {
      const stepsPerBeat = 4;
      const beatDur = stepDur * stepsPerBeat;
      const beatsAhead = Math.ceil((now + this.MIN_MARGIN - this.nextTime) / beatDur);
      this.step = (this.step + beatsAhead * stepsPerBeat) % 32;
      this.nextTime += beatsAhead * beatDur;
    }
    // Scheduled well ahead of real time (not just ~1 frame) so a slow
    // render frame in the busy outdoor map can't cause the scheduler to
    // fall behind and produce audible stutter/catch-up bursts. Every step
    // is also clamped to MIN_MARGIN ahead of "now" so a long catch-up pass
    // can never schedule two steps close enough together to sound doubled.
    while (this.nextTime < now + this.LOOKAHEAD) {
      const t = Math.max(this.nextTime, now + this.MIN_MARGIN);
      this.schedule(this.step, t, stepDur);
      this.step = (this.step + 1) % 32;
      this.nextTime += stepDur;
    }
  },
  schedule(gs, t, stepDur) {
    const s = gs % 16;
    // old, dusty vinyl drum break while on the title screen -- fixed and
    // world-independent on purpose, since no world is actually "current"
    // yet at the title screen.
    if (this.menuDusty) {
      if ([0, 7, 10].includes(s)) this.kick(t);
      if (s === 4 || s === 12) this.snare(t);
      if (s % 2 === 0) this.hat(t, s === 14, 0.10);
      this.crackle(t, s, stepDur);
      return;
    }
    const bar = Math.floor(gs / 16);
    const worldId = currentWorldId();
    const L = this.layersFor(worldId);
    // Nothing unlocked in this world yet -> schedule nothing at all, so no
    // audio nodes are created and the output stays truly silent.
    if (L.size === 0) return;
    // Falls back to town's beat if a world hasn't defined one yet, same
    // spirit as worldDef()'s own `|| WORLD_DEFS.town` fallback.
    const beat = worldDef().beat || WORLD_DEFS.town.beat;
    if (L.has('drums')) {
      if (beat.kickSteps.includes(s)) this.kick(t);
      if (beat.snareSteps.includes(s)) this.snare(t);
      if (s % 2 === 0) this.hat(t, s === beat.hatOpenStep, 0.10);
    }
    // (No baseline "tick" hat any more: with zero sample layers unlocked the
    // music bus is now completely silent. That quiet metronome-style click
    // was the only thing playing before the first record was found.)
    if (L.has('bass')) {
      for (const [ps, n, d] of beat.bassPattern)
        if (ps === s) this.note(t, beat.bassWave, n, d * stepDur, 0.10);
    }
    if (L.has('horns') && beat.hornSteps.includes(s)) {
      for (const n of beat.hornNotes) this.note(t, beat.hornWave, n, 1.4 * stepDur, 0.05, 0.03);
    }
    if (L.has('vox') && beat.voxSteps.includes(s)) {
      const notes = bar % 2 === 0 ? beat.voxNotesEven : beat.voxNotesOdd;
      this.note(t, beat.voxWave, notes[s === beat.voxSteps[0] ? 0 : 1], 7.5 * stepDur, 0.07, 0.25, true);
    }
    if (L.has('lead') && bar % 2 === 1 && s % 2 === 0) {
      this.note(t, beat.leadWave, beat.leadNotes[s / 2], 1.6 * stepDur, 0.045, 0.02);
    }
  },
  kick(t) {
    const o = this.ctx.createOscillator(), g = this.ctx.createGain();
    o.frequency.setValueAtTime(130, t);
    o.frequency.exponentialRampToValueAtTime(42, t + 0.12);
    g.gain.setValueAtTime(0.55, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.15);
    o.connect(g); g.connect(this.master);
    o.start(t); o.stop(t + 0.16);
  },
  snare(t) {
    const src = this.ctx.createBufferSource(); src.buffer = this.noiseBuf;
    const f = this.ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = 1900;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.3, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.12);
    src.connect(f); f.connect(g); g.connect(this.master);
    src.start(t); src.stop(t + 0.13);
  },
  hat(t, open, gain) {
    const src = this.ctx.createBufferSource(); src.buffer = this.noiseBuf;
    const f = this.ctx.createBiquadFilter(); f.type = 'highpass'; f.frequency.value = 7500;
    const g = this.ctx.createGain();
    const dur = open ? 0.22 : 0.045;
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    src.connect(f); f.connect(g); g.connect(this.master);
    src.start(t); src.stop(t + dur + 0.01);
  },
  note(t, type, midi, dur, gain, release = 0.02, vibrato = false) {
    const o = this.ctx.createOscillator(), g = this.ctx.createGain();
    o.type = type;
    o.frequency.value = 440 * Math.pow(2, (midi - 69) / 12);
    if (vibrato) {
      const lfo = this.ctx.createOscillator(), lg = this.ctx.createGain();
      lfo.frequency.value = 5.2; lg.gain.value = 7;
      lfo.connect(lg); lg.connect(o.detune);
      lfo.start(t); lfo.stop(t + dur + release);
    }
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(gain, t + 0.015);
    g.gain.setValueAtTime(gain, t + dur);
    g.gain.exponentialRampToValueAtTime(0.001, t + dur + release);
    o.connect(g); g.connect(this.master);
    o.start(t); o.stop(t + dur + release + 0.02);
  },
  sting() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + 0.05;
    [69, 73, 76, 81].forEach((n, i) => this.note(t + i * 0.09, 'square', n, 0.14, 0.09, 0.08));
  },
  // [T] Turbo Taunt sparkle cue -- a quick, tiny ascending chime, distinct
  // from (and much shorter than) sting() so it reads as a light flourish
  // rather than the bigger "moment" sting() is used for elsewhere.
  trickChime() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + 0.02;
    [76, 81, 86].forEach((n, i) => this.note(t + i * 0.045, 'square', n, 0.08, 0.055, 0.05));
  },
};

// Rico's Beat Lab ('lab'/'labApp' game states -- the instrument-picker
// popup and the instrument iframe it opens, both reached only via
// checkLabDoor()) is the one place the ambient town music should be
// ducked out, so the player can hear the sampler/drum-pad audio without
// it fighting the background loop. No shop interior (including Green
// Door Studio, map id 'groove') ducks -- every building should sound
// like every other one, with the full music + sfx bus always audible.
//
// This is recalculated from `state` every frame in update() (see
// syncMusicDuck() below) rather than toggled at individual
// enter/exit call sites, so it can't drift out of sync no matter which
// of the several ways the player backs out of the lab popup (keyboard
// [X], on-screen [X] button, closing the instrument iframe, etc.).
const DUCKED_STATES = new Set(['lab', 'labApp', 'chessApp', 'sunnySideDinerApp', 'beatBotApp', 'organApp', 'minigolfApp', 'blackbookApp', 'crocSwampApp', 'qsdBalanceApp', 'vinylSnakeApp', 'waveformApp', 'bayouBreakApp', 'freqAltarApp', 'reverbReefApp', 'beatBrewingApp', 'drumPatternDocApp', 'gatorJamSlamApp', 'swampCaveApp', 'vocalChopBoothApp', 'vtDirtApp', 'penaltyKingsApp', 'digDashApp', 'digOnApp', 'rico1200App', 'ricoDawApp', 'filterLabApp', 'characterIntro', 'vinylNinjaApp', 'diggerApp', 'johnnySlidesApp', 'humbleTreasuresApp', 'dustRacingApp', 'cbPressApp', 'spotDiffApp', 'guitarApp', 'hyperSwimApp', 'linusTugApp', 'connectFourApp', 'syrupRoadsApp', 'scoopBeatsApp', 'clawMachineApp', 'kangaidenVideo', 'kangaidenApp', 'hiphopLibraryApp', 'arkaiikImpactApp', 'precisionPointsApp', 'wishJamApp', 'skateHipHopReaderApp', 'travSkatesApp', 'j2sProSkaterApp', 'danceParty', 'truthKnocksVideo', 'truthKnocksApp', 'johnnySlidesVideo', 'humbleTreasuresVideo']);
function syncMusicDuck() {
  const minigameDucked = state === 'minigame' && activeMinigame && activeMinigame.musicDucked;
  music.duck(DUCKED_STATES.has(state) || !!minigameDucked);
}

// ---------------------------------------------------------------- movement
function isSolid(map, tx, ty) {
  if (tx < 0 || ty < 0 || tx >= map.w || ty >= map.h) return true;
  return SOLID.has(map.grid[ty][tx]);
}

function boxClear(map, cx, cy) {
  const hw = 10, hh = 7;
  const pts = [[cx-hw, cy-hh], [cx+hw, cy-hh], [cx-hw, cy+hh], [cx+hw, cy+hh]];
  return pts.every(([px, py]) => !isSolid(map, Math.floor(px / TILE), Math.floor(py / TILE)));
}

function movePlayer(dt) {
  const [dx, dy] = axis();
  player.moving = dx !== 0 || dy !== 0;
  if (!player.moving) return;

  if (dy < 0) player.dir = 'up';
  else if (dy > 0) player.dir = 'down';
  else if (dx < 0) player.dir = 'left';
  else if (dx > 0) player.dir = 'right';

  const map = maps[player.map];
  const baseSpeed = player.skating ? SKATE_SPEED : WALK_SPEED;
  const speed = (player.holdingCoffee || player.holdingTea) ? baseSpeed * 1.15 : baseSpeed;
  const mag = Math.hypot(dx, dy) || 1;
  const stepX = (dx / mag) * speed * dt;
  const stepY = (dy / mag) * speed * dt;

  if (boxClear(map, player.x + stepX, player.y)) player.x += stepX;
  if (boxClear(map, player.x, player.y + stepY)) player.y += stepY;
  player.animT += dt * (player.skating ? 1.4 : 1);

  const tk = player.map + ':' + key(Math.floor(player.x / TILE), Math.floor(player.y / TILE));
  const tr = transitions[tk];
  if (tr) {
    player.map = tr.map;
    player.x = tr.x * TILE;
    player.y = tr.y * TILE;
    if (!maps[tr.map].outside) player.skating = false;
    saveGame(); // silent autosave checkpoint -- keeps "Continue" accurate to the room the player is in
  }

  checkPortal(map);
  checkSwampPortal(map);
  checkLabDoor(map);
  checkShopBackDoor(map);
}

// Placeholder portal doors: walking onto a 'P' tile pops the "more lands
// coming" splash instead of an actual map transition. Records which tile
// was entered so closing the popup can nudge the player back off of it —
// otherwise standing still on the tile would reopen the popup every frame.
function checkPortal(map) {
  const tx = Math.floor(player.x / TILE), ty = Math.floor(player.y / TILE);
  if (map.grid[ty] && map.grid[ty][tx] === 'P') {
    activePortal = { x: tx, y: ty };
    state = 'portal';
  }
}

// The real, working portal between town and THE SWAMP (LEVEL 2) -- a 'Q'
// tile on both ends. Walking onto it in town shows the full-screen "LEVEL 2"
// splash (showLevelIntro(), same treatment Level 1 gets on a fresh game)
// before dropping the player into the swamp, just off the return portal on
// its west edge. Walking onto it in the swamp sends the player straight
// back to town, right below the north portal -- no splash needed for the
// return trip, same as every other door-to-door transition in the game.
// Both directions are fully local/offline: showLevelIntro() only swaps in
// level2IntroImg (already loaded as a same-origin local asset) and flips
// `state`, no network involved.
function checkSwampPortal(map) {
  const tx = Math.floor(player.x / TILE), ty = Math.floor(player.y / TILE);
  if (!(map.grid[ty] && map.grid[ty][tx] === 'Q')) return;
  if (map.id === 'town') {
    showLevelIntro('swamp', () => {
      const rp = maps.swamp.returnPortal;
      player.map = 'swamp';
      player.x = (rp.x + 1.5) * TILE; // one tile east of the return portal, off the 'Q' tile
      player.y = (rp.y + 0.5) * TILE;
      state = 'play';
      saveGame(); // silent autosave checkpoint, same as every ordinary door transition
    });
  } else if (map.id === 'swamp') {
    player.map = 'town';
    player.x = 19.5 * TILE;
    player.y = 1.6 * TILE; // one tile south of the town portal, same push-off-the-door offset every other transition uses
    saveGame();
  }
}

// Rico's Lab door: walking onto an 'L' tile opens the instrument picker
// once every record in town has been found (worldComplete()/completedWorlds
// only track the world the player is *currently* standing in, but the lab
// door only ever lives on the town map, so checking 'town' directly here is
// safe and keeps this working even if the player somehow reaches it from
// another world later). Before that, it just pops a "locked" popup — same
// activeLabDoor-records-the-tile trick as checkPortal() above so closing
// either popup can nudge the player back off the doorway.
function checkLabDoor(map) {
  const tx = Math.floor(player.x / TILE), ty = Math.floor(player.y / TILE);
  if (map.grid[ty] && map.grid[ty][tx] === 'L') {
    activeLabDoor = { x: tx, y: ty };
    state = completedWorlds.has('town') ? 'lab' : 'labLocked';
    if (state === 'lab') labIndex = 0;
  }
}

// A shop's own locked "back room" door (see makeShop()'s backDoorTile opt
// and SHOP_BACK_ROOMS above): walking onto its 'B' tile steps straight into
// the back room once that shop's world is fully swept (completedWorlds has
// it), same as any ordinary door -- just gated. Before that, it pops a
// "locked" popup -- same activeShopBackDoor-records-the-tile trick as
// checkPortal()/checkLabDoor() above.
function checkShopBackDoor(map) {
  if (!map.backDoorTile) return;
  const tx = Math.floor(player.x / TILE), ty = Math.floor(player.y / TILE);
  if (map.grid[ty] && map.grid[ty][tx] === 'B') {
    if (completedWorlds.has(map.world)) {
      const dest = SHOP_BACK_ROOMS[map.id];
      player.map = dest.room;
      player.x = 6.5 * TILE;
      player.y = 7.5 * TILE;
      saveGame(); // silent autosave checkpoint, same as every ordinary door transition
    } else {
      activeShopBackDoor = { x: tx, y: ty };
      state = 'shopBackLocked';
    }
  }
}

// Shared by the 'portal'/'lab'/'labLocked' popups: nudges the player one
// tile back off whichever edge door they just walked into, so standing
// still on the doorway doesn't immediately reopen the popup the instant it
// closes. Works for any of the four map edges the door might sit on.
function pushOffDoor(map, doorTile) {
  let pushX = 0, pushY = 0;
  if (doorTile.x === 0) pushX = 1;
  else if (doorTile.x === map.w - 1) pushX = -1;
  else if (doorTile.y === 0) pushY = 1;
  else if (doorTile.y === map.h - 1) pushY = -1;
  player.x = (doorTile.x + pushX + 0.5) * TILE;
  player.y = (doorTile.y + pushY + 0.5) * TILE;
}

// ---------------------------------------------------------------- interact
// Vendor carts are cosmetic sprites (drawn in drawTownDecorations), not part
// of the tile grid, so they're detected by standing near a point in front of
// the counter rather than by facing a specific tile.
const VENDOR_CARTS = [
  // coffee cart just outside Pure Pop Records
  { id: 'coldbrew', map: 'town', label: 'BUY A COLD BREW', x: 27 * TILE + 5 + 28, y: 18 * TILE + 4 + 40, radius: 42 },
  // ice cream van tucked in town's lower-right corner
  { id: 'icecream', map: 'town', label: 'BUY ICE CREAM', x: 35.2 * TILE + 46, y: 21.4 * TILE + 63, radius: 46 },
  // Swamp Juice cart -- set up on open ground just west of GUT HUT (tile
  // 23,20), clear of the building (25-30,15-18), its door push-out tile
  // (28,19), and the TRUTH LAB clearing further west (10-19,13-24). Same
  // "cart_x + half its drawn width, cart_y + an offset below it"
  // interaction-point pattern as the cold brew cart above -- the base
  // 23*TILE+4, 20*TILE+2 here matches the top-left corner drawSwampJuiceCart()
  // draws from below.
  { id: 'swampjuice', map: 'swamp', label: 'BUY SWAMP JUICE', x: 23 * TILE + 4 + 27, y: 20 * TILE + 2 + 40, radius: 42 },
  // TACO TRUCK ALL STARS -- skatepark, east of the plaza ring. The truck
  // fills tiles (46-50, 20-22); its serving window is ~21px in from the
  // truck's left edge, so the buy point is that far in from tile 46, just
  // below the truck's bottom edge (row 23) -- see drawTacoTruck().
  { id: 'tacotruck', map: 'skatepark', label: 'BUY A TACO', x: 46 * TILE + 21, y: 23 * TILE + 26, radius: 46 },
];

function facingTile() {
  const d = { up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0] }[player.dir];
  const fx = player.x + d[0] * 24, fy = player.y + d[1] * 22;
  return [Math.floor(fx / TILE), Math.floor(fy / TILE)];
}

function facingTarget() {
  const map = maps[player.map];
  const [tx, ty] = facingTile();
  if (tx >= 0 && ty >= 0 && tx < map.w && ty < map.h) {
    const ch = map.grid[ty][tx];
    if (ch === 'C' || ch === 'c') return { type: 'crate', tx, ty, data: map.crates[key(tx, ty)] };
    if (ch === 'K') return { type: 'keeper', data: map.keeper };
    if (ch === 'T' && map.keeper && Math.abs(tx - map.keeper.x) <= 2 && ty === map.keeper.y + 1)
      return { type: 'keeper', data: map.keeper };
    if (ch === 'J') return { type: 'jukebox' };
    if (ch === 'Z') return { type: 'filingCabinets' };
    if (map.npcs) {
      const np = map.npcs.find(n => n.tx === tx && n.ty === ty);
      if (np) return { type: 'npc', data: np };
    }
    if (map.newsstands) {
      const ns = map.newsstands.find(n => n.tx === tx && n.ty === ty);
      if (ns) return { type: 'newspaper', data: ns };
    }
    if (map.minigames) {
      // `alsoTiles` lets one mini-game answer to extra neighboring tiles
      // (e.g. the two-tile-wide CB PRINTS press) without drawing a second sign.
      const mg = map.minigames.find(m => (m.tx === tx && m.ty === ty) ||
        (m.alsoTiles && m.alsoTiles.some(t => t[0] === tx && t[1] === ty)));
      if (mg) return { type: 'minigame', data: mg };
    }
  }
  const cart = VENDOR_CARTS.find(c => c.map === player.map &&
    Math.hypot(player.x - c.x, player.y - c.y) < c.radius);
  if (cart) return { type: 'cart', data: cart };
  return null;
}

function doInteract() {
  const target = facingTarget();
  if (!target) return;
  if (target.type === 'keeper') {
    const k = target.data;
    const shopRecord = Object.values(maps[player.map].crates).find(c => c.record)?.record;
    const lines = shopRecord && collected.has(recKey(currentWorldId(), shopRecord)) ? [k.foundLine] : resolveLines(k.lines);
    // Always give good Ol' Linus a pet: every time the player walks up to
    // him he gets petted (hearts float over his head, see drawKeeper()) and
    // the last line of the chat is the pet itself.
    if (k.name === 'LINUS') {
      k.petUntil = performance.now() + 3000;
      lines.push('*You give Linus a good pet.* He leans right into it. Best boy in the swamp.');
    }
    dialog = { name: k.name, lines, i: 0 };
    state = 'dialog';
  } else if (target.type === 'crate') {
    const c = target.data;
    if (!c) return;
    if (c.record && !collected.has(recKey(currentWorldId(), c.record))) {
      collected.add(recKey(currentWorldId(), c.record));
      music.enable(worldRecords()[c.record].layer);
      music.sting();
      shownRecord = c.record;
      state = 'record';
      saveGame(); // silent autosave checkpoint
    } else if (c.record) {
      dialog = { name: 'CRATE', lines: ['Nothing left in here but dust and old sleeves.'], i: 0 };
      state = 'dialog';
    } else if (c.comedySeed !== undefined) {
      dialog = { name: 'CRATE', lines: [COMEDY_JUNK[c.comedySeed % COMEDY_JUNK.length], 'Keep digging...'], i: 0 };
      state = 'dialog';
    } else if (c.pizzaSeed !== undefined) {
      dialog = { name: 'CRATE', lines: [PIZZA_JUNK[c.pizzaSeed % PIZZA_JUNK.length], 'Good vibes, but not what you\'re digging for.'], i: 0 };
      state = 'dialog';
    } else if (c.nectarsSeed !== undefined) {
      const nj = NECTARS_JUNK[c.nectarsSeed % NECTARS_JUNK.length];
      dialog = { name: 'CRATE', lines: [nj.line, nj.reply], i: 0 };
      state = 'dialog';
    } else if (c.henrysSeed !== undefined) {
      const hj = HENRYS_JUNK[c.henrysSeed % HENRYS_JUNK.length];
      dialog = { name: 'CRATE', lines: [hj.line, hj.reply], i: 0 };
      state = 'dialog';
    } else if (c.truthLabSeed !== undefined) {
      const tj = TRUTHLAB_JUNK[c.truthLabSeed % TRUTHLAB_JUNK.length];
      dialog = { name: 'CRATE', lines: [tj.line, tj.reply], i: 0 };
      state = 'dialog';
    } else if (c.streisandSeed !== undefined) {
      const sj = STREISAND_JUNK[c.streisandSeed % STREISAND_JUNK.length];
      dialog = { name: 'CRATE', lines: [sj.line, sj.reply], i: 0 };
      state = 'dialog';
    } else if (c.soulShackSeed !== undefined) {
      const ssj = SOUL_SHACK_JUNK[c.soulShackSeed % SOUL_SHACK_JUNK.length];
      dialog = { name: 'CRATE', lines: [ssj.line, ssj.reply], i: 0 };
      state = 'dialog';
    } else if (c.skateShopSeed !== undefined) {
      const ksj = SKATE_SHOP_JUNK[c.skateShopSeed % SKATE_SHOP_JUNK.length];
      dialog = { name: 'CRATE', lines: [ksj.line, ksj.reply], i: 0 };
      state = 'dialog';
    } else if (c.foamSeed !== undefined) {
      const fj = FOAM_JUNK[c.foamSeed % FOAM_JUNK.length];
      dialog = { name: 'CRATE', lines: [fj.line, fj.reply], i: 0 };
      state = 'dialog';
    } else if (c.svSeed !== undefined) {
      const svj = SPEAKING_VOLUMES_JUNK[c.svSeed % SPEAKING_VOLUMES_JUNK.length];
      dialog = { name: 'CRATE', lines: [svj.line, svj.reply], i: 0 };
      state = 'dialog';
    } else if (c.echoSeed !== undefined) {
      // ECHO CENTER: the crate's SPOT picks its theme (Shallows / Deep Sea /
      // Reef), since the real record gets shuffled between spots each game
      const echoList = ECHO_CENTER_JUNK[ECHO_CENTER_CRATE_THEMES[target.tx + ',' + target.ty] || 'shallows'];
      const ecj = echoList[Math.floor(Math.random() * echoList.length)];
      dialog = { name: 'CRATE', lines: [ecj.line, ecj.reply], i: 0 };
      state = 'dialog';
    } else if (c.talentSeed !== undefined) {
      const tlj = TALENT_JUNK[c.talentSeed % TALENT_JUNK.length];
      dialog = { name: 'CRATE', lines: [tlj.line, tlj.reply], i: 0 };
      state = 'dialog';
    } else if (c.cbSeed !== undefined) {
      // CB PRINTS: left-hand crate (x < 7) is hip hop, right-hand is reggae
      const cbList = CB_PRINTS_JUNK[target.tx < 7 ? 'hiphop' : 'reggae'];
      const cbj = cbList[Math.floor(Math.random() * cbList.length)];
      dialog = { name: 'CRATE', lines: [cbj.line, cbj.reply], i: 0 };
      state = 'dialog';
    } else {
      dialog = { name: 'CRATE', lines: [JUNK[c.junkSeed % JUNK.length], 'Keep digging...'], i: 0 };
      state = 'dialog';
    }
  } else if (target.type === 'jukebox') {
    dialog = { name: 'JUKEBOX', lines: ['B7: "Cherry Cola Bounce". The button is worn smooth from decades of plays.'], i: 0 };
    state = 'dialog';
  } else if (target.type === 'filingCabinets') {
    dialog = { name: 'FILING CABINETS', lines: [
      'Of course the files you actually need are jammed in the very top drawer.',
      'No ladder. No stairs. Not even a stray milk crate to stand on. How is anybody supposed to get up there?',
      'You circle the whole stack twice and come away no closer to an answer.'
    ], i: 0 };
    state = 'dialog';
  } else if (target.type === 'npc') {
    const n = target.data;
    dialog = { name: n.name, lines: resolveLines(n.lines), i: 0 };
    state = 'dialog';
  } else if (target.type === 'newspaper') {
    // swamp newsstands carry the local swamp-themed paper; every other
    // outdoor map still gets the town's Green Mountain Bugle.
    const swamp = maps[player.map] && maps[player.map].swamp;
    const paperName = swamp ? SWAMP_NEWS_PAPER : VERMONT_NEWS_PAPER;
    const stories = swamp ? SWAMP_NEWS : VERMONT_NEWS;
    const story = stories[Math.floor(Math.random() * stories.length)];
    dialog = { name: paperName, lines: [story.headline, story.body], i: 0 };
    state = 'dialog';
  } else if (target.type === 'minigame') {
    const start = MINIGAME_ACTIONS[target.data.id];
    if (start) start();
  }
}

// Buying from a vendor cart pops the item into Rico's hand for a few
// seconds, just like the other held items (cold brew / iced tea).
function doBuy() {
  if (state !== 'play') return;
  const target = facingTarget();
  if (!target || target.type !== 'cart') return;
  if (target.data.id === 'icecream') {
    player.tempItem = 'iceCream';
    player.tempItemTimer = 6;
    toast = { text: 'Ice Cream!', t: 1.2 };
  } else if (target.data.id === 'coldbrew') {
    player.tempItem = 'coldBrew';
    player.tempItemTimer = 6;
    toast = { text: 'Cold Brew!', t: 1.2 };
  } else if (target.data.id === 'swampjuice') {
    player.tempItem = 'swampJuice';
    player.tempItemTimer = 6;
    toast = { text: 'Swamp Juice!', t: 1.2 };
  } else if (target.data.id === 'tacotruck') {
    // held for 6 seconds, then the update loop clears it (tempItemTimer)
    player.tempItem = 'taco';
    player.tempItemTimer = 6;
    toast = { text: 'Taco!', t: 1.2 };
  }
}

// ---------------------------------------------------------------- ambient town life (people, bikes, dogs, fish)
const ambient = [];
const ambientTimers = { bike: 4, walker: 3, dog: 6, fish: 2, gator: 5, snake: 6, frog: 4 };

function updateAmbient(dt) {
  const map = maps[player.map];
  const amb = map && map.ambient;
  if (!amb) { if (ambient.length) ambient.length = 0; return; }

  ambientTimers.bike -= dt;
  if (ambientTimers.bike <= 0) { spawnBike(map); ambientTimers.bike = 7 + Math.random() * 9; }
  ambientTimers.walker -= dt;
  if (ambientTimers.walker <= 0) { spawnWalker(map); ambientTimers.walker = 5 + Math.random() * 8; }
  ambientTimers.dog -= dt;
  if (ambientTimers.dog <= 0) { spawnDog(map); ambientTimers.dog = 9 + Math.random() * 10; }
  ambientTimers.fish -= dt;
  if (ambientTimers.fish <= 0 && map.riverTiles && map.riverTiles.length) {
    spawnFish(map); ambientTimers.fish = 2 + Math.random() * 3;
  }
  // Swamp-only critters -- each spawn helper checks its own map.ambient
  // flag and no-ops if the current map doesn't set it, same pattern as
  // spawnBike/spawnDog above, so this is a no-op on every non-swamp map.
  ambientTimers.gator -= dt;
  if (ambientTimers.gator <= 0) { spawnGator(map); ambientTimers.gator = 9 + Math.random() * 8; }
  ambientTimers.snake -= dt;
  if (ambientTimers.snake <= 0) { spawnSnake(map); ambientTimers.snake = 8 + Math.random() * 9; }
  ambientTimers.frog -= dt;
  if (ambientTimers.frog <= 0) { spawnFrog(map); ambientTimers.frog = 6 + Math.random() * 7; }

  for (let i = ambient.length - 1; i >= 0; i--) {
    const a = ambient[i];
    a.t += dt;
    if (a.type === 'fish') {
      if (a.t > a.life) ambient.splice(i, 1);
      continue;
    }
    if (a.type === 'gator') {
      // slow horizontal drift, then submerges (despawns) after `life`
      // seconds rather than crossing the whole map -- keeps it from
      // gliding over mud islands it has no business being on top of
      a.x += a.vx * dt;
      if (a.t > a.life) ambient.splice(i, 1);
      continue;
    }
    if (a.type === 'frog') {
      // hops vertically up/down its boardwalk spur instead of the usual
      // horizontal drift
      a.y += a.vy * dt;
      if (a.y < a.minY - 20 || a.y > a.maxY + 20) ambient.splice(i, 1);
      continue;
    }
    a.x += a.vx * dt;
    if (a.x < -50 || a.x > map.w * TILE + 50) ambient.splice(i, 1);
  }
}

// Spawn helpers now read from the current map, so any overworld with an
// `ambient` config gets its own life without hardcoding 'town'.
function spawnBike(map) {
  const amb = map.ambient || {};
  const rows = amb.bikeRows;
  if (!rows || !rows.length) return;   // no bike lanes -> no bikes
  const dir = Math.random() < 0.5 ? 1 : -1;
  const row = rows[Math.floor(Math.random() * rows.length)];
  ambient.push({ type: 'bike', x: dir > 0 ? -30 : map.w * TILE + 30, y: row * TILE + 16, vx: dir * 115, dir, t: 0 });
}
function spawnWalker(map) {
  const amb = map.ambient || {};
  const dir = Math.random() < 0.5 ? 1 : -1;
  const shirts = ['#c86a3a', '#4a7ab0', '#7a4a9a', '#3a9a5a', '#c2a23a', '#3a8a8a'];
  const skins = ['#b87954', '#8a5a34', '#d8a878', '#e8c8a0'];
  const hairs = ['#2a2018', '#4a3020', '#6a4020', '#8a8a8a', '#c8a860'];
  const backpacks = ['#4a5a3a', '#8a4030', '#2a3a5a'];
  const row = amb.walkerRow !== undefined ? amb.walkerRow : 12;
  if (row < 0) return;                  // no walker lane -> no walkers
  const shirt = shirts[Math.floor(Math.random() * shirts.length)];
  ambient.push({
    type: 'walker', x: dir > 0 ? -20 : map.w * TILE + 20, y: row * TILE + 24,
    vx: dir * 44, dir, t: 0,
    shirt, shirtDark: shadeColor(shirt, -45), shirtLight: shadeColor(shirt, 40),
    skin: skins[Math.floor(Math.random() * skins.length)],
    pants: '#3a3a46', shoe: '#241c18',
    hair: hairs[Math.floor(Math.random() * hairs.length)],
    backpack: Math.random() < 0.35 ? backpacks[Math.floor(Math.random() * backpacks.length)] : null,
  });
}
function spawnDog(map) {
  const amb = map.ambient || {};
  const dir = Math.random() < 0.5 ? 1 : -1;
  const row = amb.dogRow !== undefined ? amb.dogRow : 23;
  if (row < 0) return;                  // no dog lane -> no dogs
  const furs = ['#a9713f', '#3a2e26', '#e8d8b8', '#8a5a34'];
  const fur = furs[Math.floor(Math.random() * furs.length)];
  ambient.push({
    type: 'dog', x: dir > 0 ? -20 : map.w * TILE + 20, y: row * TILE + 20, vx: dir * 58, dir, t: 0,
    fur, furDark: shadeColor(fur, -40), furLight: shadeColor(fur, 35),
  });
}
function spawnFish(map) {
  const tile = map.riverTiles[Math.floor(Math.random() * map.riverTiles.length)];
  ambient.push({
    type: 'fish',
    x: tile.x * TILE + 10 + Math.random() * 12,
    y: tile.y * TILE + 10 + Math.random() * 12,
    t: 0, life: 1 + Math.random() * 0.8,
  });
}

// Gator: surfaces at a random water tile, drifts slowly for a few seconds,
// then submerges again. Deliberately short-range and slow (unlike
// bike/dog/snake's full cross-map traversal) since the swamp's water isn't
// one clear lane -- it's broken up by mud islands, so a gator that tried to
// swim the width of the map would end up gliding over dry ground partway
// through. Reuses map.riverTiles, the same water-tile list spawnFish uses.
function spawnGator(map) {
  const amb = map.ambient || {};
  if (!amb.gator || !map.riverTiles || !map.riverTiles.length) return;
  const tile = map.riverTiles[Math.floor(Math.random() * map.riverTiles.length)];
  const dir = Math.random() < 0.5 ? 1 : -1;
  ambient.push({
    type: 'gator', x: tile.x * TILE + 6, y: tile.y * TILE + 10,
    vx: dir * 13, dir, t: 0, life: 3.5 + Math.random() * 2.5,
  });
}

// Snake: slithers the full width of the boardwalk trunk (row 12 on the
// swamp map), the one row guaranteed to be clear, walkable ground across
// the entire map -- same "spawn off one edge, drift to the other" shape as
// spawnBike/spawnDog above, just slower and on a different lane.
function spawnSnake(map) {
  const amb = map.ambient || {};
  const row = amb.snakeRow;
  if (row === undefined || row < 0) return;
  const dir = Math.random() < 0.5 ? 1 : -1;
  const bodies = ['#5a7a3a', '#7a6a26', '#3a5a4a', '#8a3a2a'];
  const body = bodies[Math.floor(Math.random() * bodies.length)];
  ambient.push({
    type: 'snake', x: dir > 0 ? -20 : map.w * TILE + 20, y: row * TILE + 24,
    vx: dir * 32, dir, t: 0,
    body, bodyDark: shadeColor(body, -35), bodyLight: shadeColor(body, 30),
  });
}

// Frog: hops up or down one of the two north-south boardwalk spurs
// (map.ambient.frogSpurs), rather than the horizontal drift every other
// ambient actor uses -- picked because the spurs are the only clear
// vertical lanes on the map, same reasoning as the snake's horizontal one.
function spawnFrog(map) {
  const amb = map.ambient || {};
  const spurs = amb.frogSpurs;
  if (!spurs || !spurs.length) return;
  const spur = spurs[Math.floor(Math.random() * spurs.length)];
  const dir = Math.random() < 0.5 ? 1 : -1;
  const skins = ['#4a8a3a', '#6a9a28', '#3a7a5a'];
  const skin = skins[Math.floor(Math.random() * skins.length)];
  ambient.push({
    type: 'frog', x: spur.col * TILE + 16,
    y: dir > 0 ? spur.y0 * TILE - 20 : spur.y1 * TILE + 20,
    vy: dir * 24, dir, t: 0,
    minY: spur.y0 * TILE, maxY: spur.y1 * TILE,
    skin, skinDark: shadeColor(skin, -35), skinLight: shadeColor(skin, 30),
  });
}

// Darken (negative percent) or lighten (positive percent) a '#rrggbb' color.
// Used to build the shadow/highlight tones for the layered pixel-art look.
function shadeColor(hex, amount) {
  const num = parseInt(hex.slice(1), 16);
  let r = (num >> 16) + amount;
  let g = ((num >> 8) & 0xff) + amount;
  let b = (num & 0xff) + amount;
  r = Math.max(0, Math.min(255, r));
  g = Math.max(0, Math.min(255, g));
  b = Math.max(0, Math.min(255, b));
  return '#' + (0x1000000 + r * 0x10000 + g * 0x100 + b).toString(16).slice(1);
}

function drawAmbient() {
  for (const a of ambient) {
    if (a.type === 'bike') drawBikeActor(a);
    else if (a.type === 'walker') drawWalkerActor(a);
    else if (a.type === 'dog') drawDogActor(a);
    else if (a.type === 'fish') drawFishActor(a);
    else if (a.type === 'gator') drawGatorActor(a);
    else if (a.type === 'snake') drawSnakeActor(a);
    else if (a.type === 'frog') drawFrogActor(a);
  }
}

function drawWheel(cx, cy, spin) {
  ctx.beginPath();
  ctx.arc(cx, cy, 7, 0, Math.PI * 2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(cx + Math.cos(spin) * 6, cy + Math.sin(spin) * 6);
  ctx.lineTo(cx - Math.cos(spin) * 6, cy - Math.sin(spin) * 6);
  ctx.stroke();
}

function drawBikeActor(a) {
  const flip = a.dir < 0;
  ctx.save();
  ctx.translate(a.x, a.y);
  if (flip) ctx.scale(-1, 1);
  const spin = a.t * 10;
  ctx.strokeStyle = '#1c1a20';
  ctx.lineWidth = 2;
  drawWheel(-10, 8, spin);
  drawWheel(10, 8, spin);
  ctx.strokeStyle = '#3f6fae';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(-10, 8); ctx.lineTo(0, -4); ctx.lineTo(10, 8);
  ctx.moveTo(0, -4); ctx.lineTo(-4, -12);
  ctx.stroke();
  ctx.fillStyle = '#d0703c';
  ctx.fillRect(-5, -20, 9, 10);
  ctx.fillStyle = '#b87954';
  ctx.fillRect(-4, -28, 7, 8);
  ctx.restore();
}

function drawWalkerActor(a) {
  const flip = a.dir < 0;
  ctx.save();
  ctx.translate(a.x, a.y);
  if (flip) ctx.scale(-1, 1);
  const stride = Math.sin(a.t * 8) * 3;
  const outline = '#1c140f';
  const backSwing = -stride * 0.4, frontSwing = stride * 0.4;

  // ground shadow
  ctx.fillStyle = 'rgba(0,0,0,0.25)';
  ctx.fillRect(-8, 14, 16, 4);

  // back leg (outline, then pants, then shoe)
  ctx.fillStyle = outline;
  ctx.fillRect(-6, 1 + backSwing, 6, 14);
  ctx.fillStyle = a.pants;
  ctx.fillRect(-5, 2 + backSwing, 4, 10);
  ctx.fillStyle = a.shoe;
  ctx.fillRect(-5, 11 + backSwing, 4, 3);

  // front leg
  ctx.fillStyle = outline;
  ctx.fillRect(0, 1 + frontSwing, 6, 14);
  ctx.fillStyle = a.pants;
  ctx.fillRect(1, 2 + frontSwing, 4, 10);
  ctx.fillStyle = a.shoe;
  ctx.fillRect(1, 11 + frontSwing, 4, 3);

  // optional backpack, tucked behind the torso
  if (a.backpack) {
    ctx.fillStyle = outline;
    ctx.fillRect(-10, -8, 6, 11);
    ctx.fillStyle = a.backpack;
    ctx.fillRect(-9, -7, 4, 9);
  }

  // torso: outline, base shirt, trailing-side shadow, leading-side highlight
  ctx.fillStyle = outline;
  ctx.fillRect(-7, -9, 14, 13);
  ctx.fillStyle = a.shirt;
  ctx.fillRect(-6, -8, 12, 11);
  ctx.fillStyle = a.shirtDark;
  ctx.fillRect(-6, -8, 4, 11);
  ctx.fillStyle = a.shirtLight;
  ctx.fillRect(3, -8, 3, 4);

  // arms, swinging opposite the legs
  ctx.fillStyle = a.skin;
  ctx.fillRect(-8, -6 + frontSwing * 0.5, 2, 7);
  ctx.fillRect(6, -6 + backSwing * 0.5, 2, 7);

  // head: outline, skin, hair/cap with a shaded brim line
  ctx.fillStyle = outline;
  ctx.fillRect(-5, -17, 10, 10);
  ctx.fillStyle = a.skin;
  ctx.fillRect(-4, -16, 8, 8);
  ctx.fillStyle = a.hair;
  ctx.fillRect(-4, -17, 8, 4);
  ctx.fillStyle = 'rgba(0,0,0,0.18)';
  ctx.fillRect(-4, -13, 8, 2);

  ctx.restore();
}

function drawDogActor(a) {
  const flip = a.dir < 0;
  ctx.save();
  ctx.translate(a.x, a.y);
  if (flip) ctx.scale(-1, 1);
  const legOff = Math.sin(a.t * 10) * 2;
  const outline = '#241a12';

  // ground shadow
  ctx.fillStyle = 'rgba(0,0,0,0.25)';
  ctx.fillRect(-9, 8, 18, 3);

  // legs: outline then darker fur
  ctx.fillStyle = outline;
  ctx.fillRect(-8, 1 + legOff, 4, 8);
  ctx.fillRect(3, 1 - legOff, 4, 8);
  ctx.fillStyle = a.furDark;
  ctx.fillRect(-7, 2 + legOff, 2, 6);
  ctx.fillRect(4, 2 - legOff, 2, 6);

  // tail
  ctx.fillStyle = outline;
  ctx.fillRect(-12, -3, 5, 4);
  ctx.fillStyle = a.fur;
  ctx.fillRect(-11, -2, 4, 3);

  // body: outline, base fur, top highlight, belly shadow
  ctx.fillStyle = outline;
  ctx.fillRect(-10, -5, 20, 10);
  ctx.fillStyle = a.fur;
  ctx.fillRect(-9, -4, 18, 8);
  ctx.fillStyle = a.furLight;
  ctx.fillRect(-9, -4, 18, 2);
  ctx.fillStyle = a.furDark;
  ctx.fillRect(-9, 1, 18, 3);

  // head: outline, fur, ear shading, snout with a small nose dot
  ctx.fillStyle = outline;
  ctx.fillRect(6, -9, 8, 8);
  ctx.fillStyle = a.fur;
  ctx.fillRect(7, -8, 6, 6);
  ctx.fillStyle = a.furDark;
  ctx.fillRect(7, -9, 3, 3);
  ctx.fillStyle = outline;
  ctx.fillRect(12, -3, 3, 3);
  ctx.fillStyle = '#2a1c14';
  ctx.fillRect(13, -2, 1, 1);

  ctx.restore();
}

function drawFishActor(a) {
  const p = a.t / a.life;
  const alpha = p < 0.2 ? p / 0.2 : p > 0.8 ? (1 - p) / 0.2 : 1;
  ctx.save();
  ctx.globalAlpha = Math.max(0, Math.min(1, alpha));
  ctx.fillStyle = '#e8d060';
  ctx.beginPath();
  ctx.ellipse(a.x, a.y, 5, 2.4, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(a.x - 5, a.y);
  ctx.lineTo(a.x - 8, a.y - 3);
  ctx.lineTo(a.x - 8, a.y + 3);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(230,240,255,0.5)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.ellipse(a.x, a.y, 8 + p * 10, 3 + p * 4, 0, 0, Math.PI * 2);
  ctx.stroke();
  ctx.restore();
}

// Gator: low, mostly-submerged silhouette -- just eyes/snout-ridge riding
// above the waterline plus a barely-visible body under a translucent
// "water surface" tint, with the same fade-in/fade-out envelope as
// drawFishActor (surfaces, drifts, submerges again).
function drawGatorActor(a) {
  const p = a.t / a.life;
  const alpha = p < 0.15 ? p / 0.15 : p > 0.85 ? (1 - p) / 0.15 : 1;
  const flip = a.dir < 0;
  ctx.save();
  ctx.globalAlpha = Math.max(0, Math.min(1, alpha));
  ctx.translate(a.x, a.y);
  if (flip) ctx.scale(-1, 1);

  // submerged body -- dark, dulled by the water tint over it
  ctx.fillStyle = 'rgba(30,42,26,0.55)';
  ctx.beginPath();
  ctx.ellipse(0, 2, 15, 5, 0, 0, Math.PI * 2);
  ctx.fill();

  // ridged back breaking the surface
  ctx.fillStyle = '#3a4a2e';
  for (let i = -10; i <= 8; i += 6) {
    ctx.beginPath();
    ctx.moveTo(i, -1);
    ctx.lineTo(i + 3, -4);
    ctx.lineTo(i + 6, -1);
    ctx.closePath();
    ctx.fill();
  }

  // snout ridge + eyes, the classic "just watching you" gator silhouette
  ctx.fillStyle = '#2e3c22';
  ctx.fillRect(11, -1, 8, 3);
  ctx.fillStyle = '#e8d878';
  ctx.fillRect(13, -3, 2, 2);
  ctx.fillRect(17, -3, 2, 2);
  ctx.fillStyle = '#1a1410';
  ctx.fillRect(13.5, -2.5, 1, 1);
  ctx.fillRect(17.5, -2.5, 1, 1);

  // faint ripple ring, grows slowly over the gator's lifetime
  ctx.strokeStyle = 'rgba(200,220,200,0.35)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.ellipse(0, 2, 16 + p * 8, 5 + p * 3, 0, 0, Math.PI * 2);
  ctx.stroke();
  ctx.restore();
}

// Snake: slithers along the boardwalk in a simple sine-wave S-curve, drawn
// as a chain of overlapping segments that shrink toward the tail.
function drawSnakeActor(a) {
  const flip = a.dir < 0;
  ctx.save();
  ctx.translate(a.x, a.y);
  if (flip) ctx.scale(-1, 1);

  ctx.fillStyle = 'rgba(0,0,0,0.22)';
  ctx.fillRect(-14, 6, 28, 3);

  const segs = 7;
  for (let i = segs - 1; i >= 0; i--) {
    const sx = -i * 4;
    const sy = Math.sin(a.t * 7 - i * 0.9) * 3;
    const r = i === 0 ? 4.5 : 3.6 - i * 0.15;
    ctx.fillStyle = i % 2 === 0 ? a.body : a.bodyDark;
    ctx.beginPath();
    ctx.ellipse(sx, sy, r, r * 0.7, 0, 0, Math.PI * 2);
    ctx.fill();
  }

  // head: a slightly lighter, forward-facing segment with two small eyes
  // and a flicking tongue
  const headY = Math.sin(a.t * 7) * 3;
  ctx.fillStyle = a.bodyLight;
  ctx.beginPath();
  ctx.ellipse(3, headY, 4.5, 3.2, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#1a1410';
  ctx.fillRect(4, headY - 2, 1, 1);
  ctx.fillRect(4, headY + 1, 1, 1);
  if (Math.floor(a.t * 6) % 3 === 0) {
    ctx.strokeStyle = '#c04030';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(7, headY);
    ctx.lineTo(11, headY - 1.5);
    ctx.moveTo(7, headY);
    ctx.lineTo(11, headY + 1.5);
    ctx.stroke();
  }
  ctx.restore();
}

// Frog: hops in short arcs (scale + vertical bob keyed off its own travel
// distance) up or down a boardwalk spur rather than walking smoothly.
function drawFrogActor(a) {
  const hopPhase = (Math.abs(a.y - (a.dir > 0 ? a.minY : a.maxY)) / 14) % 1;
  const hop = Math.sin(hopPhase * Math.PI); // 0 at each landing, 1 mid-hop
  const squash = 1 - hop * 0.25;
  ctx.save();
  ctx.translate(a.x, a.y);

  ctx.fillStyle = 'rgba(0,0,0,0.22)';
  ctx.beginPath();
  ctx.ellipse(0, 8, 7 * squash, 2.5, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.translate(0, -hop * 6);
  ctx.scale(squash, 1 / squash);

  // legs (simple splayed rectangles, more splayed mid-hop)
  const legSpread = 3 + hop * 3;
  ctx.fillStyle = a.skinDark;
  ctx.fillRect(-legSpread - 2, 2, 4, 5);
  ctx.fillRect(legSpread - 2, 2, 4, 5);

  // body
  ctx.fillStyle = a.skin;
  ctx.beginPath();
  ctx.ellipse(0, 0, 7, 5.5, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = a.skinLight;
  ctx.beginPath();
  ctx.ellipse(0, -2, 5, 2.5, 0, 0, Math.PI * 2);
  ctx.fill();

  // eyes on top, froggy style
  ctx.fillStyle = a.skin;
  ctx.beginPath();
  ctx.arc(-3, -5, 2.2, 0, Math.PI * 2);
  ctx.arc(3, -5, 2.2, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#1a1410';
  ctx.beginPath();
  ctx.arc(-3, -5, 1, 0, Math.PI * 2);
  ctx.arc(3, -5, 1, 0, Math.PI * 2);
  ctx.fill();

  ctx.restore();
}

// ---------------------------------------------------------------- touch controls (phones / tablets)
function bindHold(el, onDown, onUp) {
  el.addEventListener('pointerdown', (e) => { e.preventDefault(); onDown(); });
  el.addEventListener('pointerup', (e) => { e.preventDefault(); onUp(); });
  el.addEventListener('pointercancel', () => onUp());
  el.addEventListener('pointerleave', () => onUp());
}
function bindTap(el, onTap) {
  el.addEventListener('pointerdown', (e) => { e.preventDefault(); onTap(); });
}

// Floating analog joystick removed in favor of discrete d-pad buttons (see
// createTouchControls) \u2014 four separate elements proved more reliable for
// touch input than a single drag-tracked zone.

// Set by createTouchControls() below; read by syncTrickBtn() so the TRICK
// button's visibility can be toggled every frame from frame(), same
// pattern as hotkeysHintBtnEl/syncHotkeysHintBtn().
let trickBtnEl = null;

function createTouchControls() {
  const wrap = document.createElement('div');
  wrap.id = 'touchControls';
  wrap.addEventListener('contextmenu', (e) => e.preventDefault());

  // Explicitly pin the container's height in px to the actually-visible
  // viewport. This is belt-and-suspenders alongside the 100svh CSS rule:
  // some mobile browsers (older Safari/Chrome builds especially) don't
  // support svh units, and fall back to 100vh, which on-screen-toolbar
  // quirks can size against the viewport with toolbars hidden -- leaving
  // bottom-anchored controls positioned below the visible screen, worst in
  // portrait. Recomputing this in JS on every resize/orientation change
  // sidesteps CSS unit support entirely.
  function syncHeight() {
    const h = (window.visualViewport && window.visualViewport.height) || window.innerHeight;
    wrap.style.height = h + 'px';
  }
  syncHeight();
  window.addEventListener('resize', syncHeight);
  window.addEventListener('orientationchange', syncHeight);
  if (window.visualViewport) window.visualViewport.addEventListener('resize', syncHeight);

  const dpad = [
    ['dpadUp', 'arrowup', '▲'],
    ['dpadDown', 'arrowdown', '▼'],
    ['dpadLeft', 'arrowleft', '◀'],
    ['dpadRight', 'arrowright', '▶'],
  ];
  dpad.forEach(([id, k, label]) => {
    const btn = document.createElement('div');
    btn.id = id; btn.className = 'tc-btn'; btn.textContent = label;
    bindHold(btn, () => {
      keys[k] = true;
      // On the character-select screen (and the title screen's left/right
      // page flip) the d-pad's left/right taps need to drive selectMove
      // directly, the same way the keydown listener does for a physical
      // keyboard — held/synthetic key state alone never reaches update()'s
      // selectMove check.
      if (state === 'select' || state === 'title' || state === 'history') {
        if (k === 'arrowleft') selectMove = -1;
        if (k === 'arrowright') selectMove = 1;
      }
      // 'minigame' included for the darts mode chooser (classic vs 3D) --
      // running mini-games themselves ignore menuMove. 'lab' included so the
      // 4-bay instrument picker in Rico's Lab (see LAB_OPTIONS/labIndex) can
      // be cycled by tapping the on-screen d-pad, same as a physical
      // keyboard's up/down arrows do via the keydown listener above.
      if (state === 'digChoice' || state === 'slotChoose' || state === 'minigame' || state === 'lab') {
        if (k === 'arrowup') menuMove = -1;
        if (k === 'arrowdown') menuMove = 1;
      }
      // The Crate uses left/right for world tabs and up/down to browse
      // slots, same reasoning as the selectMove/menuMove cases above.
      if (state === 'crate') {
        if (k === 'arrowleft') selectMove = -1;
        if (k === 'arrowright') selectMove = 1;
        if (k === 'arrowup') menuMove = -1;
        if (k === 'arrowdown') menuMove = 1;
      }
      music.start();
    }, () => { keys[k] = false; });
    wrap.appendChild(btn);
  });

  const eBtn = document.createElement('div');
  eBtn.id = 'btnE'; eBtn.className = 'tc-btn'; eBtn.textContent = 'E';
  bindTap(eBtn, () => { interactPressed = true; music.start(); });
  wrap.appendChild(eBtn);

  const xBtn = document.createElement('div');
  xBtn.id = 'btnX'; xBtn.className = 'tc-btn'; xBtn.textContent = 'X';
  bindTap(xBtn, () => { buyPressed = true; music.start(); });
  wrap.appendChild(xBtn);

  const mBtn = document.createElement('div');
  mBtn.id = 'btnM'; mBtn.className = 'tc-btn'; mBtn.textContent = 'MUTE';
  bindTap(mBtn, () => { music.toggleMute(); music.start(); });
  wrap.appendChild(mBtn);

  // SK8 gets its own always-visible button — it's the toggle players reach
  // for most, so it shouldn't be buried in the Extras dropdown.
  const skBtn = document.createElement('div');
  skBtn.id = 'btnSK8'; skBtn.className = 'tc-btn'; skBtn.textContent = 'SK8';
  bindTap(skBtn, () => {
    toggleSkate();
    scratchPressed = true; // doubles as the 2nd mini-game action button; harmless outside 'minigame'
    music.start();
    skBtn.classList.toggle('tc-on', player.skating);
  });
  wrap.appendChild(skBtn);

  // TRICK — same action as the desktop [T] hot key (triggerTrick()), but
  // only ever useful while riding the board, so it's hidden/shown by
  // syncTrickBtn() (called every frame from frame()) rather than sitting
  // in the resting cluster all the time like SK8/X/MUTE do. Label text is
  // wrapped in its own span (see #btnTrick .tc-trick-icon CSS above).
  const trickBtn = document.createElement('div');
  trickBtn.id = 'btnTrick'; trickBtn.className = 'tc-btn';
  const trickIcon = document.createElement('span');
  trickIcon.className = 'tc-trick-icon';
  trickIcon.textContent = 'STEEZ';
  trickBtn.appendChild(trickIcon);
  bindTap(trickBtn, () => { triggerTrick(); music.start(); });
  wrap.appendChild(trickBtn);
  trickBtnEl = trickBtn;

  // "Extras" — a small popup menu (cold brew, iced tea) so the resting
  // button cluster stays minimal instead of growing a permanent button
  // for every toggle.
  const extrasPanel = document.createElement('div');
  extrasPanel.id = 'extrasPanel';

  const extras = [
    ['BREW',  () => toggleCoffee(),     () => player.holdingCoffee],
    ['YERBA', () => toggleTea(),        () => player.holdingTea],
    ['TAG',   () => placeGraffitiTag(), () => false],
    ['CRATE', () => openCrate(),        () => false],
    ['SAVE',  () => saveGame(true),     () => false],
    ['NEW',   () => { openDigChoice(); },       () => false],
  ];
  extras.forEach(([label, action, isOn]) => {
    const btn = document.createElement('div');
    btn.className = 'tc-btn' + ((label === 'SAVE' || label === 'NEW' || label === 'CRATE') ? ' tc-important' : '');
    btn.textContent = label;
    bindTap(btn, () => {
      action();
      music.start();
      btn.classList.toggle('tc-on', isOn());
    });
    extrasPanel.appendChild(btn);
  });
  wrap.appendChild(extrasPanel);

  const extrasBtn = document.createElement('div');
  extrasBtn.id = 'btnExtras'; extrasBtn.className = 'tc-btn'; extrasBtn.textContent = '☰';
  bindTap(extrasBtn, () => { extrasPanel.classList.toggle('open'); music.start(); });
  wrap.appendChild(extrasBtn);

  document.body.appendChild(wrap);
}
createTouchControls();

// ---------------------------------------------------------------- hot-keys reminder tab (non-touch only)
// A subtle "HOT KEYS [H]" tab glued to the right edge of the screen, for
// desktop/laptop/gamepad players who have no onscreen equivalent of the
// touch controls' visible button labels -- it's easy to forget the [H]
// popup exists once you're deep into the map. Hidden on touch devices via
// the (pointer: coarse) rule above (they already see everything they need),
// and only ever shown while state === 'play' (see syncHotkeysHintBtn(),
// called every frame from frame() below) so it never overlaps a mini-game
// or one of the instrument/app overlays.
let hotkeysHintBtnEl = null;
function createHotkeysHintBtn() {
  const btn = document.createElement('div');
  btn.id = 'hotkeysHintBtn';
  btn.textContent = 'HOT KEYS [H]';
  btn.title = 'Show hot keys (H)';
  btn.addEventListener('click', () => {
    // Same open action as pressing [H] in the keydown handler above --
    // only fires from 'play' since that's the only state this tab is ever
    // visible in.
    if (state === 'play') {
      hotkeysReturnState = state;
      state = 'hotkeys';
      music.start();
    }
  });
  document.body.appendChild(btn);
  hotkeysHintBtnEl = btn;
}
createHotkeysHintBtn();

// Toggles the .visible class only when it actually changes, so this can be
// called unconditionally from frame() every tick without spamming DOM
// writes. Gated on state === 'play' alone -- every other state (dialog,
// portal, minigame, hotkeys popup itself, every *App instrument/mini-game
// overlay, etc.) hides it, per "only over the main map areas".
let hotkeysHintVisible = null;
function syncHotkeysHintBtn() {
  const shouldShow = state === 'play';
  if (shouldShow !== hotkeysHintVisible) {
    hotkeysHintVisible = shouldShow;
    if (hotkeysHintBtnEl) hotkeysHintBtnEl.classList.toggle('visible', shouldShow);
  }
}

// Same toggle-only-on-change pattern as syncHotkeysHintBtn() above, so this
// can also be called unconditionally from frame() every tick. Shown only
// while actually riding the board during play -- the same condition
// triggerTrick() itself checks -- so it appears the instant player.skating
// flips true (from [B], the on-screen SK8 button, or falling off outside
// terrain) and disappears the instant it flips back.
let trickBtnVisible = null;
function syncTrickBtn() {
  const shouldShow = state === 'play' && player.skating;
  if (shouldShow !== trickBtnVisible) {
    trickBtnVisible = shouldShow;
    if (trickBtnEl) trickBtnEl.classList.toggle('visible', shouldShow);
  }
}

// ---------------------------------------------------------------- Rico's Lab instrument overlay
// Each of the 4 instrument apps (Pocket Sampler, Keys, Cuts, EQ) is a full
// standalone HTML/CSS/JS page (see LAB_OPTIONS), so rather than porting
// ~1000+ lines of Web Audio code per instrument into the canvas/minigame
// system, they're loaded into a fixed full-screen DOM overlay via <iframe>
// -- same trick as the rest of the game's UI (touch controls, the
// responsive canvas sizing) building its own DOM/CSS at runtime instead of
// depending on markup living in index.html.
let labOverlayEl = null, labOverlayFrame = null, labOverlayTitle = null;

function createLabAppOverlay() {
  const style = document.createElement('style');
  style.textContent = `
    #ricoLabApp {
      position: fixed; inset: 0; z-index: 1000;
      background: #000;
      display: none; flex-direction: column;
    }
    #ricoLabApp.open { display: flex; }
    #ricoLabApp .rla-bar {
      flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between;
      gap: 12px; padding: 10px 14px;
      background: linear-gradient(#241a0e, #120d06);
      border-bottom: 2px solid #e0b040;
      padding-top: calc(10px + env(safe-area-inset-top, 0px));
    }
    #ricoLabApp .rla-title {
      color: #f4ecd8; font: bold 14px monospace; letter-spacing: 0.5px;
      white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    }
    #ricoLabApp .rla-close {
      flex: 0 0 auto; cursor: pointer;
      background: rgba(224,176,64,0.15);
      border: 1.5px solid rgba(224,176,64,0.85);
      color: #f4ecd8; border-radius: 8px;
      padding: 7px 16px; font: bold 13px monospace;
      -webkit-user-select: none; user-select: none;
    }
    #ricoLabApp .rla-close:active { background: rgba(224,176,64,0.4); }
    #ricoLabApp iframe {
      flex: 1 1 auto; width: 100%; border: 0; background: #000;
    }
  `;
  document.head.appendChild(style);

  labOverlayEl = document.createElement('div');
  labOverlayEl.id = 'ricoLabApp';

  const bar = document.createElement('div');
  bar.className = 'rla-bar';
  labOverlayTitle = document.createElement('div');
  labOverlayTitle.className = 'rla-title';
  const closeBtn = document.createElement('div');
  closeBtn.className = 'rla-close';
  closeBtn.textContent = '\u2190 BACK TO THE LAB';
  bindTap(closeBtn, closeInstrument);
  bar.appendChild(labOverlayTitle);
  bar.appendChild(closeBtn);

  labOverlayFrame = document.createElement('iframe');
  labOverlayFrame.setAttribute('allow', 'autoplay; microphone');

  labOverlayEl.appendChild(bar);
  labOverlayEl.appendChild(labOverlayFrame);
  document.body.appendChild(labOverlayEl);
}
createLabAppOverlay();

