// ---------------------------------------------------------------- Vinyl Ninja splash + overlay
// Vinyl Ninja -- a fruit-ninja-style slice-the-records arcade game, reached
// by walking up to the samurai sword left stuck in the mud out in the swamp
// (see MINIGAME_ACTIONS.vinylninja and the swamp map's `minigames` list).
// Unlike VT Dirt/Dig Dash/every other standalone app above, this one shows
// a full-screen splash card first (the "KANGA'S WAX NINJA" key art) instead
// of opening straight into the iframe -- same "scale-to-fit art plus a
// blinking continue prompt" shape as drawLabUnlock()/drawLevelIntro()'s
// level-1 card, drawn over the still-running swamp scene the same way
// drawLabUnlock() draws over town. Pressing E or tapping again from the
// splash is what actually calls openVinylNinjaApp() below.
let vinylNinjaSplashReturnState = 'play';

// Opens the splash and switches state to 'vinylNinjaSplash'. Called from
// MINIGAME_ACTIONS.vinylninja (E on the sword, or tapping its floating
// sign).
function openVinylNinjaSplash() {
  vinylNinjaSplashReturnState = state;
  state = 'vinylNinjaSplash';
}

// Full-screen splash card -- see drawLevelIntro()'s level-1 branch and
// drawLabUnlock() for the same "scale art to fully cover the view, blink a
// continue prompt at the bottom" shape this reuses. Drawn on top of the
// ordinary swamp render() pass (not one of the WORLD_HIDDEN_STATES/DOM-
// overlay states), so the swamp stays visible/dimmed underneath exactly
// like drawLabUnlock() over town.
function drawVinylNinjaSplash() {
  ctx.fillStyle = 'rgba(8,6,12,0.6)';
  ctx.fillRect(0, 0, VIEW_W, VIEW_H);

  if (vinylNinjaSplashImg.complete && vinylNinjaSplashImg.naturalWidth) {
    const iw = vinylNinjaSplashImg.naturalWidth, ih = vinylNinjaSplashImg.naturalHeight;
    const scale = Math.max(VIEW_W / iw, VIEW_H / ih);
    const dw = iw * scale, dh = ih * scale;
    const dx = (VIEW_W - dw) / 2, dy = (VIEW_H - dh) / 2;
    ctx.drawImage(vinylNinjaSplashImg, dx, dy, dw, dh);
    ctx.fillStyle = 'rgba(8,6,12,0.35)';
    ctx.fillRect(0, 0, VIEW_W, VIEW_H);
  } else {
    // fallback text-only version, in case the art hasn't loaded in yet
    ctx.textAlign = 'center';
    ctx.fillStyle = '#e0b040';
    ctx.font = 'bold 26px monospace';
    ctx.fillText('VINYL NINJA', VIEW_W / 2, VIEW_H / 2 - 10);
    ctx.fillStyle = '#f4ecd8';
    ctx.font = '14px monospace';
    ctx.fillText('Slice the records. Dodge the bombs.', VIEW_W / 2, VIEW_H / 2 + 16);
  }

  ctx.textAlign = 'center';
  ctx.fillStyle = Math.floor(performance.now() / 400) % 2 ? '#e0b040' : '#f4ecd8';
  ctx.font = 'bold 16px monospace';
  ctx.fillText('- PRESS E TO DROP IN -', VIEW_W / 2, VIEW_H - 24);
}

// KANGAIDEN -- a Shinobi-style side-scrolling brawler starring DJ Kanga,
// parked on the open grass in town (see the town map's `minigames` list
// above and MINIGAME_ACTIONS.kangaiden). Same "full-screen splash card
// before the iframe" shape as Vinyl Ninja just above -- see
// drawVinylNinjaSplash() -- drawn over the still-running town scene the
// same way drawLabUnlock()/drawVinylNinjaSplash() draw over their own
// worlds. Pressing E or tapping again from the splash is what actually
// calls openKangaidenApp() below.
let kangaidenSplashReturnState = 'play';

// Full-screen, skippable video that plays once before the still key-art
// splash below -- same shape as the M85 Games brand-intro video at the very
// top of this file (skip button in the corner; a click/tap, the [Skip]
// button, `ended`, `error`, or any keypress all dismiss it the same way;
// sound-first-then-muted-fallback autoplay, since browsers only allow
// autoplay-with-sound right after a user gesture like the E-press/tap that
// got us here; and a hard safety timeout so a slow or blocked file never
// strands the player on a black screen) -- just triggered on demand here
// instead of once at page load, and parameterized with an `onDone` callback
// instead of always resuming the same fixed startup flow. `onDone` fires
// exactly once, however playback ends, and is what actually hands off to
// the rest of the KANGAIDEN flow (see openKangaidenSplash() below).
function playKangaidenSplashVideo(onDone) {
  const v = document.createElement('video');
  v.src = KANGAIDEN_SPLASH_VIDEO_SRC;
  v.preload = 'auto';
  v.playsInline = true; // iOS: play inline instead of forcing fullscreen
  v.setAttribute('webkit-playsinline', 'true');
  v.disablePictureInPicture = true;
  v.controls = false;
  v.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;'
    + 'object-fit:contain;background:#000;z-index:2147483647;';
  document.body.appendChild(v);

  const skipBtn = document.createElement('div');
  skipBtn.textContent = 'SKIP \u25b8';
  skipBtn.style.cssText = 'position:fixed;right:14px;bottom:14px;'
    + 'padding:8px 16px;padding-bottom:calc(8px + env(safe-area-inset-bottom, 0px));'
    + 'background:rgba(20,16,26,0.55);border:1.5px solid rgba(244,236,216,0.55);'
    + 'border-radius:8px;color:#f4ecd8;font:bold 12px monospace;letter-spacing:0.5px;'
    + '-webkit-user-select:none;user-select:none;z-index:2147483647;cursor:pointer;';
  document.body.appendChild(skipBtn);

  let done = false;
  function finish() {
    if (done) return;
    done = true;
    clearTimeout(safety);
    v.pause();
    v.remove();
    skipBtn.remove();
    onDone();
  }
  v.addEventListener('click', finish);
  v.addEventListener('ended', finish);
  v.addEventListener('error', finish); // missing/corrupt file -> never block the game on it
  skipBtn.addEventListener('click', finish);
  skipBtn.addEventListener('touchend', (e) => { e.preventDefault(); finish(); });
  window.addEventListener('keydown', finish, { once: true });
  const safety = setTimeout(finish, 9000);

  const tryPlay = v.play();
  if (tryPlay && typeof tryPlay.catch === 'function') {
    tryPlay.catch(() => {
      v.muted = true;
      v.play().catch(finish); // if even muted autoplay fails, just skip straight in
    });
  }
}

// Kicks off the video and switches state to 'kangaidenVideo' (blocking
// ordinary input/movement the same way every other overlay state here
// does), then -- once playKangaidenSplashVideo()'s onDone fires -- hands
// off to the still key-art splash exactly as before (state =
// 'kangaidenSplash'). Called from MINIGAME_ACTIONS.kangaiden (E on the
// cabinet, or tapping its floating sign).
function openKangaidenSplash() {
  kangaidenSplashReturnState = state;
  state = 'kangaidenVideo';
  playKangaidenSplashVideo(() => {
    state = 'kangaidenSplash';
  });
}

// Full-screen splash card -- see drawVinylNinjaSplash() just above for the
// same "scale art to fully cover the view, blink a continue prompt at the
// bottom" shape this reuses. Drawn on top of the ordinary town render()
// pass (not one of the WORLD_HIDDEN_STATES/DOM-overlay states), so the
// town stays visible/dimmed underneath exactly like drawVinylNinjaSplash()
// does over the swamp.
function drawKangaidenSplash() {
  ctx.fillStyle = 'rgba(8,6,12,0.6)';
  ctx.fillRect(0, 0, VIEW_W, VIEW_H);

  if (kangaidenSplashImg.complete && kangaidenSplashImg.naturalWidth) {
    const iw = kangaidenSplashImg.naturalWidth, ih = kangaidenSplashImg.naturalHeight;
    const scale = Math.max(VIEW_W / iw, VIEW_H / ih);
    const dw = iw * scale, dh = ih * scale;
    const dx = (VIEW_W - dw) / 2, dy = (VIEW_H - dh) / 2;
    ctx.drawImage(kangaidenSplashImg, dx, dy, dw, dh);
    ctx.fillStyle = 'rgba(8,6,12,0.35)';
    ctx.fillRect(0, 0, VIEW_W, VIEW_H);
  } else {
    // fallback text-only version, in case the art hasn't loaded in yet
    ctx.textAlign = 'center';
    ctx.fillStyle = '#e0b040';
    ctx.font = 'bold 26px monospace';
    ctx.fillText('KANGAIDEN', VIEW_W / 2, VIEW_H / 2 - 10);
    ctx.fillStyle = '#f4ecd8';
    ctx.font = '14px monospace';
    ctx.fillText('Slash zombies. Drop the beat.', VIEW_W / 2, VIEW_H / 2 + 16);
  }

  ctx.textAlign = 'center';
  ctx.fillStyle = Math.floor(performance.now() / 400) % 2 ? '#e0b040' : '#f4ecd8';
  ctx.font = 'bold 16px monospace';
  ctx.fillText('- PRESS E TO DROP IN -', VIEW_W / 2, VIEW_H - 24);
}

