// building. Same "full-screen DOM overlay with an <iframe>" pattern as
// chess/the beat bot/the organ/mini golf/the blackbook/.../Filter Lab
// above.
//
// Ships as a bundled, self-contained app (its own HTML/CSS/JS, WebAudio
// breakbeat pad included, no external assets, fonts, or network calls at
// all) at instruments/hiphop-library/index.html -- the exact same local-
// file pattern CHESS_APP_URL/BEAT_BOT_APP_URL/.../FILTER_LAB_APP_URL use.
// Being a same-origin local asset rather than a live remote site means it
// loads and plays identically with or without a connection, so -- same as
// the others -- there's no online/offline branching needed here either.
const HIPHOP_LIBRARY_APP_URL = 'instruments/hiphop-library/index.html';
let hiphopLibraryOverlayEl = null, hiphopLibraryOverlayFrame = null;
let hiphopLibraryReturnState = 'play';
let hiphopLibraryHistoryPushed = false; // mirrors labHistoryPushed/chessHistoryPushed/.../filterLabHistoryPushed -- see openHipHopLibraryApp()/closeHipHopLibraryApp()

function createHipHopLibraryOverlay() {
  const style = document.createElement('style');
  style.textContent = `
    #hiphopLibraryApp {
      position: fixed; inset: 0; z-index: 1000;
      background: #000;
      display: none; flex-direction: column;
    }
    #hiphopLibraryApp.open { display: flex; }
    #hiphopLibraryApp .hhl-bar {
      flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between;
      gap: 12px; padding: 10px 14px;
      background: linear-gradient(#241a0e, #120d06);
      border-bottom: 2px solid #e0b040;
      padding-top: calc(10px + env(safe-area-inset-top, 0px));
    }
    #hiphopLibraryApp .hhl-title {
      color: #f4ecd8; font: bold 14px monospace; letter-spacing: 0.5px;
      white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    }
    #hiphopLibraryApp .hhl-close {
      flex: 0 0 auto; cursor: pointer;
      background: rgba(224,176,64,0.15);
      border: 1.5px solid rgba(224,176,64,0.85);
      color: #f4ecd8; border-radius: 8px;
      padding: 7px 16px; font: bold 13px monospace;
      -webkit-user-select: none; user-select: none;
    }
    #hiphopLibraryApp .hhl-close:active { background: rgba(224,176,64,0.4); }
    #hiphopLibraryApp iframe {
      flex: 1 1 auto; width: 100%; border: 0; background: #000;
    }
  `;
  document.head.appendChild(style);

  hiphopLibraryOverlayEl = document.createElement('div');
  hiphopLibraryOverlayEl.id = 'hiphopLibraryApp';

  const bar = document.createElement('div');
  bar.className = 'hhl-bar';
  const title = document.createElement('div');
  title.className = 'hhl-title';
  title.textContent = 'THE HIP HOP LIBRARY';
  const closeBtn = document.createElement('div');
  closeBtn.className = 'hhl-close';
  closeBtn.textContent = '\u2190 BACK OUTSIDE';
  bindTap(closeBtn, closeHipHopLibraryApp);
  bar.appendChild(title);
  bar.appendChild(closeBtn);

  hiphopLibraryOverlayFrame = document.createElement('iframe');
  hiphopLibraryOverlayFrame.setAttribute('allow', 'autoplay');

  hiphopLibraryOverlayEl.appendChild(bar);
  hiphopLibraryOverlayEl.appendChild(hiphopLibraryOverlayFrame);
  document.body.appendChild(hiphopLibraryOverlayEl);
}
createHipHopLibraryOverlay();

// Opens the Hip Hop Library overlay and switches state to
// 'hiphopLibraryApp'. Called from MINIGAME_ACTIONS.hiphoplibrary (E on the
// kiosk, or tapping its floating sign), same entry points every other
// mini-game uses.
function openHipHopLibraryApp() {
  hiphopLibraryReturnState = state;
  hiphopLibraryOverlayFrame.src = HIPHOP_LIBRARY_APP_URL;
  hiphopLibraryOverlayEl.classList.add('open');
  state = 'hiphopLibraryApp';
  // Same throwaway-history-entry trick as openInstrument()/openChessApp()/
  // .../openFilterLabApp() above, so the browser/OS back gesture closes
  // the Hip Hop Library overlay instead of leaving the game entirely.
  history.pushState({ hiphopLibraryApp: true }, '');
  hiphopLibraryHistoryPushed = true;
}

// Tears the iframe back down and returns to ordinary gameplay outside.
// fromPopState mirrors closeInstrument()/closeChessApp()/.../
// closeFilterLabApp()'s parameter -- true when triggered by the browser's
// back button (whose history entry is already consumed), so we must not
// call history.back() again in that case.
function closeHipHopLibraryApp(fromPopState) {
  hiphopLibraryOverlayEl.classList.remove('open');
  hiphopLibraryOverlayFrame.src = 'about:blank';
  reclaimGameFocus(hiphopLibraryOverlayFrame);
  state = hiphopLibraryReturnState;
  if (!fromPopState && hiphopLibraryHistoryPushed) {
    hiphopLibraryHistoryPushed = false;
    history.back();
  } else {
    hiphopLibraryHistoryPushed = false;
  }
}

// WISH JAM -- a rhythm-battle breakdancing game (tap/press FOOTWORK, TOP ROCK,
// FREEZE and POWER as notes hit the pads, keep the crowd hyped, and every
// 15-note combo triggers a power-move FINISHER) set out on the concrete plaza
// of LEVEL 3 (SKATEPARK), triggered by a headspinning b-boy on a cardboard mat
// (see the skatepark map's `minigames` list in makeSkatepark()). Same
// "full-screen DOM overlay with an <iframe>" pattern as Reverb Reef/Beat
// Brewing, and the same INLINED-page shape: the whole page (pixel sprite
// sheet and WISH JAM splash art embedded as data URIs, the beat synthesized
// at runtime with the Web Audio API) lives in WISH_JAM_HTML below and is
// loaded through iframe.srcdoc -- so there's no extra file to ship, nothing
// to fetch, and no network call anywhere. It plays identically with or
// without a connection, on desktop (arrow keys / WASD) and on mobile (tap
// the lanes) in portrait or landscape. [Esc] inside the iframe posts a
// message back (keys typed there never reach this page).
const WISH_JAM_HTML = "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><title>WISH JAM<\/title>\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover,user-scalable=no\">\n<style>\n:root{--bg:#0a0a1a;color-scheme:dark;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px);background:var(--bg)}\nhtml{height:100%;scroll-padding-top:env(safe-area-inset-top,0px)}\nbody{margin:0;height:100%;background:var(--bg);overflow:hidden;touch-action:none;user-select:none;-webkit-user-select:none}\ncanvas{display:block;width:100%;height:100%}\n<\/style><\/head><body><canvas id=\"c\"><\/canvas>\n<script>\nconst IMG=\"data:image/png;base64,\";\nconst SPL=\"data:image/jpeg;base64,\";const spl=new Image();spl.src=SPL;\nconst cv=document.getElementById('c'),g=cv.getContext('2d');\nlet W,H,D,st,ln,sheet=null,K=1;\nfunction size(){D=Math.min(devicePixelRatio||1,2);W=cv.clientWidth;H=cv.clientHeight;cv.width=W*D;cv.height=H*D;g.setTransform(D,0,0,D,0,0);\n if(W>H*1.05){st={x:0,y:0,w:W*.42,h:H};ln={x:W*.42,y:0,w:W*.58,h:H}}else{st={x:0,y:0,w:W,h:H*.42};ln={x:0,y:H*.42,w:W,h:H*.58}}}\naddEventListener('resize',size);addEventListener('orientationchange',()=>setTimeout(size,200));size();\n// sprite rows: y, height, half-width, frame centers (in sheet px)\nconst R={\nidle:{y:62,h:172,w:48,c:[56,151,245,341]},\nwalk:{y:62,h:172,w:50,c:[460,555,640,725,815,905]},\nbounce:{y:62,h:172,w:50,c:[1018,1112,1205,1298,1390,1480]},\ntop:{y:322,h:162,w:52,c:[65,168,270,372,470,575]},\nfoot:{y:350,h:138,w:52,c:[700,820,945,1050,1155,1258,1365,1470]},\nfreeze:{y:582,h:148,w:55,c:[70,170,270,380,495,650]},\npower:{y:572,h:158,w:55,c:[790,905,1020,1120,1222,1340,1465]},\nhit:{y:818,h:146,w:42,c:[665,740,810,885,960,1040]},\nwin:{y:818,h:146,w:50,c:[1135,1220,1310,1385,1475]}};\nconst LANES=[{n:'FOOTWORK',a:'foot',col:'#ff4d6d',k:'\u2190',keys:['ArrowLeft','a']},{n:'TOP ROCK',a:'top',col:'#ffd23f',k:'\u2193',keys:['ArrowDown','s']},{n:'FREEZE',a:'freeze',col:'#3ddc97',k:'\u2191',keys:['ArrowUp','w']},{n:'POWER',a:'power',col:'#4cc9f0',k:'\u2192',keys:['ArrowRight','d','k']}];\nconst im=new Image();im.onload=()=>{const c=document.createElement('canvas');c.width=im.width;c.height=im.height;const x=c.getContext('2d');x.drawImage(im,0,0);const d=x.getImageData(0,0,c.width,c.height),p=d.data;for(let i=0;i<p.length;i+=4)if(p[i]+p[i+1]+p[i+2]<45)p[i+3]=0;x.putImageData(d,0,0);sheet=c;K=c.width/1536};im.src=IMG;\nfunction spr(a,i,x,fy,s){if(!sheet)return;const r=R[a];i=((i%r.c.length)+r.c.length)%r.c.length;g.drawImage(sheet,(r.c[i]-r.w)*K,r.y*K,2*r.w*K,r.h*K,x-r.w*s,fy-r.h*s,2*r.w*s,r.h*s)}\n// audio\nlet iS=0,fin_=null,AC,t0=0,bpm=104,spb=60/bpm,chart=[],total=80,nextStep=0,state='menu',score=0,combo=0,best=0,hype=50,hits=[0,0,0,0],pose=null,texts=[],press=[0,0,0,0],stats={p:0,g:0,m:0},endT=0;\nfunction env(f,t,d,type,v,f2){const o=AC.createOscillator(),gn=AC.createGain();o.type=type;o.frequency.setValueAtTime(f,t);if(f2)o.frequency.exponentialRampToValueAtTime(f2,t+d);gn.gain.setValueAtTime(v,t);gn.gain.exponentialRampToValueAtTime(.001,t+d);o.connect(gn).connect(AC.destination);o.start(t);o.stop(t+d)}\nfunction noise(t,d,v,hp){const n=AC.sampleRate*d,b=AC.createBuffer(1,n,AC.sampleRate),a=b.getChannelData(0);for(let i=0;i<n;i++)a[i]=Math.random()*2-1;const s=AC.createBufferSource(),f=AC.createBiquadFilter(),gn=AC.createGain();s.buffer=b;f.type='highpass';f.frequency.value=hp;gn.gain.setValueAtTime(v,t);gn.gain.exponentialRampToValueAtTime(.001,t+d);s.connect(f).connect(gn).connect(AC.destination);s.start(t)}\nconst BASS=[55,55,65.4,49];\nfunction music(s,t){const b=s>>1,off=s&1;if(!off&&b%2==0)env(150,t,.18,'sine',.9,40);if(!off&&b%2==1)noise(t,.15,.35,1500);noise(t,.04,.12,7000);if(!off&&(b%4==0||b%4==2))env(BASS[(b>>2)%4],t,.4,'sawtooth',.18);if(off&&b%4==3)env(BASS[(b>>2)%4]*2,t,.2,'square',.07)}\nfunction sched(){const e=AC.currentTime+.25;while(t0+nextStep*spb/2<e){music(nextStep,t0+nextStep*spb/2);nextStep++}}\nfunction begin(){if(!AC)AC=new(window.AudioContext||window.webkitAudioContext)();AC.resume();chart=[];let last=-1;for(let b=4;b<total;b++){const pr=Math.min(.55+b/total*.4,.95);if(Math.random()<pr){let l;do{l=Math.random()*4|0}while(l==last&&Math.random()<.7);last=l;chart.push({t:b,l,s:0})}\n if(b>24&&Math.random()<.22){chart.push({t:b+.5,l:Math.random()*4|0,s:0})}}\n chart.sort((a,b)=>a.t-b.t);iS=AC.currentTime;t0=iS+2.6;fin_=null;nextStep=0;score=combo=0;hype=50;hits=[0,0,0,0];pose=null;texts=[];stats={p:0,g:0,m:0};endT=t0+(total+3)*spb;state='play'}\nconst now=()=>AC?AC.currentTime:performance.now()/1000;\nfunction judge(l){press[l]=now();if(state!='play')return;const T=now();let best=null;for(const n of chart)if(n.l==l&&!n.s&&Math.abs(t0+n.t*spb-T)<.22){if(!best||n.t<best.t)best=n}\n if(!best){return}const d=Math.abs(t0+best.t*spb-T);const perfect=d<.09;best.s=1;combo++;if(combo>bestC())best_=combo;stats[perfect?'p':'g']++;score+=(perfect?100:50)*(1+Math.min(combo,40)/10|0);hype=Math.min(100,hype+(perfect?3:1.5));\n hits[l]++;if(!(fin_&&T<fin_.u))pose={a:LANES[l].a,i:hits[l],u:T+spb*.8,l};texts.push({s:perfect?'PERFECT':'GOOD',c:LANES[l].col,t:T});if(combo%15==0){fin_={s:T,u:T+spb*3};score+=500;hype=Math.min(100,hype+10);texts.push({s:'FINISHER!',c:'#fff',t:T});env(110,T,.5,'sawtooth',.25,440)}env(330+l*110,T,.12,'square',.12)}\nlet best_=0;const bestC=()=>best_;\nfunction fin(w){state=w;pose=null}\naddEventListener('keydown',e=>{if(e.repeat)return;const k=e.key.length==1?e.key.toLowerCase():e.key;if(state!='play'){if(k==' '||k=='Enter')begin();return}LANES.forEach((L,i)=>{if(L.keys.includes(k)){e.preventDefault();judge(i)}})});\ncv.addEventListener('pointerdown',e=>{e.preventDefault();const r=cv.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;if(state!='play'){if(state=='menu'||state=='over'||state=='win')begin();return}\n if(x>=ln.x&&y>=ln.y){judge(Math.min(3,(x-ln.x)/(ln.w/4)|0))}});\n// draw\nfunction rr(x,y,w,h,r){g.beginPath();g.roundRect(x,y,w,h,r)}\nfunction frame(){requestAnimationFrame(frame);const T=now(),beat=state=='play'?(T-t0)/spb:T/spb;\n g.clearRect(0,0,W,H);\n // stage\n let gr=g.createLinearGradient(0,0,0,st.h);gr.addColorStop(0,'#1a0a3a');gr.addColorStop(1,'#3a1060');g.fillStyle=gr;g.fillRect(st.x,st.y,st.w,st.h);\n const pul=1-((beat%1+1)%1);const fy=st.y+st.h*.88;\n g.save();g.beginPath();g.rect(st.x,st.y,st.w,st.h);g.clip();\n [['#ff4d6d',.2],['#4cc9f0',.5],['#ffd23f',.8]].forEach(([c,p],i)=>{g.fillStyle=c;g.globalAlpha=.08+.1*pul;const sx=st.x+st.w*p,sw=st.w*.12*(i==1?1.2:1);g.beginPath();g.moveTo(sx-6,0);g.lineTo(sx+6,0);g.lineTo(sx+sw+Math.sin(T+i)*20,fy);g.lineTo(sx-sw+Math.sin(T+i)*20,fy);g.fill()});g.globalAlpha=1;\n g.fillStyle='#1c1033';g.fillRect(st.x,fy,st.w,st.h-(fy-st.y));g.fillStyle='#ff4d6d';g.globalAlpha=.6+.4*pul;g.fillRect(st.x,fy,st.w,3);g.globalAlpha=1;\n g.imageSmoothingEnabled=false;\n const s=Math.min(st.h*.62/172,st.w*.8/100),cx=st.x+st.w/2;\n let a='bounce',i=Math.floor(beat*3)%6,sc=s*(1+.03*pul);\n if(state=='menu'){a='idle';i=Math.floor(T*4)%4}\n else if(state=='win'){a='win';i=Math.floor(T*6)%5}\n else if(state=='over'){a='hit';i=5}\n else if(pose&&T<pose.u){a=pose.a;i=pose.i;sc=s*(1+.06*pul)}\n else if(pose&&pose.miss&&T<pose.u){a='hit';i=5}\n g.fillStyle='#000';g.globalAlpha=.3;g.beginPath();g.ellipse(cx,fy+4,s*40,s*8,0,0,7);g.fill();g.globalAlpha=1;\n let px=cx,py=fy+4;if(state=='play'&&T<t0){const p=Math.min(1,(T-iS)/(t0-iS-.5));if(p<1){px=st.x-s*50+(cx-st.x+s*50)*(1-(1-p)*(1-p));a='walk';i=p<.6?4+(Math.floor(T*9)%2):Math.floor(T*8)%4}}else if(state=='play'&&fin_&&T<fin_.u){const q=(T-fin_.s)/(fin_.u-fin_.s);a='power';i=Math.floor(q*14)%7;py-=Math.sin(Math.PI*Math.min(1,q*1.2))*st.h*.1;sc=s*1.15;g.fillStyle='#fff';g.globalAlpha=.25*(1-q);g.fillRect(st.x,st.y,st.w,fy-st.y);g.globalAlpha=1}\n spr(a,i,px,py,sc);\n g.restore();\n // HUD\n g.textAlign='left';g.fillStyle='#fff';g.font='bold '+Math.max(16,st.h*.06)+'px monospace';const hs=Math.max(16,st.h*.06);\n g.fillText('SCORE '+score,st.x+12,st.y+hs+8);\n g.fillStyle='#222';g.fillRect(st.x+12,st.y+hs+18,st.w-24,10);g.fillStyle=hype>30?'#3ddc97':'#ff4d6d';g.fillRect(st.x+12,st.y+hs+18,(st.w-24)*hype/100,10);\n g.fillStyle='#aaa';g.font=(hs*.6)+'px monospace';g.fillText('CROWD HYPE',st.x+12,st.y+hs+44);\n if(state=='play'&&T<t0){g.textAlign='center';g.fillStyle='#ffd23f';g.font='bold '+hs*1.3+'px monospace';g.fillText('GET READY',cx,st.y+st.h*.3)}\n if(state=='play'&&combo>1){g.textAlign='center';g.fillStyle='#ffd23f';g.font='bold '+hs*1.3+'px monospace';g.fillText(combo+'x COMBO',cx,st.y+st.h*.3);g.fillStyle='#fff';g.font=(hs*.6)+'px monospace';g.fillText('FINISHER IN '+(15-combo%15),cx,st.y+st.h*.3+hs*.9)}\n texts=texts.filter(t=>T-t.t<.6);texts.forEach(t=>{g.textAlign='center';g.globalAlpha=1-(T-t.t)/.6;g.fillStyle=t.c;g.font='bold '+hs+'px monospace';g.fillText(t.s,cx,st.y+st.h*.5-(T-t.t)*60)});g.globalAlpha=1;\n // lanes\n g.fillStyle='#0d0d22';g.fillRect(ln.x,ln.y,ln.w,ln.h);\n const lw=ln.w/4,hy=ln.y+ln.h*.84,bh=Math.min(ln.h*.18,lw*.9),ty=ln.y-20,tr=1.5;\n LANES.forEach((L,l)=>{const x=ln.x+l*lw;g.fillStyle=L.col;g.globalAlpha=.07;g.fillRect(x,ln.y,lw,ln.h);g.globalAlpha=1;g.fillStyle='#222244';g.fillRect(x,ln.y,1,ln.h)});\n if(state=='play'){sched();hype=Math.max(0,hype);\n  for(const n of chart){const dt=t0+n.t*spb-T;if(!n.s&&dt<-.2){n.s=2;combo=0;hype-=8;stats.m++;pose={a:'hit',i:5,u:T+.5,miss:1};texts.push({s:'MISS',c:'#888',t:T})}\n   if(n.s==1||n.s==2||dt>tr)continue;const y=hy-dt/tr*(hy-ty),L=LANES[n.l],nw=lw*.8,nh=bh*.55;g.shadowColor=L.col;g.shadowBlur=14;g.fillStyle=L.col;rr(ln.x+n.l*lw+(lw-nw)/2,y-nh/2,nw,nh,10);g.fill();g.shadowBlur=0;g.fillStyle='#000';g.font='bold '+nh*.7+'px monospace';g.textAlign='center';g.fillText(L.k,ln.x+n.l*lw+lw/2,y+nh*.25)}\n  if(hype<=0)fin('over');else if(T>endT)fin('win')}\n LANES.forEach((L,l)=>{const x=ln.x+l*lw,pr=Math.max(0,1-(T-press[l])/.15);g.fillStyle=L.col;g.globalAlpha=.25+.6*pr;rr(x+lw*.08,hy-bh/2,lw*.84,bh,14);g.fill();g.globalAlpha=1;g.strokeStyle=L.col;g.lineWidth=3;g.stroke();g.fillStyle='#fff';g.textAlign='center';g.font='bold '+Math.min(bh*.4,lw*.18)+'px monospace';g.fillText(L.k,x+lw/2,hy+bh*.05);g.font=Math.min(bh*.2,lw*.11)+'px monospace';g.fillText(L.n,x+lw/2,hy+bh*.36)});\n // overlays\n if(state!='play'&&state!='menu'){g.fillStyle='rgba(5,5,20,.72)';g.fillRect(ln.x,ln.y,ln.w,ln.h);g.textAlign='center';const mx=ln.x+ln.w/2,u=Math.min(ln.w/14,ln.h/12);g.fillStyle='#4cc9f0';g.font='bold '+u*1.8+'px monospace';\n  const title=state=='menu'?'WISH JAM':state=='win'?'YOU WON THE BATTLE!':'CROWD WENT HOME';g.fillText(title,mx,ln.y+ln.h*.28);\n  g.fillStyle='#fff';g.font=u*1.1+'px monospace';\n  if(state=='menu'){g.fillText('Tap the lane as notes hit the pads',mx,ln.y+ln.h*.5);g.fillText('Keys: \u2190 \u2193 \u2191 \u2192  or  A S W D',mx,ln.y+ln.h*.5+u*1.5)}\n  else{g.fillText('Score '+score+'   Best combo '+best_,mx,ln.y+ln.h*.45);g.fillText('Perfect '+stats.p+'  Good '+stats.g+'  Miss '+stats.m,mx,ln.y+ln.h*.45+u*1.5)}\n  g.fillStyle='#ffd23f';g.font='bold '+u*1.4+'px monospace';g.globalAlpha=.6+.4*Math.sin(T*5);g.fillText(sheet?(state=='menu'?'TAP TO START':'TAP TO PLAY AGAIN'):'LOADING\u2026',mx,ln.y+ln.h*.78);g.globalAlpha=1}\n if(state=='menu'&&spl.naturalWidth)splash();\n}\nfunction splash(){const w=spl.naturalWidth,h=spl.naturalHeight;let s=Math.max(W/w,H/h);g.imageSmoothingEnabled=true;g.drawImage(spl,(W-w*s)/2,(H-h*s)/2,w*s,h*s);g.fillStyle='rgba(0,0,0,.6)';g.fillRect(0,0,W,H);s=Math.min(W/w,H/h);g.drawImage(spl,(W-w*s)/2,(H-h*s)/2,w*s,h*s)}\naddEventListener('keydown',e=>{if(e.key==='Escape'){try{parent.postMessage({wishJam:'close'},'*')}catch(_){}}});\nframe();\n<\/script><\/body><\/html>\n";
let wishJamOverlayEl = null, wishJamOverlayFrame = null;
let wishJamReturnState = 'play';
let wishJamHistoryPushed = false; // mirrors reverbReefHistoryPushed -- see openWishJamApp()/closeWishJamApp()

function createWishJamOverlay() {
  const style = document.createElement('style');
  style.textContent = `
    #wishJamApp {
      position: fixed; inset: 0; z-index: 1000;
      background: #000;
      display: none; flex-direction: column;
    }
    #wishJamApp.open { display: flex; }
    #wishJamApp .wj-bar {
      flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between;
      gap: 12px; padding: 10px 14px;
      background: linear-gradient(#2a0f4f, #12062a);
      border-bottom: 2px solid #4cc9f0;
      padding-top: calc(10px + env(safe-area-inset-top, 0px));
    }
    #wishJamApp .wj-title {
      color: #eaf9ff; font: bold 14px monospace; letter-spacing: 0.5px;
      white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    }
    #wishJamApp .wj-close {
      flex: 0 0 auto; cursor: pointer;
      background: rgba(76,201,240,0.15);
      border: 1.5px solid rgba(76,201,240,0.9);
      color: #eaf9ff; border-radius: 8px;
      padding: 7px 16px; font: bold 13px monospace;
      -webkit-user-select: none; user-select: none;
    }
    #wishJamApp .wj-close:active { background: rgba(76,201,240,0.45); }
    #wishJamApp iframe {
      flex: 1 1 auto; width: 100%; border: 0; background: #0a0a1a;
    }
  `;
  document.head.appendChild(style);

  wishJamOverlayEl = document.createElement('div');
  wishJamOverlayEl.id = 'wishJamApp';

  const bar = document.createElement('div');
  bar.className = 'wj-bar';
  const title = document.createElement('div');
  title.className = 'wj-title';
  title.textContent = 'WISH JAM \u2014 BREAKDANCE BATTLE';
  const closeBtn = document.createElement('div');
  closeBtn.className = 'wj-close';
  closeBtn.textContent = '\u2190 BACK TO THE PARK';
  bindTap(closeBtn, closeWishJamApp);
  bar.appendChild(title);
  bar.appendChild(closeBtn);

  wishJamOverlayFrame = document.createElement('iframe');
  wishJamOverlayFrame.setAttribute('allow', 'autoplay');

  wishJamOverlayEl.appendChild(bar);
  wishJamOverlayEl.appendChild(wishJamOverlayFrame);
  document.body.appendChild(wishJamOverlayEl);

  // [Esc] pressed while the iframe itself has keyboard focus never reaches
  // this page's keydown handler, so the app posts a message instead.
  window.addEventListener('message', (e) => {
    if (!wishJamOverlayFrame || e.source !== wishJamOverlayFrame.contentWindow) return;
    if (e.data && e.data.wishJam === 'close' && state === 'wishJamApp') closeWishJamApp();
  });
}
createWishJamOverlay();

// Opens the WISH JAM overlay and switches state to 'wishJamApp'. Called from
// MINIGAME_ACTIONS.wishjam (E on the b-boy mat, or tapping its floating
// sign), same entry points every other mini-game uses.
function openWishJamApp() {
  wishJamReturnState = state;
  wishJamOverlayFrame.srcdoc = WISH_JAM_HTML;
  wishJamOverlayEl.classList.add('open');
  state = 'wishJamApp';
  wishJamOverlayFrame.addEventListener('load', () => {
    try { wishJamOverlayFrame.contentWindow.focus(); } catch (e) { /* a tap will focus it */ }
  }, { once: true });
  // Same throwaway-history-entry trick as openReverbReefApp() etc., so the
  // browser/OS back gesture closes the overlay instead of leaving the game.
  history.pushState({ wishJamApp: true }, '');
  wishJamHistoryPushed = true;
}

// Tears the iframe back down (which also stops all audio) and returns to
// ordinary gameplay in the park. fromPopState mirrors closeReverbReefApp()'s
// parameter -- true when triggered by the browser's back button (whose
// history entry is already consumed), so we must not call history.back()
// again in that case.
function closeWishJamApp(fromPopState) {
  wishJamOverlayEl.classList.remove('open');
  wishJamOverlayFrame.removeAttribute('srcdoc');
  wishJamOverlayFrame.src = 'about:blank';
  reclaimGameFocus(wishJamOverlayFrame);
  state = wishJamReturnState;
  if (!fromPopState && wishJamHistoryPushed) {
    wishJamHistoryPushed = false;
    history.back();
  } else {
    wishJamHistoryPushed = false;
  }
}

// SKATEBOARDING & HIP-HOP CULTURE -- a read-and-explore encyclopedia-style
// page that lives inside TALENT (LEVEL 3, SKATEPARK) on a little zine stand in
// the middle of the shop floor (see TALENT's `minigames` list and
// drawMinigameZineStand()). Same "full-screen DOM overlay with an <iframe>"
// pattern as WISH JAM above, and just as offline-proof: the entire page is
// inlined below as SKATE_HIPHOP_READER_HTML and loaded through iframe.srcdoc,
// so there is no extra file to ship and no network call. Its contents links
// scroll in-page; its external reference links only open when online (offline
// they show a small "needs a connection" note instead of navigating the
// iframe away). [Esc] inside the iframe posts a message back (keys typed
// there never reach this page).
const SKATE_HIPHOP_READER_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"description\" content=\"An encyclopedia-style overview of the historical and cultural connections between skateboarding and hip-hop.\">\n<title>Skateboarding and Hip-Hop Culture \u2014 Cultural Overview<\/title>\n<style>\n:root{--ink:#202122;--muted:#54595d;--line:#a2a9b1;--link:#0645ad;--paper:#fff;--soft:#f8f9fa;--accent:#3366cc}\n*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}\na{color:var(--link);text-decoration:none}a:hover{text-decoration:underline}header{border-bottom:1px solid var(--line);padding:20px max(22px,calc((100% - 1180px)/2));background:var(--soft)}\n.brand{font-family:Georgia,serif;font-size:1.05rem;color:var(--muted);letter-spacing:.02em}.brand strong{color:var(--ink);font-weight:600}\n.shell{max-width:1180px;margin:auto;padding:28px 22px 70px;display:grid;grid-template-columns:220px minmax(0,1fr);gap:38px}\nnav{align-self:start;position:sticky;top:18px;border:1px solid #eaecf0;background:#fff;padding:16px;border-radius:4px;font-size:.92rem}\nnav h2{font:600 1rem Georgia,serif;margin:0 0 10px;border-bottom:1px solid #eaecf0;padding-bottom:8px}nav ol{margin:0;padding-left:20px}nav li{margin:5px 0}\nmain{min-width:0}h1,h2,h3{font-family:Georgia,\"Times New Roman\",serif;line-height:1.25;font-weight:500}h1{font-size:2.25rem;margin:0 0 8px}h2{font-size:1.55rem;border-bottom:1px solid var(--line);padding-bottom:7px;margin:34px 0 14px}h3{font-size:1.18rem;margin:23px 0 7px}.subtitle{color:var(--muted);margin:0 0 22px}.notice{border:1px solid #c8ccd1;background:var(--soft);padding:12px 15px;font-size:.92rem;margin:18px 0 22px}.lead{font-size:1.07rem}.infobox{float:right;width:min(310px,43%);margin:0 0 20px 24px;border:1px solid var(--line);background:var(--soft);padding:14px;font-size:.92rem}.infobox h2{font:600 1.08rem Georgia,serif;text-align:center;border:0;margin:0 0 10px;padding:0}.infobox dl{display:grid;grid-template-columns:100px 1fr;gap:6px 10px;margin:0}.infobox dt{font-weight:650}.infobox dd{margin:0}.caption{font-size:.82rem;color:var(--muted);text-align:center;margin-top:9px}.tagline{font:italic 1rem Georgia,serif;text-align:center;color:#54595d;border-top:1px solid #eaecf0;padding-top:10px;margin-top:12px}p{margin:0 0 15px}sup a{font-size:.78rem}.timeline{border-left:3px solid #c8ccd1;margin:16px 0 22px 8px;padding-left:18px}.era{margin:0 0 17px}.era strong{display:block}.related{background:var(--soft);border:1px solid #eaecf0;padding:14px 17px}.refs{padding-left:24px}.refs li{padding:0 0 10px;overflow-wrap:anywhere}.footer{border-top:1px solid var(--line);margin-top:35px;padding-top:15px;color:var(--muted);font-size:.85rem}.smallcaps{text-transform:uppercase;letter-spacing:.08em;font-size:.74rem;color:var(--muted)}\n@media(max-width:780px){.shell{grid-template-columns:1fr;gap:22px;padding-top:20px}nav{position:static;order:0}main{order:1}.infobox{float:none;width:100%;margin:0 0 20px}h1{font-size:1.9rem}}\n@media print{nav{display:none}.shell{display:block;max-width:none}a{color:inherit;text-decoration:none}.infobox{break-inside:avoid}}\n<\/style>\n<\/head>\n<body>\n<header><div class=\"brand\"><strong>Culture Atlas<\/strong> &nbsp; / &nbsp; Independent reference page<\/div><\/header>\n<div class=\"shell\">\n<nav aria-label=\"Contents\"><h2>Contents<\/h2><ol>\n<li><a href=\"#overview\">Overview<\/a><\/li><li><a href=\"#origins\">Different origins, shared conditions<\/a><\/li><li><a href=\"#nyc\">New York convergence<\/a><\/li><li><a href=\"#music\">Music and skate videos<\/a><\/li><li><a href=\"#style\">Fashion, graphics and identity<\/a><\/li><li><a href=\"#spaces\">The city as a canvas<\/a><\/li><li><a href=\"#people\">People and representation<\/a><\/li><li><a href=\"#mainstream\">Mainstream visibility<\/a><\/li><li><a href=\"#differences\">Differences and tensions<\/a><\/li><li><a href=\"#legacy\">Legacy<\/a><\/li><li><a href=\"#references\">References<\/a><\/li>\n<\/ol><\/nav>\n<main>\n<div class=\"smallcaps\">Cultural history \u00b7 Music \u00b7 Street sports<\/div>\n<h1>Skateboarding and Hip-Hop Culture<\/h1>\n<p class=\"subtitle\">Historical connections, shared aesthetics, and cross-cultural influence<\/p>\n<aside class=\"infobox\">\n<h2>Skateboarding and hip-hop<\/h2>\n<dl>\n<dt>Relationship<\/dt><dd>Cross-pollination between youth cultures<\/dd>\n<dt>Key period<\/dt><dd>Late 1980s onward; especially 1990s New York<\/dd>\n<dt>Shared settings<\/dt><dd>Streets, plazas, parks, music venues and independent shops<\/dd>\n<dt>Shared media<\/dt><dd>Photography, graffiti, magazines, VHS, music videos and online clips<\/dd>\n<dt>Related fields<\/dt><dd>Streetwear, DJ culture, graphic design, filmmaking<\/dd>\n<\/dl>\n<div class=\"tagline\">Two practices shaped by rhythm, style, space and self-expression.<\/div>\n<\/aside>\n<section id=\"overview\">\n<h2>Overview<\/h2>\n<p class=\"lead\"><b>Skateboarding and hip-hop culture<\/b> have influenced one another through music, fashion, visual art, street life and independent media. Their connection became especially visible in the late 1980s and 1990s, when street skateboarding and hip-hop scenes overlapped in cities such as New York and San Francisco. Skate videos increasingly used rap soundtracks; skaters and rappers shared clothing and graphic styles; and young people moved between skate spots, record stores, parties, galleries and music venues.<sup><a href=\"#ref1\">[1]<\/a><\/sup><sup><a href=\"#ref2\">[2]<\/a><\/sup><\/p>\n<p>The relationship is not exclusive or universal. Skateboarding has long been associated with surfing, punk, hardcore, metal, funk and many other musical traditions. Hip-hop, meanwhile, emerged from specific Black and Latino communities and includes MCing, DJing, breaking, graffiti and broader cultural practices. The connection between the two is best understood as an evolving exchange\u2014not as evidence that either culture originated from the other.<\/p>\n<\/section>\n<section id=\"origins\">\n<h2>Different origins, shared conditions<\/h2>\n<p>Modern skateboarding developed in California in the mid-20th century, with roots in surfing and later in freestyle, pool and ramp skating. Hip-hop emerged in the Bronx in New York City during the 1970s, shaped by Black, Puerto Rican and Caribbean American communities, block parties, DJ techniques, MCing, breaking and graffiti. Their beginnings were geographically and historically distinct.<sup><a href=\"#ref3\">[3]<\/a><\/sup><sup><a href=\"#ref4\">[4]<\/a><\/sup><\/p>\n<p>Over time, both became participatory cultures in which people could develop a recognizable style without needing formal institutions. Skaters learned through practice, watching peers and filming tricks. Hip-hop practitioners developed skills through cyphers, parties, DJ sets, writing, recording and local scenes. In both, reputation was often built through creativity, persistence, knowledge and contributions to a community.<\/p>\n<p>Both cultures also made use of spaces that were not designed specifically for them. Skaters transformed stairs, handrails, ledges and plazas into places to practice. Hip-hop artists used parks, community rooms, sidewalks and available sound equipment to create gatherings and performances. This did not mean the cultures were identical, but it gave them overlapping ways of making culture in public.<\/p>\n<\/section>\n<section id=\"nyc\">\n<h2>New York and the convergence of the late 1980s and 1990s<\/h2>\n<p>Downtown Manhattan became an important meeting point for skateboarding and hip-hop during the late 1980s and early 1990s. Skaters, graffiti writers, DJs, rappers, photographers and filmmakers encountered one another in the same urban networks. The documentary <i>All the Streets Are Silent: The Convergence of Hip Hop and Skateboarding (1987\u20131997)<\/i> explores this period and the shared visual language that emerged from it.<sup><a href=\"#ref1\">[1]<\/a><\/sup><\/p>\n<p>New York skate crews and brands helped make this connection visible. Zoo York, founded by skaters with ties to graffiti and downtown street culture, drew on the city's subway-writing, skateboarding and hip-hop environments. Skaters such as Harold Hunter became memorable figures in the overlap between downtown skateboarding and hip-hop. The scene was not a single unified movement; it was a network of people whose interests and friendships crossed cultural boundaries.<\/p>\n<p>The city itself mattered. Dense streets and public plazas brought different communities into close contact, while restrictions on skating and the policing of public space gave some participants a shared experience of being treated as disruptive or out of place. These common pressures could create solidarity, even as each culture retained its own history and internal differences.<\/p>\n<\/section>\n<section id=\"music\">\n<h2>Music and skate videos<\/h2>\n<p>Music became one of the most direct bridges between the cultures. Skate videos combine movement, editing and soundtrack into a short portrait of a skater's personality. As home video cameras and VHS circulation spread, independent skate companies and crews could produce and distribute their own films. These videos functioned as entertainment, informal instruction and a way for geographically distant skaters to discover new styles.<sup><a href=\"#ref5\">[5]<\/a><\/sup><\/p>\n<p>Early skate soundtracks often leaned toward punk and hardcore, but the musical palette broadened. Funk, soul, jazz, alternative rock and hip-hop all became part of skate-video history. In the 1990s, videos featuring music from Bay Area rap groups\u2014including Hieroglyphics-related artists and Souls of Mischief\u2014helped connect skateboarding with regional hip-hop scenes. Soundtrack choices could become associated with particular teams, cities or editing styles.<sup><a href=\"#ref6\">[6]<\/a><\/sup><\/p>\n<p>Hip-hop production techniques also resonated with skate-video editing. A trick sequence can be structured like a beat: build-up, repetition, pause, impact and release. Scratches, loops, breaks and sharply cut samples suit the stop-start motion of tricks and the rhythm of a filmed line. This is an aesthetic parallel rather than a claim that skate editing directly derives from hip-hop music.<\/p>\n<p>As online video replaced much of the VHS-era distribution, the exchange continued through edits, social media clips, music videos and artist collaborations. The soundtrack remains a way for a skater or filmer to communicate taste and identity, not merely provide background noise.<\/p>\n<\/section>\n<section id=\"style\">\n<h2>Fashion, graphics and identity<\/h2>\n<p>Both cultures helped shape streetwear, but their styles were never fixed. Skateboarding's practical clothing\u2014durable pants, roomy shirts, sneakers and caps\u2014overlapped at different times with hip-hop silhouettes and sportswear. In the 1990s and beyond, baggy clothing, team jerseys, hoodies, workwear and skate shoes could appear in both scenes. The meaning of a garment depended on place, era and the people wearing it.<\/p>\n<p>Graphic design was another point of contact. Skate decks, wheels, stickers, T-shirts and magazine ads became portable canvases for illustration, lettering and identity. Graffiti-influenced lettering, bold logos, mascot characters, hand-drawn marks and DIY photocopied graphics appeared across street-oriented products. Hip-hop's visual arts traditions were an important influence on some skate brands, while skate companies developed their own irreverent and often abrasive design language.<\/p>\n<p>Both scenes also valued individual taste and customization: a deck covered in stickers, a hand-painted board, a mixtape, a homemade video, a tag or a carefully assembled outfit could communicate affiliations and personal style. Commercial brands later turned many of these visual codes into products, creating an ongoing tension between grassroots expression and marketing.<\/p>\n<\/section>\n<section id=\"spaces\">\n<h2>The city as a canvas<\/h2>\n<p>Street skateboarding reframes ordinary architecture as a field of possibilities. A ledge, stair set, bench or plaza may become a site for technical experimentation and filming. Graffiti and hip-hop likewise made the city a place for visual and musical expression, although the practices have different methods, histories and relationships to property and public space.<\/p>\n<p>This shared attention to urban space helps explain why skateboarding and hip-hop often appear together in photography, films and design. Both can document a neighborhood from the point of view of the people who use it, rather than from the perspective of official planning or tourism. At the same time, skating can damage property and graffiti can raise legal and community conflicts; describing the creative use of public space does not erase those disagreements.<\/p>\n<\/section>\n<section id=\"people\">\n<h2>People, race and representation<\/h2>\n<p>The overlap created room for people who did not fit narrow ideas of what a skater or hip-hop fan was supposed to look like. Black and Latino skaters, including figures such as Harold Hunter and later Stevie Williams, became visible within scenes that were often marketed and remembered through predominantly white skate imagery. Research on skateboarding has examined how race, class and commercial representation shape who is recognized as authentic or central to the culture.<sup><a href=\"#ref7\">[7]<\/a><\/sup><\/p>\n<p>Hip-hop's influence was not simply a matter of borrowing music or clothes. For some skaters, it offered a way to express identity and connect skating to the neighborhoods and communities they came from. Still, neither culture should be treated as monolithic: race, gender, class, geography and generation shape participation in different ways. Women and girls, for example, have contributed to both cultures while frequently receiving less attention in mainstream histories and media.<\/p>\n<\/section>\n<section id=\"mainstream\">\n<h2>Mainstream visibility and commercialization<\/h2>\n<p>By the 1990s, skateboarding's growing media profile and hip-hop's expanding commercial reach brought both cultures to wider audiences. Music videos, fashion campaigns, magazines, sneaker releases and celebrity appearances made the overlap increasingly visible. Later, rappers publicly embraced skateboarding, skaters collaborated with musicians, and brands marketed products to audiences spanning both scenes.<\/p>\n<p>Mainstream recognition brought resources, visibility and new opportunities, but it also raised questions about authenticity and appropriation. An independent scene can value experimentation and community reputation, while a corporation may prioritize recognizable imagery and sales. Scholars of skateboarding have described the tension between subcultural values and the commercial systems that grow around them.<sup><a href=\"#ref8\">[8]<\/a><\/sup><\/p>\n<p>That tension does not make every collaboration inauthentic. Artists, skaters, filmmakers and designers may use commercial platforms to fund their work or reach new audiences. The important distinction is between a living cultural exchange and the superficial use of cultural symbols without meaningful connection to the people who created them.<\/p>\n<\/section>\n<section id=\"differences\">\n<h2>Differences and tensions<\/h2>\n<p>Despite their overlap, skateboarding and hip-hop are not interchangeable. Skateboarding is a physical practice and sport with its own technical disciplines, equipment and histories. Hip-hop is a broad cultural movement with musical, dance, visual-art and social dimensions. A person may be deeply involved in one without participating in the other.<\/p>\n<p>Their musical relationship is also varied. Punk and hardcore remain central to many skate scenes, while others gravitate toward rap, soul, electronic music or no particular genre. Hip-hop artists have embraced skateboarding in different ways, from genuine long-term participation to occasional visual references. Any broad account should leave room for local differences rather than presenting one style as universal.<\/p>\n<\/section>\n<section id=\"legacy\">\n<h2>Legacy<\/h2>\n<p>The connection between skateboarding and hip-hop is now visible across music, streetwear, graphic design, filmmaking and online culture. Its significance lies less in a single origin story than in the ways people carried ideas between scenes: a rap track in a skate part, a graffiti-inspired deck graphic, a skater in a music video, a neighborhood crew filming its own work, or friends meeting through shared public spaces.<\/p>\n<p>Both cultures demonstrate how creative communities can develop distinctive languages outside traditional institutions, then influence global popular culture. Their histories also show that cultural exchange is most meaningful when it acknowledges the specific people, places and traditions involved.<\/p>\n<\/section>\n<section class=\"related\">\n<h2>See also<\/h2>\n<ul>\n<li><a href=\"https://en.wikipedia.org/wiki/Hip-hop_culture\">Hip-hop culture<\/a><\/li>\n<li><a href=\"https://en.wikipedia.org/wiki/Street_skateboarding\">Street skateboarding<\/a><\/li>\n<li><a href=\"https://en.wikipedia.org/wiki/Graffiti\">Graffiti<\/a><\/li>\n<li><a href=\"https://en.wikipedia.org/wiki/Streetwear\">Streetwear<\/a><\/li>\n<li><a href=\"https://en.wikipedia.org/wiki/Skate_video\">Skate video<\/a><\/li>\n<\/ul>\n<\/section>\n<section id=\"references\">\n<h2>References and further reading<\/h2>\n<ol class=\"refs\">\n<li id=\"ref1\"> <i>All the Streets Are Silent: The Convergence of Hip Hop and Skateboarding (1987\u20131997)<\/i>, official film website. <a href=\"https://www.allthestreetsaresilent.com/\">allthestreetsaresilent.com<\/a>.<\/li>\n<li id=\"ref2\">PBS, <i>The Surprising Origins of Streetwear<\/i>, series episode exploring the parallel development and eventual overlap of hip-hop and skate culture. <a href=\"https://www.pbs.org/video/the-surprising-origins-of-streetwear-llrzyu/\">PBS video<\/a>.<\/li>\n<li id=\"ref3\">HISTORY, \u201cWho Invented Skateboarding?\u201d Background on skateboarding's development and its youth-culture associations. <a href=\"https://www.history.com/articles/skateboarding-origins-california\">HISTORY<\/a>.<\/li>\n<li id=\"ref4\">\u201cHip-hop culture,\u201d overview of the movement's elements and historical development. <a href=\"https://en.wikipedia.org/wiki/Hip-hop_culture\">Wikipedia<\/a>.<\/li>\n<li id=\"ref5\">\u201cRecording the Ride,\u201d exhibition recap on the development and circulation of skate videos. <a href=\"https://vimeo.com/1082510887\">Vimeo<\/a>.<\/li>\n<li id=\"ref6\">TransWorld SKATEboarding, \u201cThe Chronological History of Skateboard Video Soundtracks,\u201d including the 1990s Bay Area hip-hop period. <a href=\"https://www.skateboarding.com/news/the-chronological-history-of-skateboard-video-soundtracks\">TransWorld SKATEboarding<\/a>.<\/li>\n<li id=\"ref7\">\u201cRacial diversity in skateboarding: destabilising whiteness, decentring heartlands,\u201d <i>Sport in Society<\/i> (2023). <a href=\"https://www.tandfonline.com/doi/full/10.1080/17430437.2023.2208079\">Taylor &amp; Francis<\/a>.<\/li>\n<li id=\"ref8\">\u00c5sa B\u00e4ckstr\u00f6m and Shane Blackman, \u201cSkateboarding: From Urban Spaces to Subcultural Olympians,\u201d <i>Young<\/i> (2022). <a href=\"https://journals.sagepub.com/doi/10.1177/11033088221081944\">SAGE Journals<\/a>.<\/li>\n<\/ol>\n<\/section>\n<div class=\"footer\">This is an independent, encyclopedia-style educational page, not a Wikipedia article and not affiliated with the Wikimedia Foundation. It is designed as a self-contained HTML document; external reference links require an internet connection.<\/div>\n<\/main>\n<\/div>\n<style>#gtoast{position:fixed;left:50%;bottom:22px;transform:translateX(-50%);background:#12151c;color:#fbe600;border:2px solid #55bbee;padding:10px 16px;border-radius:8px;font:bold 13px monospace;z-index:99;display:none;max-width:90%;text-align:center}<\/style>\n<div id=\"gtoast\" role=\"status\"><\/div>\n<script>\n(function(){\n  var tt;\n  function toast(m){var t=document.getElementById('gtoast');t.textContent=m;t.style.display='block';clearTimeout(tt);tt=setTimeout(function(){t.style.display='none';},2600);}\n  document.addEventListener('keydown',function(e){\n    if(e.key==='Escape'){try{parent.postMessage({skateHipHopReader:'close'},'*');}catch(x){}}\n  });\n  document.addEventListener('click',function(e){\n    var a=e.target.closest&&e.target.closest('a');\n    if(!a)return;\n    var h=a.getAttribute('href')||'';\n    e.preventDefault();\n    if(h.charAt(0)==='#'){var t=document.getElementById(h.slice(1));if(t)t.scrollIntoView({behavior:'smooth',block:'start'});return;}\n    if(navigator.onLine===false){toast('That link needs an internet connection.');return;}\n    window.open(a.href,'_blank','noopener');\n  });\n  window.addEventListener('load',function(){try{window.focus();}catch(x){}});\n})();\n<\/script>\n<\/body>\n<\/html>";
let skateHipHopReaderOverlayEl = null, skateHipHopReaderOverlayFrame = null;
let skateHipHopReaderReturnState = 'play';
let skateHipHopReaderHistoryPushed = false; // mirrors wishJamHistoryPushed -- see openSkateHipHopReaderApp()/closeSkateHipHopReaderApp()

function createSkateHipHopReaderOverlay() {
  const style = document.createElement('style');
  style.textContent = `
    #skateHipHopReaderApp {
      position: fixed; inset: 0; z-index: 1000;
      background: #000;
      display: none; flex-direction: column;
    }
    #skateHipHopReaderApp.open { display: flex; }
    #skateHipHopReaderApp .shr-bar {
      flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between;
      gap: 12px; padding: 10px 14px;
      background: linear-gradient(#1a1f2b, #12151c);
      border-bottom: 2px solid #55bbee;
      padding-top: calc(10px + env(safe-area-inset-top, 0px));
    }
    #skateHipHopReaderApp .shr-title {
      color: #fbe600; font: bold 14px monospace; letter-spacing: 0.5px;
      white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    }
    #skateHipHopReaderApp .shr-close {
      flex: 0 0 auto; cursor: pointer;
      background: rgba(85,187,238,0.15);
      border: 1.5px solid rgba(85,187,238,0.9);
      color: #eaf6ff; border-radius: 8px;
      padding: 7px 16px; font: bold 13px monospace;
      -webkit-user-select: none; user-select: none;
    }
    #skateHipHopReaderApp .shr-close:active { background: rgba(85,187,238,0.45); }
    #skateHipHopReaderApp iframe {
      flex: 1 1 auto; width: 100%; border: 0; background: #fff;
    }
  `;
  document.head.appendChild(style);

  skateHipHopReaderOverlayEl = document.createElement('div');
  skateHipHopReaderOverlayEl.id = 'skateHipHopReaderApp';

  const bar = document.createElement('div');
  bar.className = 'shr-bar';
  const title = document.createElement('div');
  title.className = 'shr-title';
  title.textContent = 'SKATEBOARDING & HIP-HOP CULTURE \u2014 TALENT READING LIST';
  const closeBtn = document.createElement('div');
  closeBtn.className = 'shr-close';
  closeBtn.textContent = '\u2190 BACK TO THE SHOP';
  bindTap(closeBtn, closeSkateHipHopReaderApp);
  bar.appendChild(title);
  bar.appendChild(closeBtn);

  skateHipHopReaderOverlayFrame = document.createElement('iframe');

  skateHipHopReaderOverlayEl.appendChild(bar);
  skateHipHopReaderOverlayEl.appendChild(skateHipHopReaderOverlayFrame);
  document.body.appendChild(skateHipHopReaderOverlayEl);

  window.addEventListener('message', (e) => {
    if (!skateHipHopReaderOverlayFrame || e.source !== skateHipHopReaderOverlayFrame.contentWindow) return;
    if (e.data && e.data.skateHipHopReader === 'close' && state === 'skateHipHopReaderApp') closeSkateHipHopReaderApp();
  });
}
createSkateHipHopReaderOverlay();

// Opens the reader overlay and switches state to 'skateHipHopReaderApp'.
// Called from MINIGAME_ACTIONS.skatehiphopreader (E on the zine stand, or
// tapping its floating sign).
function openSkateHipHopReaderApp() {
  skateHipHopReaderReturnState = state;
  skateHipHopReaderOverlayFrame.srcdoc = SKATE_HIPHOP_READER_HTML;
  skateHipHopReaderOverlayEl.classList.add('open');
  state = 'skateHipHopReaderApp';
  skateHipHopReaderOverlayFrame.addEventListener('load', () => {
    try { skateHipHopReaderOverlayFrame.contentWindow.focus(); } catch (e) { /* a tap will focus it */ }
  }, { once: true });
  history.pushState({ skateHipHopReaderApp: true }, '');
  skateHipHopReaderHistoryPushed = true;
}

// Tears the iframe back down and returns to ordinary gameplay in TALENT.
// fromPopState: true when triggered by the browser's back button (history
// entry already consumed), so we must not call history.back() again.
function closeSkateHipHopReaderApp(fromPopState) {
  skateHipHopReaderOverlayEl.classList.remove('open');
  skateHipHopReaderOverlayFrame.removeAttribute('srcdoc');
  skateHipHopReaderOverlayFrame.src = 'about:blank';
  reclaimGameFocus(skateHipHopReaderOverlayFrame);
  state = skateHipHopReaderReturnState;
  if (!fromPopState && skateHipHopReaderHistoryPushed) {
    skateHipHopReaderHistoryPushed = false;
    history.back();
  } else {
    skateHipHopReaderHistoryPushed = false;
  }
}


// TRAV SKATES -- an endless skate run starring Trav (ollie, kickflip/heelflip/
// shove-it tricks, rail grinds, shamrock coins, day-to-sunset-to-night), on a
// floating skateboard sign inside TALENT (LEVEL 3, SKATEPARK). Same "full-screen
// DOM overlay with an <iframe>" pattern as the zine reader above and just as
// offline-proof: the whole game -- canvas code, CSS and both sprites as data
// URIs -- is inlined as TRAV_SKATES_HTML and loaded through iframe.srcdoc, so
// there is no extra file and no network call. [Esc] inside the iframe pauses
// (a second [Esc] posts a message back to close); its high score lives in
// localStorage, which srcdoc frames share with this page.
const TRAV_SKATES_TITLE_URI = "data:image/png;base64,";
const TRAV_SKATES_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>TRAV SKATES<\/title>\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover\">\n<style>\nhtml, body {\n  margin: 0;\n  padding: 0;\n  width: 100%;\n  height: 100%;\n  background: #0b1020;\n  overflow: hidden;\n  overscroll-behavior: none;\n  touch-action: none;\n  -webkit-user-select: none;\n  user-select: none;\n  -webkit-touch-callout: none;\n  -webkit-tap-highlight-color: transparent;\n}\n\ncanvas#game {\n  position: fixed;\n  inset: 0;\n  display: block;\n  width: 100%;\n  height: 100%;\n  image-rendering: pixelated;\n  image-rendering: crisp-edges;\n  touch-action: none;\n}\n\n#loading {\n  position: fixed;\n  inset: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  color: #fff;\n  font: bold 20px \"Courier New\", Courier, monospace;\n  letter-spacing: 2px;\n  background: #0b1020;\n  z-index: 5;\n  transition: opacity 0.25s;\n}\n\n#loading.hide {\n  opacity: 0;\n  pointer-events: none;\n}\n\n<\/style>\n<\/head>\n<body>\n<canvas id=\"game\"><\/canvas>\n<div id=\"loading\">LOADING\u2026<\/div>\n<script>\n/* TRAV SKATES \u2014 a standalone endless skate run starring Trav.\n   Plain HTML5 canvas, no dependencies. Works on desktop + mobile, portrait + landscape. */\n(() => {\n'use strict';\n\n/* ------------------------------------------------------------------ helpers */\nconst canvas = document.getElementById('game');\nconst ctx = canvas.getContext('2d');\nconst loadingEl = document.getElementById('loading');\n\nconst clamp = (v, a, b) => Math.max(a, Math.min(b, v));\nconst lerp = (a, b, t) => a + (b - a) * t;\nconst rnd = (a, b) => a + Math.random() * (b - a);\nconst rint = (a, b) => Math.floor(rnd(a, b + 1));\nconst smooth = t => { t = clamp(t, 0, 1); return t * t * (3 - 2 * t); };\nfunction mulberry32(a) {\n  return function () {\n    a |= 0; a = a + 0x6D2B79F5 | 0;\n    let t = Math.imul(a ^ a >>> 15, 1 | a);\n    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;\n    return ((t ^ t >>> 14) >>> 0) / 4294967296;\n  };\n}\nconst hexRGB = c => [parseInt(c.slice(1, 3), 16), parseInt(c.slice(3, 5), 16), parseInt(c.slice(5, 7), 16)];\nfunction mix(c1, c2, t) {\n  const a = hexRGB(c1), b = hexRGB(c2);\n  return 'rgb(' + a.map((v, i) => Math.round(lerp(v, b[i], t))).join(',') + ')';\n}\nconst hash = (a, b, c) => {\n  let h = (a * 374761393 + b * 668265263 + c * 2147483647) | 0;\n  h = (h ^ (h >>> 13)) * 1274126177 | 0;\n  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;\n};\n\n/* ------------------------------------------------------------------ constants */\nconst GRAVITY = 1900;\nconst FAST_FALL = 3600;\nconst JUMP_V = 640;\nconst BASE_SPEED = 250;\nconst SPR_H = 84;                 // Trav's on-screen height (logical px)\nconst SAVE_KEY = 'travSkatesBest';\n\nconst THEMES = [\n  { name: 'MORNING SESSION', skyTop: '#5db8ff', skyBot: '#dff4ff', far: '#9db9d6', mid: '#6f8bad', near: '#3d5772', ground: '#5d6168', curb: '#c8c8c2', line: '#f1f1f1', win: '#c9e1f5' },\n  { name: 'SUNSET SESSION',  skyTop: '#3a2a6e', skyBot: '#ff9a5f', far: '#8c5b93', mid: '#5f3d72', near: '#3a2850', ground: '#423c4b', curb: '#8e8192', line: '#ecd9c6', win: '#ffd47a' },\n  { name: 'NIGHT SESSION',   skyTop: '#050a22', skyBot: '#1e2d60', far: '#1d2851', mid: '#151d3d', near: '#0d1329', ground: '#23262f', curb: '#4b505e', line: '#8e94a5', win: '#ffe28b' }\n];\n\n/* ------------------------------------------------------------------ view / sizing */\nlet W = 640, H = 360, gy = 288, DPR = 1, portrait = false, viewReady = false;\n\nfunction resize() {\n  const cw = window.innerWidth || 640, ch = window.innerHeight || 360;\n  DPR = Math.min(window.devicePixelRatio || 1, 3);\n  canvas.width = Math.max(1, Math.round(cw * DPR));\n  canvas.height = Math.max(1, Math.round(ch * DPR));\n  canvas.style.width = cw + 'px';\n  canvas.style.height = ch + 'px';\n  const wasPortrait = portrait;\n  const asp = cw / ch;\n  if (asp >= 1) { H = 360; W = H * asp; portrait = false; }\n  else { W = 400; H = W / asp; portrait = true; }\n  gy = Math.round(portrait ? H * 0.70 : H * 0.79);\n  ctx.imageSmoothingEnabled = false;\n  if (viewReady && wasPortrait !== portrait && G.state === 'play') pauseGame();\n  viewReady = true;\n}\n\n/* ------------------------------------------------------------------ assets */\nconst IMG = { rider: null, title: null };\nfunction loadImage(src) {\n  return new Promise(res => {\n    const im = new Image();\n    im.onload = () => res(im);\n    im.onerror = () => res(null);\n    im.src = src;\n  });\n}\n\n/* ------------------------------------------------------------------ audio */\nconst AU = { ctx: null, master: null, muted: false, step: 0, next: 0, noise: null };\ntry { AU.muted = localStorage.getItem('travSkatesMuted') === '1'; } catch (e) { /* ignore */ }\n\nfunction audioInit() {\n  if (AU.ctx) { if (AU.ctx.state === 'suspended') AU.ctx.resume(); return; }\n  try {\n    const C = window.AudioContext || window.webkitAudioContext;\n    if (!C) return;\n    AU.ctx = new C();\n    AU.master = AU.ctx.createGain();\n    AU.master.gain.value = AU.muted ? 0 : 0.55;\n    AU.master.connect(AU.ctx.destination);\n    const len = AU.ctx.sampleRate * 0.6;\n    const buf = AU.ctx.createBuffer(1, len, AU.ctx.sampleRate);\n    const d = buf.getChannelData(0);\n    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;\n    AU.noise = buf;\n  } catch (e) { AU.ctx = null; }\n}\nfunction tone(f0, f1, dur, type, vol, delay) {\n  if (!AU.ctx || AU.muted) return;\n  const t = AU.ctx.currentTime + (delay || 0);\n  const o = AU.ctx.createOscillator(), g = AU.ctx.createGain();\n  o.type = type || 'square';\n  o.frequency.setValueAtTime(f0, t);\n  o.frequency.exponentialRampToValueAtTime(Math.max(20, f1), t + dur);\n  g.gain.setValueAtTime(vol || 0.15, t);\n  g.gain.exponentialRampToValueAtTime(0.001, t + dur);\n  o.connect(g); g.connect(AU.master);\n  o.start(t); o.stop(t + dur + 0.02);\n}\nfunction noise(dur, vol, freq, delay) {\n  if (!AU.ctx || AU.muted || !AU.noise) return;\n  const t = AU.ctx.currentTime + (delay || 0);\n  const s = AU.ctx.createBufferSource(); s.buffer = AU.noise;\n  const f = AU.ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = freq || 1200;\n  const g = AU.ctx.createGain();\n  g.gain.setValueAtTime(vol || 0.2, t);\n  g.gain.exponentialRampToValueAtTime(0.001, t + dur);\n  s.connect(f); f.connect(g); g.connect(AU.master);\n  s.start(t); s.stop(t + dur);\n}\nfunction sfx(n) {\n  switch (n) {\n    case 'jump':  tone(260, 560, 0.14, 'square', 0.10); noise(0.08, 0.10, 2500); break;\n    case 'land':  noise(0.12, 0.22, 700); tone(120, 60, 0.1, 'triangle', 0.18); break;\n    case 'trick': tone(520, 880, 0.08, 'square', 0.09); tone(880, 1320, 0.1, 'square', 0.09, 0.08); break;\n    case 'clean': tone(660, 990, 0.1, 'triangle', 0.14); break;\n    case 'coin':  tone(988, 988, 0.05, 'square', 0.08); tone(1480, 1480, 0.12, 'square', 0.08, 0.05); break;\n    case 'grind': noise(0.07, 0.07, 5000); break;\n    case 'crash': noise(0.5, 0.4, 900); tone(220, 40, 0.5, 'sawtooth', 0.2); break;\n    case 'start': tone(330, 330, 0.08, 'square', 0.1); tone(440, 440, 0.08, 'square', 0.1, 0.09); tone(660, 660, 0.18, 'square', 0.1, 0.18); break;\n  }\n}\nconst BASS = [110, 0, 110, 0, 131, 0, 110, 0, 147, 0, 147, 0, 165, 0, 131, 0];\nconst LEAD = [0, 440, 0, 523, 0, 440, 0, 392, 0, 440, 0, 587, 0, 523, 0, 392];\nfunction playStep(step, t) {\n  const c = AU.ctx, i = step % 16;\n  const mk = (f, d, type, v) => {\n    const o = c.createOscillator(), g = c.createGain();\n    o.type = type; o.frequency.value = f;\n    g.gain.setValueAtTime(v, t); g.gain.exponentialRampToValueAtTime(0.001, t + d);\n    o.connect(g); g.connect(AU.master); o.start(t); o.stop(t + d + 0.02);\n  };\n  if (BASS[i]) mk(BASS[i], 0.22, 'triangle', 0.16);\n  if (LEAD[i] && (step % 32) >= 16) mk(LEAD[i], 0.12, 'square', 0.035);\n  if (i % 4 === 0) { mk(70, 0.12, 'sine', 0.22); }\n  if (i % 4 === 2 && AU.noise) {\n    const s = c.createBufferSource(); s.buffer = AU.noise;\n    const f = c.createBiquadFilter(); f.type = 'highpass'; f.frequency.value = 6000;\n    const g = c.createGain(); g.gain.setValueAtTime(0.05, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.05);\n    s.connect(f); f.connect(g); g.connect(AU.master); s.start(t); s.stop(t + 0.06);\n  }\n}\nfunction musicTick() {\n  if (!AU.ctx || AU.muted || G.state !== 'play') return;\n  const stepDur = 60 / 128 / 4;\n  const now = AU.ctx.currentTime;\n  if (AU.next < now - 0.3) AU.next = now + 0.05;\n  let guard = 0;\n  while (AU.next < now + 0.15 && guard++ < 8) {\n    playStep(AU.step, AU.next);\n    AU.next += stepDur; AU.step = (AU.step + 1) % 32;\n  }\n}\nsetInterval(musicTick, 30);\nfunction toggleMute() {\n  AU.muted = !AU.muted;\n  if (AU.master) AU.master.gain.value = AU.muted ? 0 : 0.55;\n  try { localStorage.setItem('travSkatesMuted', AU.muted ? '1' : '0'); } catch (e) { /* ignore */ }\n}\n\n/* ------------------------------------------------------------------ game state */\nconst G = {\n  state: 'title',            // title | play | paused | dead\n  time: 0, dist: 0, speed: BASE_SPEED, bonus: 0, score: 0, best: 0, coins: 0,\n  obs: [], pickups: [], parts: [], texts: [],\n  spawnDist: 0, spawnIn: 0, shake: 0, banner: null, stage: 0, themeIdx: 0,\n  deadT: 0, titleT: 0, newBest: false, P: null, D: null, B: null, lastKind: ''\n};\ntry { G.best = parseInt(localStorage.getItem(SAVE_KEY) || '0', 10) || 0; } catch (e) { /* ignore */ }\n\nfunction newPlayer() {\n  return {\n    x: 100, h: 0, vh: 0, onGround: true, grind: null, grindT: 0, duck: false,\n    jumpHeld: false, jumped: false, coyote: 0, jumpBuf: 0,\n    trickT: 0, trickDur: 0.5, trickUsed: false, trickDone: false, trickKind: 0, trickName: '', trickDir: 1,\n    rot: 0, squash: 0\n  };\n}\nfunction startGame() {\n  audioInit();\n  G.state = 'play';\n  G.time = 0; G.dist = 0; G.bonus = 0; G.score = 0; G.coins = 0;\n  G.obs = []; G.pickups = []; G.parts = []; G.texts = [];\n  G.spawnDist = 0; G.spawnIn = 0; G.shake = 0; G.banner = null; G.stage = 0; G.deadT = 0;\n  G.newBest = false; G.D = null; G.B = null; G.lastKind = '';\n  G.P = newPlayer();\n  G.speed = BASE_SPEED * speedScale();\n  AU.next = AU.ctx ? AU.ctx.currentTime + 0.05 : 0; AU.step = 0;\n  sfx('start');\n}\nfunction pauseGame() { if (G.state === 'play') G.state = 'paused'; }\nfunction resumeGame() { if (G.state === 'paused') { G.state = 'play'; if (AU.ctx) AU.next = AU.ctx.currentTime + 0.05; } }\nconst speedScale = () => (portrait ? 0.86 : 1);\n\n/* ------------------------------------------------------------------ input */\nconst IN = { duckKey: false, ptr: new Map(), touchMode: false, jumpDownPtr: new Set() };\ntry { IN.touchMode = !!(window.matchMedia && window.matchMedia('(pointer: coarse)').matches); } catch (e) { /* ignore */ }\n\nfunction isDucking() {\n  if (IN.duckKey) return true;\n  for (const a of IN.ptr.values()) if (a === 'duck') return true;\n  return false;\n}\nfunction pressJump() {\n  const P = G.P;\n  if (!P || G.state !== 'play') return;\n  P.jumpHeld = true;\n  if (P.onGround || P.grind || (P.coyote > 0 && !P.jumped)) { doJump(); return; }\n  if (P.vh < 0 && P.h < 26) { P.jumpBuf = 0.14; return; }       // about to land: buffer a jump\n  if (!P.trickUsed && P.h > 14) startTrick();\n}\nfunction releaseJump() {\n  const P = G.P;\n  if (!P) return;\n  P.jumpHeld = false;\n  if (P.jumped && P.vh > 470) P.vh = 470;                         // short hop if tapped\n}\nfunction action() {\n  audioInit();\n  if (G.state === 'title') startGame();\n  else if (G.state === 'dead') { if (G.deadT > 0.7) startGame(); }\n  else if (G.state === 'paused') resumeGame();\n  else pressJump();\n}\n\nwindow.addEventListener('keydown', e => {\n  const k = e.code;\n  if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(k)) e.preventDefault();\n  if (e.repeat) return;\n  if (k === 'Space' || k === 'ArrowUp' || k === 'KeyW' || k === 'Enter') action();\n  else if (k === 'ArrowDown' || k === 'KeyS') IN.duckKey = true;\n  else if (k === 'KeyP') { if (G.state === 'play') pauseGame(); else if (G.state === 'paused') resumeGame(); }\n  else if (k === 'Escape') { if (G.state === 'play') pauseGame(); else { try { parent.postMessage({ travSkates: 'close' }, '*'); } catch (err) { /* ignore */ } } }\n  else if (k === 'KeyM') toggleMute();\n});\nwindow.addEventListener('keyup', e => {\n  const k = e.code;\n  if (k === 'Space' || k === 'ArrowUp' || k === 'KeyW') releaseJump();\n  else if (k === 'ArrowDown' || k === 'KeyS') IN.duckKey = false;\n});\n\nfunction uiRects() {\n  const top = portrait ? 26 : 10, s = 30;\n  return {\n    pause: { x: W - 14 - s, y: top, w: s, h: s },\n    sound: { x: W - 14 - s * 2 - 8, y: top, w: s, h: s }\n  };\n}\nconst inRect = (r, x, y) => x >= r.x - 4 && x <= r.x + r.w + 4 && y >= r.y - 4 && y <= r.y + r.h + 4;\n\ncanvas.addEventListener('pointerdown', e => {\n  e.preventDefault();\n  audioInit();\n  if (e.pointerType === 'touch' || e.pointerType === 'pen') IN.touchMode = true;\n  const rect = canvas.getBoundingClientRect();\n  const lx = (e.clientX - rect.left) / rect.width * W;\n  const ly = (e.clientY - rect.top) / rect.height * H;\n  try { canvas.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ }\n  const ui = uiRects();\n  if (inRect(ui.sound, lx, ly)) { toggleMute(); IN.ptr.set(e.pointerId, 'ui'); return; }\n  if (G.state === 'play' && inRect(ui.pause, lx, ly)) { pauseGame(); IN.ptr.set(e.pointerId, 'ui'); return; }\n  if (G.state === 'play' && IN.touchMode && lx < W * 0.38) {\n    IN.ptr.set(e.pointerId, 'duck');\n    return;\n  }\n  IN.ptr.set(e.pointerId, 'jump');\n  action();\n}, { passive: false });\n\nfunction pointerEnd(e) {\n  const a = IN.ptr.get(e.pointerId);\n  IN.ptr.delete(e.pointerId);\n  if (a === 'jump') releaseJump();\n}\ncanvas.addEventListener('pointerup', pointerEnd);\ncanvas.addEventListener('pointercancel', pointerEnd);\ncanvas.addEventListener('contextmenu', e => e.preventDefault());\ndocument.addEventListener('touchmove', e => e.preventDefault(), { passive: false });\ndocument.addEventListener('visibilitychange', () => { if (document.hidden) pauseGame(); });\nwindow.addEventListener('blur', () => { IN.duckKey = false; pauseGame(); });\nwindow.addEventListener('resize', resize);\nwindow.addEventListener('orientationchange', () => setTimeout(resize, 120));\n\n/* ------------------------------------------------------------------ player actions */\nfunction doJump() {\n  const P = G.P;\n  P.vh = JUMP_V; P.h += 0.5; P.onGround = false; P.grind = null; P.jumped = true;\n  P.trickUsed = false; P.trickDone = false; P.trickT = 0; P.coyote = 0; P.jumpBuf = 0;\n  puff(P.x - 6, gy - 2, 4, 'rgba(255,255,255,0.55)', 0.6);\n  sfx('jump');\n}\nfunction startTrick() {\n  const P = G.P;\n  P.trickUsed = true; P.trickDone = false;\n  P.trickDur = 0.5; P.trickT = 0.5;\n  P.trickKind = Math.random() < 0.34 ? 1 : 0;\n  P.trickDir = Math.random() < 0.5 ? 1 : -1;\n  P.trickName = P.trickKind === 1 ? 'SHOVE-IT' : (P.trickDir > 0 ? 'KICKFLIP' : 'HEELFLIP');\n  sfx('trick');\n}\nfunction award(n, label, x, y, color) {\n  G.bonus += n;\n  floatText((label ? label + ' ' : '') + '+' + n, x, y, color || '#ffe14d');\n}\nfunction die(reason) {\n  if (G.state !== 'play') return;\n  const P = G.P;\n  G.state = 'dead'; G.deadT = 0; G.shake = 0.35;\n  const fy = gy - P.h;\n  G.D = { x: P.x, y: fy - 40, vx: -G.speed * 0.45, vy: -260, rot: 0, vr: -7, bounced: false, fall: reason === 'fall' };\n  G.B = { x: P.x, y: fy - 8, vx: G.speed * 0.25, vy: -380, rot: 0, vr: 11 };\n  if (reason === 'fall') { G.D.vx = 0; G.D.vy = 0; G.B.vx = 0; G.B.vy = -120; }\n  G.score = Math.floor(G.dist / 10) + G.bonus;\n  if (G.score > G.best) { G.best = G.score; G.newBest = true; try { localStorage.setItem(SAVE_KEY, String(G.best)); } catch (e) { /* ignore */ } }\n  puff(P.x, fy - 10, 14, 'rgba(255,255,255,0.8)', 1.2);\n  sfx('crash');\n  try { if (navigator.vibrate) navigator.vibrate(70); } catch (e) { /* ignore */ }\n}\n\n/* ------------------------------------------------------------------ effects */\nfunction puff(x, y, n, color, power) {\n  for (let i = 0; i < n; i++) {\n    G.parts.push({ x, y, vx: rnd(-60, 30) * (power || 1) - G.speed * 0.3, vy: rnd(-90, -10) * (power || 1), life: rnd(0.25, 0.55), max: 0.55, size: rnd(2, 4.5), color, g: 160 });\n  }\n}\nfunction sparks(x, y) {\n  for (let i = 0; i < 2; i++) {\n    G.parts.push({ x, y, vx: rnd(-140, 40) - G.speed * 0.2, vy: rnd(-170, -30), life: rnd(0.2, 0.4), max: 0.4, size: rnd(1.5, 3), color: Math.random() < 0.5 ? '#ffe14d' : '#ff9a2e', g: 600 });\n  }\n}\nfunction floatText(s, x, y, color) { G.texts.push({ s, x, y, vy: -38, life: 1.1, max: 1.1, color: color || '#fff' }); }\n\n/* ------------------------------------------------------------------ world spawning */\nconst OB = {\n  cone:   { w: 16, h: 20 },\n  can:    { w: 22, h: 34 },\n  bench:  { w: 58, h: 24 },\n  crates: { w: 32, h: 38 }\n};\nfunction addObstacle(k, x, w, h, b) { const o = { k, x, w, h, b: b || 0, top: h }; G.obs.push(o); return o; }\n\nfunction spawn() {\n  const x = W + 60, t = G.time, sp = G.speed;\n  const r = Math.random();\n  let kind, total = 0;\n  if (t > 5 && r < 0.18 && G.lastKind !== 'gap') kind = 'gap';\n  else if (t > 2 && r < 0.38 && G.lastKind !== 'rail') kind = 'rail';\n  else if (t > 8 && r < 0.52 && G.lastKind !== 'sign') kind = 'sign';\n  else kind = ['cone', 'can', 'bench', 'crates'][rint(0, 3)];\n  G.lastKind = kind;\n\n  if (kind === 'gap') {\n    const w = rnd(70, 100) + Math.max(0, sp - 250) * 0.12;\n    addObstacle('gap', x, w, 0);\n    total = w;\n    addArcCoins(x - 10, w + 20, 52);\n  } else if (kind === 'rail') {\n    const w = rnd(120, 190);\n    const o = addObstacle('rail', x, w, 28);\n    total = w;\n    for (let i = 0; i < Math.floor(w / 30); i++) G.pickups.push({ x: x + 20 + i * 30, h: 28 + 24, got: false, ph: i * 0.6, kind: 'coin' });\n    o.top = 28;\n  } else if (kind === 'sign') {\n    const w = rnd(70, 110);\n    addObstacle('sign', x, w, 96, 58);\n    total = w;\n    for (let i = 0; i < 4; i++) G.pickups.push({ x: x + 10 + i * (w - 20) / 3, h: 24, got: false, ph: i * 0.6, kind: 'coin' });\n  } else {\n    const d = OB[kind];\n    let h = d.h;\n    if (kind === 'crates' && t > 12 && Math.random() < 0.35) h = 66;\n    addObstacle(kind, x, d.w, h);\n    total = d.w;\n    if (t > 10 && Math.random() < 0.3) {\n      const x2 = x + d.w + rnd(34, 60);\n      addObstacle(kind, x2, d.w, h);\n      total = x2 + d.w - x;\n    }\n    if (Math.random() < 0.55) addArcCoins(x - 12, total + 24, Math.max(46, h + 22));\n  }\n  const minG = sp * 0.72 + (kind === 'gap' ? 70 : 0);\n  const maxG = sp * 1.45 + 40;\n  G.spawnDist = 0;\n  G.spawnIn = total + rnd(minG, maxG);\n\n  if (Math.random() < 0.3) {          // free ground-level coin line later on in the gap\n    const cx = x + total + 60, n = rint(4, 7);\n    for (let i = 0; i < n; i++) G.pickups.push({ x: cx + i * 26, h: 22, got: false, ph: i * 0.5, kind: 'coin' });\n  }\n}\nfunction addArcCoins(x, w, peak) {\n  const n = 5;\n  for (let i = 0; i < n; i++) {\n    const f = i / (n - 1);\n    G.pickups.push({ x: x + f * w, h: 24 + Math.sin(f * Math.PI) * (peak - 24 + 20), got: false, ph: i * 0.6, kind: 'coin' });\n  }\n}\nconst overGap = px => { for (const o of G.obs) if (o.k === 'gap' && px > o.x + 8 && px < o.x + o.w - 8) return true; return false; };\n\n/* ------------------------------------------------------------------ update */\nfunction update(dt) {\n  G.titleT += dt;\n  if (G.shake > 0) G.shake = Math.max(0, G.shake - dt);\n  if (G.banner) { G.banner.t -= dt; if (G.banner.t <= 0) G.banner = null; }\n\n  if (G.state === 'title') { G.dist += 70 * dt; G.speed = 70; updateFx(dt); return; }\n  if (G.state === 'paused') return;\n\n  if (G.state === 'dead') {\n    G.deadT += dt;\n    G.speed = Math.max(0, G.speed - 900 * dt);\n    G.dist += G.speed * dt;\n    scrollWorld(dt);\n    updateRagdoll(dt);\n    updateFx(dt);\n    return;\n  }\n\n  /* ---- playing ---- */\n  const P = G.P;\n  G.time += dt;\n  G.speed = (BASE_SPEED + Math.min(250, G.time * 5)) * speedScale();\n  G.dist += G.speed * dt;\n  G.score = Math.floor(G.dist / 10) + G.bonus;\n  P.x = portrait ? W * 0.25 : clamp(W * 0.22, 90, 200);\n  P.duck = isDucking();\n\n  G.spawnDist += G.speed * dt;\n  if (G.spawnDist >= G.spawnIn) spawn();\n  scrollWorld(dt);\n  updatePlayer(dt);\n  if (G.state !== 'play') return;\n  collide();\n  collect();\n  stageCheck();\n  updateFx(dt);\n}\nfunction scrollWorld(dt) {\n  const d = G.speed * dt;\n  for (const o of G.obs) o.x -= d;\n  for (const p of G.pickups) p.x -= d;\n  G.obs = G.obs.filter(o => o.x + o.w > -100);\n  G.pickups = G.pickups.filter(p => p.x > -40 && !p.got);\n}\nfunction updatePlayer(dt) {\n  const P = G.P;\n  P.squash = Math.max(0, P.squash - dt);\n  P.jumpBuf = Math.max(0, P.jumpBuf - dt);\n  if (!P.onGround && !P.grind) P.coyote = Math.max(0, P.coyote - dt);\n\n  // trick progress\n  if (P.trickT > 0) {\n    P.trickT -= dt;\n    if (P.trickT <= 0) { P.trickT = 0; P.trickDone = true; award(50, P.trickName, P.x, gy - P.h - 90, '#7dffa0'); sfx('clean'); }\n  }\n\n  if (P.grind) {\n    const r = P.grind;\n    P.h = r.top; P.vh = 0; P.grindT += dt;\n    sparks(P.x - 14, gy - P.h - 2);\n    if (Math.floor(P.grindT * 14) !== Math.floor((P.grindT - dt) * 14)) sfx('grind');\n    P.rot += (-0.04 - P.rot) * Math.min(1, dt * 10);\n    if (P.x > r.x + r.w - 4 || !G.obs.includes(r)) {\n      const pts = Math.max(10, Math.floor(P.grindT * 80));\n      award(pts, 'GRIND', P.x, gy - P.h - 90, '#ffe14d');\n      P.grind = null; P.grindT = 0; P.coyote = 0.1; P.jumped = false; P.onGround = false;\n    }\n    return;\n  }\n\n  if (P.onGround) {\n    P.h = 0; P.vh = 0;\n    if (overGap(P.x)) { P.onGround = false; P.coyote = 0.08; P.jumped = false; }\n    P.rot += (0 - P.rot) * Math.min(1, dt * 14);\n    return;\n  }\n\n  const prevH = P.h;\n  P.vh -= (P.duck ? FAST_FALL : GRAVITY) * dt;\n  P.h += P.vh * dt;\n  P.rot += (clamp(-P.vh * 0.0003, -0.22, 0.22) - P.rot) * Math.min(1, dt * 12);\n\n  if (prevH <= 0.001 && P.h < -6) { die('fall'); return; }          // dropped into a pit\n\n  let floorH = overGap(P.x) ? -Infinity : 0, rail = null;\n  if (P.vh <= 0) {\n    for (const o of G.obs) {\n      if (o.k === 'rail' && P.x >= o.x + 2 && P.x <= o.x + o.w - 2 && prevH >= o.top - 4 && P.h <= o.top) { floorH = Math.max(floorH, o.top); rail = o; }\n    }\n  }\n  if (P.h <= floorH && P.vh <= 0) {\n    P.h = floorH; P.vh = 0;\n    P.squash = 0.12;\n    if (rail) {\n      P.grind = rail; P.grindT = 0; P.onGround = false; P.jumped = false;\n      puff(P.x, gy - P.h, 5, '#ffe14d', 0.8); sfx('land');\n      if (P.trickDone) award(40, 'RAIL', P.x, gy - P.h - 90, '#7dffa0');\n    } else {\n      landOnGround();\n    }\n    resetTrick();\n  }\n}\nfunction resetTrick() { const P = G.P; P.trickUsed = false; P.trickDone = false; P.trickT = 0; }\nfunction landOnGround() {\n  const P = G.P;\n  P.onGround = true; P.jumped = false;\n  puff(P.x - 4, gy - 1, 6, 'rgba(255,255,255,0.6)', 0.8);\n  sfx('land');\n  if (P.trickDone) award(25, 'CLEAN', P.x, gy - 100, '#7dffa0');\n  else if (P.trickUsed) floatText('SKETCHY', P.x, gy - 100, '#ff9a8a');\n  if (P.jumpBuf > 0) doJump();\n}\nfunction collide() {\n  const P = G.P;\n  const l = P.x - 8, r = P.x + 8;\n  const pb = P.h + 3, pt = P.h + (P.duck ? 46 : 74);\n  for (const o of G.obs) {\n    if (o.k === 'gap') continue;\n    if (o === P.grind) continue;\n    const ol = o.x + 2, or = o.x + o.w - 2, ob = o.b, ot = o.top - 3;\n    if (l < or && r > ol && pb < ot && pt > ob) { die('hit'); return; }\n  }\n}\nfunction collect() {\n  const P = G.P;\n  const cy = P.h + (P.duck ? 24 : 38);\n  for (const c of G.pickups) {\n    if (c.got) continue;\n    if (Math.abs(c.x - P.x) < 18 && Math.abs(c.h - cy) < 30) {\n      c.got = true; G.coins++; G.bonus += 10;\n      floatText('+10', c.x, gy - c.h - 10, '#ffe14d');\n      puff(c.x, gy - c.h, 4, '#ffe14d', 0.5);\n      sfx('coin');\n    }\n  }\n}\nfunction stageCheck() {\n  const p = G.score / 1500;\n  const i = Math.floor(p) % 3;\n  if (i !== G.stage) { G.stage = i; G.banner = { txt: THEMES[i].name, t: 2.2 }; }\n}\nfunction updateRagdoll(dt) {\n  const D = G.D, B = G.B;\n  if (D) {\n    D.vy += 1500 * dt; D.x += D.vx * dt; D.y += D.vy * dt; D.rot += D.vr * dt;\n    if (!D.fall && D.y > gy - 22) {\n      D.y = gy - 22;\n      if (!D.bounced) { D.vy = -D.vy * 0.35; D.bounced = true; } else D.vy = 0;\n      D.vx *= 0.88; D.vr *= 0.9;\n    }\n  }\n  if (B) {\n    B.vy += 1500 * dt; B.x += B.vx * dt; B.y += B.vy * dt; B.rot += B.vr * dt;\n    if (!(D && D.fall) && B.y > gy - 6) { B.y = gy - 6; B.vy = -B.vy * 0.4; B.vx *= 0.7; B.vr *= 0.6; }\n  }\n}\nfunction updateFx(dt) {\n  for (const p of G.parts) { p.life -= dt; p.vy += p.g * dt; p.x += p.vx * dt; p.y += p.vy * dt; }\n  G.parts = G.parts.filter(p => p.life > 0);\n  for (const t of G.texts) { t.life -= dt; t.y += t.vy * dt; }\n  G.texts = G.texts.filter(t => t.life > 0);\n}\n\n/* ------------------------------------------------------------------ background */\nfunction genLayer(seed, n, wMin, wMax, hMin, hMax, gMin, gMax) {\n  const rng = mulberry32(seed); let x = 0; const items = [];\n  for (let i = 0; i < n; i++) {\n    const w = wMin + rng() * (wMax - wMin), h = hMin + rng() * (hMax - hMin);\n    items.push({ x, w, h, id: i, s: rng() });\n    x += w + gMin + rng() * (gMax - gMin);\n  }\n  return { items, len: x };\n}\nconst LAYERS = {\n  far: genLayer(11, 22, 46, 90, 0.32, 0.78, 0, 8),\n  mid: genLayer(7, 16, 62, 112, 0.22, 0.48, 4, 22),\n  near: genLayer(3, 12, 14, 30, 0.2, 0.4, 150, 260)\n};\nfunction theme() {\n  const p = Math.max(0, G.score) / 1500;\n  const i = Math.floor(p) % 3, f = p - Math.floor(p);\n  const f2 = smooth((f - 0.6) / 0.4);\n  const a = THEMES[i], b = THEMES[(i + 1) % 3];\n  const T = {};\n  for (const k of ['skyTop', 'skyBot', 'far', 'mid', 'near', 'ground', 'curb', 'line', 'win']) T[k] = mix(a[k], b[k], f2);\n  T.stars = i === 2 ? 1 - f2 : i === 1 ? f2 : 0;\n  T.dusk = i === 0 ? f2 : i === 1 ? 1 - f2 : 0;\n  T.night = T.stars;\n  return T;\n}\nfunction drawBuildings(layer, par, color, hs, T, windows) {\n  const off = (G.dist * par) % layer.len;\n  ctx.fillStyle = color;\n  for (let k = -1; k < 3; k++) {\n    for (const b of layer.items) {\n      const x = Math.round(b.x - off + k * layer.len);\n      if (x > W + 4 || x + b.w < -4) continue;\n      const bh = Math.round(b.h * hs), top = gy - bh;\n      ctx.fillStyle = color;\n      ctx.fillRect(x, top, Math.round(b.w), bh + 2);\n      if (b.s > 0.82) { ctx.fillRect(x + Math.round(b.w / 2) - 1, top - 14, 2, 14); }\n      else if (b.s < 0.2) { ctx.fillRect(x + 4, top - 6, Math.round(b.w) - 8, 6); }\n      if (windows) {\n        for (let wy = top + 8, row = 0; wy < gy - 10; wy += 13, row++) {\n          for (let wx = x + 6, col = 0; wx < x + b.w - 8; wx += 12, col++) {\n            const lit = hash(b.id + 3, row, col + k * 7) < 0.5 + T.night * 0.15;\n            if (!lit) continue;\n            ctx.globalAlpha = 0.22 + T.night * 0.65;\n            ctx.fillStyle = T.win;\n            ctx.fillRect(wx, wy, 5, 7);\n          }\n        }\n        ctx.globalAlpha = 1;\n      }\n    }\n  }\n}\nfunction drawNear(T) {\n  const layer = LAYERS.near, off = (G.dist * 0.65) % layer.len;\n  for (let k = -1; k < 3; k++) {\n    for (const it of layer.items) {\n      const x = Math.round(it.x - off + k * layer.len);\n      if (x > W + 40 || x < -60) continue;\n      if (it.s < 0.5) {            // tree\n        ctx.fillStyle = '#4a3322'; ctx.fillRect(x - 3, gy - 28, 6, 28);\n        ctx.fillStyle = mix('#2f7d3a', '#0f2a1c', Math.min(1, T.night * 0.8 + (1 - T.dusk) * 0 + T.dusk * 0.35));\n        ctx.fillRect(x - 18, gy - 56, 36, 26); ctx.fillRect(x - 12, gy - 68, 24, 14); ctx.fillRect(x - 22, gy - 46, 44, 10);\n      } else {                     // street lamp\n        ctx.fillStyle = '#2b2f3a'; ctx.fillRect(x - 2, gy - 70, 4, 70); ctx.fillRect(x - 2, gy - 70, 16, 4);\n        const glow = 0.25 + T.night * 0.75;\n        ctx.globalAlpha = glow * 0.35; ctx.fillStyle = '#ffe9a0'; ctx.fillRect(x + 6, gy - 66, 14, 30);\n        ctx.globalAlpha = Math.min(1, 0.4 + glow); ctx.fillRect(x + 8, gy - 66, 10, 5);\n        ctx.globalAlpha = 1;\n      }\n    }\n  }\n}\nfunction drawBackground(T) {\n  const g = ctx.createLinearGradient(0, 0, 0, gy);\n  g.addColorStop(0, T.skyTop); g.addColorStop(1, T.skyBot);\n  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);\n  // stars\n  if (T.stars > 0.02) {\n    ctx.fillStyle = '#fff';\n    for (let i = 0; i < 46; i++) {\n      const sx = hash(i, 1, 9) * W, sy = hash(i, 2, 9) * gy * 0.7;\n      ctx.globalAlpha = T.stars * (0.35 + 0.65 * Math.abs(Math.sin(G.titleT * 1.5 + i)));\n      ctx.fillRect(Math.round(sx), Math.round(sy), 2, 2);\n    }\n    ctx.globalAlpha = 1;\n  }\n  // sun / moon\n  const sunY = gy * lerp(0.2, 0.62, T.dusk), sx = W * 0.76;\n  if (T.stars < 0.95) {\n    ctx.globalAlpha = 1 - T.stars; ctx.fillStyle = mix('#fff2a8', '#ff7a3d', T.dusk);\n    ctx.beginPath(); ctx.arc(sx, sunY, 22, 0, Math.PI * 2); ctx.fill(); ctx.globalAlpha = 1;\n  }\n  if (T.stars > 0.05) {\n    ctx.globalAlpha = T.stars; ctx.fillStyle = '#f4f1de';\n    ctx.beginPath(); ctx.arc(W * 0.24, gy * 0.22, 16, 0, Math.PI * 2); ctx.fill();\n    ctx.fillStyle = T.skyTop; ctx.beginPath(); ctx.arc(W * 0.24 + 7, gy * 0.22 - 4, 14, 0, Math.PI * 2); ctx.fill();\n    ctx.globalAlpha = 1;\n  }\n  // clouds\n  const co = (G.dist * 0.06) % (W + 200);\n  ctx.globalAlpha = 0.55 * (1 - T.stars * 0.8); ctx.fillStyle = mix('#ffffff', '#c58aa8', T.dusk);\n  for (let i = 0; i < 4; i++) {\n    const cx = ((i * (W + 200) / 4 - co) % (W + 200) + (W + 200)) % (W + 200) - 100, cy = gy * (0.14 + 0.12 * ((i * 37) % 5) / 5);\n    ctx.fillRect(Math.round(cx), Math.round(cy), 56, 10); ctx.fillRect(Math.round(cx) + 10, Math.round(cy) - 8, 34, 10);\n  }\n  ctx.globalAlpha = 1;\n  const hs = Math.min(gy, 330);\n  drawBuildings(LAYERS.far, 0.12, T.far, hs, T, false);\n  drawBuildings(LAYERS.mid, 0.3, T.mid, hs, T, true);\n  drawNear(T);\n}\nfunction drawGround(T) {\n  ctx.fillStyle = T.ground; ctx.fillRect(0, gy, W, H - gy);\n  ctx.fillStyle = T.curb; ctx.fillRect(0, gy, W, 6);\n  ctx.fillStyle = 'rgba(0,0,0,0.28)'; ctx.fillRect(0, gy + 6, W, 3);\n  // sidewalk brick joints\n  ctx.fillStyle = 'rgba(0,0,0,0.16)';\n  const off = G.dist % 24;\n  for (let row = 0; row < 2; row++) {\n    const y = gy + 11 + row * 10;\n    ctx.fillRect(0, y + 9, W, 1);\n    for (let x = -off - (row ? 12 : 0); x < W; x += 24) ctx.fillRect(Math.round(x), y, 1, 9);\n  }\n  // road dashes\n  const dOff = G.dist % 90;\n  ctx.fillStyle = T.line;\n  const ry = gy + (H - gy) * 0.55;\n  for (let x = -dOff; x < W; x += 90) ctx.fillRect(Math.round(x), Math.round(ry), 44, 4);\n  ctx.fillStyle = 'rgba(0,0,0,0.12)';\n  for (let x = -((G.dist * 1.4) % 130); x < W; x += 130) ctx.fillRect(Math.round(x), Math.round(gy + (H - gy) * 0.8), 70, 2);\n}\n\n/* ------------------------------------------------------------------ obstacle / pickup drawing */\nfunction drawObstacles() {\n  // pits first so everything else sits above them\n  for (const o of G.obs) {\n    if (o.k !== 'gap') continue;\n    const x = Math.round(o.x), w = Math.round(o.w);\n    ctx.fillStyle = '#04050b'; ctx.fillRect(x, gy, w, H - gy);\n    const g = ctx.createLinearGradient(0, gy, 0, gy + 70);\n    g.addColorStop(0, 'rgba(255,170,40,0.28)'); g.addColorStop(1, 'rgba(0,0,0,0)');\n    ctx.fillStyle = g; ctx.fillRect(x, gy, w, 70);\n    ctx.fillStyle = '#ffcc00';\n    for (let i = 0; i < w; i += 16) { ctx.fillRect(x + i, gy, 8, 4); }\n    ctx.fillStyle = '#222'; for (let i = 8; i < w; i += 16) { ctx.fillRect(x + i, gy, 8, 4); }\n    ctx.fillStyle = 'rgba(255,255,255,0.12)'; ctx.fillRect(x, gy + 4, 2, H - gy); ctx.fillRect(x + w - 2, gy + 4, 2, H - gy);\n  }\n  for (const o of G.obs) {\n    const x = Math.round(o.x), w = Math.round(o.w);\n    switch (o.k) {\n      case 'cone': {\n        ctx.fillStyle = '#ff7a1a';\n        const h = o.h;\n        for (let r = 0; r < h - 4; r += 2) { const f = r / (h - 4); const cw = Math.round(4 + (w - 4) * f); ctx.fillRect(x + (w - cw) / 2, gy - h + 4 + r, cw, 2); }\n        ctx.fillStyle = '#fff'; ctx.fillRect(x + 4, gy - 12, w - 8, 3);\n        ctx.fillStyle = '#d95d0a'; ctx.fillRect(x - 1, gy - 4, w + 2, 4);\n        break;\n      }\n      case 'can': {\n        ctx.fillStyle = '#7d8a96'; ctx.fillRect(x + 1, gy - o.h + 4, w - 2, o.h - 4);\n        ctx.fillStyle = '#5f6b76'; ctx.fillRect(x - 2, gy - o.h, w + 4, 5);\n        ctx.fillStyle = 'rgba(0,0,0,0.25)'; ctx.fillRect(x + 6, gy - o.h + 6, 2, o.h - 8); ctx.fillRect(x + w - 8, gy - o.h + 6, 2, o.h - 8);\n        ctx.fillStyle = 'rgba(255,255,255,0.3)'; ctx.fillRect(x + 3, gy - o.h + 6, 2, o.h - 8);\n        break;\n      }\n      case 'bench': {\n        ctx.fillStyle = '#2d2a28'; ctx.fillRect(x + 4, gy - 10, 4, 10); ctx.fillRect(x + w - 8, gy - 10, 4, 10); ctx.fillRect(x + w / 2 - 2, gy - 10, 4, 10);\n        ctx.fillStyle = '#a56f3b'; ctx.fillRect(x, gy - 15, w, 5);\n        ctx.fillStyle = '#8a5a2c'; ctx.fillRect(x, gy - 20, w, 4); ctx.fillRect(x, gy - 25, w, 4);\n        ctx.fillStyle = '#2d2a28'; ctx.fillRect(x + 2, gy - 25, 3, 14); ctx.fillRect(x + w - 5, gy - 25, 3, 14);\n        break;\n      }\n      case 'crates': {\n        for (let yy = 0; yy < o.h; yy += 33) {\n          const ch = Math.min(33, o.h - yy), top = gy - yy - ch;\n          ctx.fillStyle = '#b5793a'; ctx.fillRect(x, top, w, ch);\n          ctx.fillStyle = '#7a4d20'; ctx.fillRect(x, top, w, 3); ctx.fillRect(x, top + ch - 3, w, 3); ctx.fillRect(x, top, 3, ch); ctx.fillRect(x + w - 3, top, 3, ch);\n          ctx.fillRect(x + 4, top + ch / 2 - 1, w - 8, 3);\n        }\n        break;\n      }\n      case 'rail': {\n        const top = gy - o.top;\n        ctx.fillStyle = '#69727d';\n        for (let px = x + 8; px < x + w - 4; px += 36) ctx.fillRect(px, top + 4, 3, o.top - 4);\n        ctx.fillStyle = '#9aa4b0'; ctx.fillRect(x - 2, top + 8, w + 4, 2);\n        ctx.fillStyle = '#d9dfe7'; ctx.fillRect(x - 3, top, w + 6, 5);\n        ctx.fillStyle = '#fff'; ctx.fillRect(x - 3, top, w + 6, 1);\n        ctx.fillStyle = '#69727d'; ctx.fillRect(x - 5, top - 2, 3, o.top + 2); ctx.fillRect(x + w + 2, top - 2, 3, o.top + 2);\n        break;\n      }\n      case 'sign': {\n        ctx.fillStyle = '#3a3f4a'; ctx.fillRect(x, gy - 100, 4, 100); ctx.fillRect(x + w - 4, gy - 100, 4, 100);\n        const by = gy - o.top;\n        ctx.fillStyle = '#ffcc00'; ctx.fillRect(x, by, w, o.top - o.b);\n        ctx.fillStyle = '#1d1d1d';\n        for (let i = 0; i < w; i += 16) ctx.fillRect(x + i, by, 8, 6), ctx.fillRect(x + i + 8, by + o.top - o.b - 6, 8, 6);\n        text('DUCK', x + w / 2, by + (o.top - o.b) / 2 + 6, 17, '#1d1d1d', 'center', 'rgba(255,255,255,0.0)', 0);\n        break;\n      }\n    }\n  }\n}\nfunction drawCoin(x, y, r, spin) {\n  const sw = Math.max(1.5, Math.abs(Math.cos(spin)) * r);\n  ctx.fillStyle = '#b58a14'; ctx.fillRect(Math.round(x - sw - 1), Math.round(y - r - 1), Math.round(sw * 2 + 2), Math.round(r * 2 + 2));\n  ctx.fillStyle = '#ffd84a'; ctx.fillRect(Math.round(x - sw), Math.round(y - r), Math.round(sw * 2), Math.round(r * 2));\n  if (sw > 4) {\n    ctx.fillStyle = '#1e8a3c';\n    const c = Math.round(x), d = Math.round(y);\n    ctx.fillRect(c - 3, d - 4, 3, 3); ctx.fillRect(c + 1, d - 4, 3, 3); ctx.fillRect(c - 4, d - 1, 3, 3); ctx.fillRect(c + 2, d - 1, 3, 3); ctx.fillRect(c - 1, d + 1, 2, 5);\n  }\n}\nfunction drawPickups() {\n  for (const c of G.pickups) {\n    if (c.got || c.x > W + 20) continue;\n    drawCoin(c.x, gy - c.h + Math.sin(G.titleT * 4 + c.ph) * 2, 8, G.titleT * 5 + c.ph);\n  }\n}\n\n/* ------------------------------------------------------------------ player drawing */\nfunction drawBoard(a, kind) {\n  let th = 4, sx = 1, flip = 1;\n  if (kind === 0) { th = 4 + 9 * Math.abs(Math.sin(a)); flip = Math.cos(a); }\n  else if (kind === 1) { sx = Math.cos(a); if (Math.abs(sx) < 0.08) sx = 0.08; }\n  ctx.save();\n  ctx.translate(0, -9);\n  ctx.scale(sx, 1);\n  const wheels = kind !== 0 || Math.abs(Math.sin(a)) < 0.55;\n  if (wheels) {\n    ctx.fillStyle = '#8c8f96'; ctx.fillRect(-15, 2, 6, 3); ctx.fillRect(9, 2, 6, 3);\n    ctx.fillStyle = '#f3e3b8';\n    ctx.fillRect(-16, 4, 7, 5); ctx.fillRect(9, 4, 7, 5);\n    ctx.fillStyle = '#d6c28c'; ctx.fillRect(-16, 8, 7, 1); ctx.fillRect(9, 8, 7, 1);\n  }\n  ctx.fillStyle = flip >= 0 ? '#1f8a3f' : '#181818';\n  ctx.fillRect(-24, -th / 2, 48, th);\n  ctx.fillRect(-25, -th / 2 - 2, 4, 3); ctx.fillRect(21, -th / 2 - 2, 4, 3);\n  if (flip >= 0) { ctx.fillStyle = '#f4efe0'; ctx.fillRect(-20, th / 2 - 1, 40, 1); }\n  ctx.restore();\n}\nfunction drawTrav(x, y, opts) {\n  // x,y = wheel-bottom centre. opts: rot, duck, squash, trickA, trickKind, board\n  ctx.save();\n  ctx.translate(Math.round(x), Math.round(y));\n  ctx.rotate(opts.rot || 0);\n  const sq = opts.squash || 0;\n  ctx.scale(1 + sq * 0.9, 1 - sq * 0.8);\n  if (opts.board !== false) drawBoard(opts.trickA || 0, opts.trickKind || 0);\n  const im = IMG.rider;\n  const sh = opts.duck ? SPR_H * 0.64 : SPR_H;\n  if (im) {\n    const sw = sh * (im.width / im.height) * (opts.duck ? 1.12 : 1);\n    ctx.drawImage(im, -sw * 0.365, -12 - sh, sw, sh);\n  } else {\n    ctx.fillStyle = '#111'; ctx.fillRect(-12, -12 - sh, 24, sh);\n  }\n  ctx.restore();\n}\nfunction drawPlayer() {\n  const P = G.P; if (!P) return;\n  let a = 0;\n  if (P.trickT > 0) a = (1 - P.trickT / P.trickDur) * Math.PI * 2 * P.trickDir;\n  drawTrav(P.x, gy - P.h, { rot: P.rot, duck: P.duck, squash: P.squash * 1.3, trickA: a, trickKind: P.trickKind });\n}\nfunction drawRagdoll() {\n  const D = G.D, B = G.B;\n  if (B) { ctx.save(); ctx.translate(B.x, B.y); ctx.rotate(B.rot); ctx.translate(0, 9); drawBoard(0, 2); ctx.restore(); }\n  if (D && IMG.rider) {\n    const sh = SPR_H * 0.9, sw = sh * (IMG.rider.width / IMG.rider.height);\n    ctx.save(); ctx.translate(D.x, D.y); ctx.rotate(D.rot);\n    ctx.drawImage(IMG.rider, -sw * 0.4, -sh / 2, sw, sh);\n    ctx.restore();\n  }\n}\n\n/* ------------------------------------------------------------------ HUD + screens */\nfunction text(s, x, y, size, color, align, stroke, lw) {\n  ctx.font = 'bold ' + size + 'px \"Courier New\",Courier,monospace';\n  ctx.textAlign = align || 'left'; ctx.textBaseline = 'alphabetic'; ctx.lineJoin = 'round';\n  if (lw !== 0) { ctx.lineWidth = lw == null ? Math.max(2, size / 6) : lw; ctx.strokeStyle = stroke || '#000'; ctx.strokeText(s, x, y); }\n  ctx.fillStyle = color; ctx.fillText(s, x, y);\n}\nfunction drawHUD() {\n  const top = portrait ? 38 : 24;\n  text('SCORE ' + String(G.score).padStart(5, '0'), 14, top, 16, '#fff', 'left');\n  text('BEST ' + String(G.best).padStart(5, '0'), 14, top + 19, 12, '#cfe', 'left');\n  drawCoin(24, top + 40, 6, 0.4);\n  text('x' + G.coins, 36, top + 45, 13, '#ffe14d', 'left');\n  const ui = uiRects();\n  const btn = (r, draw) => {\n    ctx.fillStyle = 'rgba(0,0,0,0.38)'; ctx.fillRect(r.x, r.y, r.w, r.h);\n    ctx.strokeStyle = 'rgba(255,255,255,0.55)'; ctx.lineWidth = 2; ctx.strokeRect(r.x + 1, r.y + 1, r.w - 2, r.h - 2);\n    draw(r);\n  };\n  btn(ui.pause, r => { ctx.fillStyle = '#fff'; ctx.fillRect(r.x + 9, r.y + 8, 4, 14); ctx.fillRect(r.x + 17, r.y + 8, 4, 14); });\n  btn(ui.sound, r => {\n    ctx.fillStyle = '#fff'; ctx.fillRect(r.x + 7, r.y + 12, 5, 7); ctx.fillRect(r.x + 12, r.y + 9, 3, 13); ctx.fillRect(r.x + 15, r.y + 6, 3, 19);\n    if (AU.muted) { ctx.strokeStyle = '#ff6b6b'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(r.x + 5, r.y + 25); ctx.lineTo(r.x + 26, r.y + 5); ctx.stroke(); }\n    else { ctx.fillRect(r.x + 21, r.y + 11, 2, 9); }\n  });\n  if (G.banner) {\n    ctx.globalAlpha = Math.min(1, G.banner.t);\n    text(G.banner.txt, W / 2, portrait ? 110 : 80, 20, '#fff', 'center');\n    ctx.globalAlpha = 1;\n  }\n  if (IN.touchMode && G.state === 'play') {\n    const by = H - (portrait ? 70 : 44), r = portrait ? 36 : 30;\n    const duckOn = isDucking();\n    const circ = (cx, label, on) => {\n      ctx.globalAlpha = on ? 0.5 : 0.24; ctx.fillStyle = '#fff';\n      ctx.beginPath(); ctx.arc(cx, by, r, 0, Math.PI * 2); ctx.fill(); ctx.globalAlpha = 0.9;\n      text(label, cx, by + 5, 14, '#fff', 'center', '#000', 3); ctx.globalAlpha = 1;\n    };\n    circ(portrait ? 56 : 52, 'DUCK', duckOn);\n    circ(W - (portrait ? 56 : 52), 'OLLIE', G.P && G.P.jumpHeld);\n  }\n}\nfunction drawTexts() {\n  for (const t of G.texts) {\n    ctx.globalAlpha = clamp(t.life / 0.5, 0, 1);\n    text(t.s, t.x, t.y, 15, t.color, 'center');\n  }\n  ctx.globalAlpha = 1;\n}\nfunction drawParticles() {\n  for (const p of G.parts) {\n    ctx.globalAlpha = clamp(p.life / p.max * 1.4, 0, 1); ctx.fillStyle = p.color;\n    ctx.fillRect(Math.round(p.x), Math.round(p.y), Math.ceil(p.size), Math.ceil(p.size));\n  }\n  ctx.globalAlpha = 1;\n}\nfunction panel(x, y, w, h) {\n  ctx.fillStyle = 'rgba(6,10,24,0.72)'; ctx.fillRect(x, y, w, h);\n  ctx.strokeStyle = '#1fbf5a'; ctx.lineWidth = 3; ctx.strokeRect(x + 1.5, y + 1.5, w - 3, h - 3);\n}\nfunction drawTitle() {\n  const blink = Math.floor(G.titleT * 2) % 2 === 0;\n  const im = IMG.title;\n  const sh = portrait ? Math.min(H * 0.40, 330) : 250;\n  const sw = im ? sh * (im.width / im.height) : sh * 0.5;\n  const cx = portrait ? W / 2 : W * 0.27;\n  const bob = Math.round(Math.sin(G.titleT * 3) * 2);\n  if (im) ctx.drawImage(im, Math.round(cx - sw / 2), Math.round(gy + 10 - sh + bob), Math.round(sw), Math.round(sh));\n  const tx = portrait ? W / 2 : W * 0.64;\n  const ty = portrait ? H * 0.13 : 98;\n  text('TRAV', tx, ty, portrait ? 84 : 76, '#ffffff', 'center', '#0c5a28', 10);\n  text('SKATES', tx, ty + (portrait ? 54 : 46), portrait ? 54 : 48, '#37e07a', 'center', '#04210f', 8);\n  text('BOSTON STREET RUN', tx, ty + (portrait ? 84 : 74), portrait ? 17 : 15, '#fff', 'center');\n  const py = portrait ? gy + 70 : 232;\n  if (blink) text(IN.touchMode ? 'TAP TO START' : 'PRESS SPACE OR CLICK', tx, py, portrait ? 22 : 20, '#ffe14d', 'center');\n  const lines = IN.touchMode\n    ? ['RIGHT SIDE: OLLIE (HOLD = HIGHER)', 'TAP AGAIN IN AIR: TRICK', 'HOLD LEFT SIDE: DUCK', 'LAND ON RAILS TO GRIND']\n    : ['SPACE / UP / CLICK: OLLIE (HOLD = HIGHER)', 'PRESS AGAIN IN AIR: TRICK', 'DOWN / S: DUCK    P: PAUSE    M: MUTE', 'LAND ON RAILS TO GRIND'];\n  const ly = portrait ? py + 40 : 262;\n  lines.forEach((s, i) => text(s, tx, ly + i * 17, portrait ? 13 : 12, '#dfeaff', 'center', '#000', 3));\n  text('BEST ' + String(G.best).padStart(5, '0'), portrait ? W / 2 : tx, portrait ? 40 : 30, 14, '#ffe14d', 'center');\n}\nfunction drawPause() {\n  ctx.fillStyle = 'rgba(0,0,0,0.5)'; ctx.fillRect(0, 0, W, H);\n  text('PAUSED', W / 2, H * 0.42, 44, '#fff', 'center', '#0c5a28', 8);\n  text(IN.touchMode ? 'TAP TO RESUME' : 'PRESS P OR CLICK TO RESUME', W / 2, H * 0.42 + 40, 16, '#ffe14d', 'center');\n}\nfunction drawGameOver() {\n  const pw = Math.min(W - 40, 340), ph = 190;\n  const px = (W - pw) / 2, py = portrait ? H * 0.2 : 56;\n  const k = smooth(G.deadT / 0.5);\n  ctx.globalAlpha = k;\n  panel(px, py, pw, ph);\n  text('WIPEOUT!', W / 2, py + 48, 38, '#ff6b6b', 'center', '#300', 6);\n  text('SCORE  ' + G.score, W / 2, py + 84, 20, '#fff', 'center');\n  text(G.newBest ? 'NEW BEST!' : 'BEST  ' + G.best, W / 2, py + 108, 16, G.newBest ? '#ffe14d' : '#cfe', 'center');\n  text('SHAMROCKS x' + G.coins, W / 2, py + 130, 14, '#ffe14d', 'center');\n  if (G.deadT > 0.7 && Math.floor(G.titleT * 2) % 2 === 0) text(IN.touchMode ? 'TAP TO RETRY' : 'SPACE / CLICK TO RETRY', W / 2, py + 170, 17, '#7dffa0', 'center');\n  ctx.globalAlpha = 1;\n}\n\n/* ------------------------------------------------------------------ render */\nfunction render() {\n  const k = canvas.width / W;\n  ctx.setTransform(k, 0, 0, k, 0, 0);\n  ctx.imageSmoothingEnabled = false;\n  ctx.save();\n  if (G.shake > 0) ctx.translate(rnd(-1, 1) * G.shake * 14, rnd(-1, 1) * G.shake * 14);\n  const T = theme();\n  drawBackground(T);\n  drawGround(T);\n  drawObstacles();\n  drawPickups();\n  if (G.state === 'play' || G.state === 'paused') drawPlayer();\n  else if (G.state === 'dead') drawRagdoll();\n  drawParticles();\n  ctx.restore();\n  drawTexts();\n  if (G.state === 'title') drawTitle();\n  else { drawHUD(); if (G.state === 'paused') drawPause(); if (G.state === 'dead') drawGameOver(); }\n}\n\n/* ------------------------------------------------------------------ main loop */\nlet last = 0;\nfunction loop(ts) {\n  requestAnimationFrame(loop);\n  const dt = clamp((ts - last) / 1000 || 0, 0, 1 / 30);\n  last = ts;\n  update(dt);\n  render();\n}\n\nPromise.all([loadImage(\"data:image/png;base64,\"), loadImage(\"data:image/png;base64,\")]).then(([rider, title]) => {\n  IMG.rider = rider; IMG.title = title;\n  resize();\n  if (loadingEl) { loadingEl.classList.add('hide'); setTimeout(() => { if (loadingEl.parentNode) loadingEl.parentNode.removeChild(loadingEl); }, 400); }\n  requestAnimationFrame(loop);\n});\n\n// small hook used for automated smoke tests\nwindow.TravGame = { G, update, render, action, pressJump, releaseJump, resize, IN, setImages: (r, t) => { IMG.rider = r; IMG.title = t; } };\n})();\n\n<\/script>\n<script>window.addEventListener(\"load\",function(){try{window.focus();}catch(e){}});<\/script>\n<\/body>\n<\/html>\n";
let travSkatesOverlayEl = null, travSkatesOverlayFrame = null;
let travSkatesReturnState = 'play';
let travSkatesHistoryPushed = false;

function createTravSkatesOverlay() {
  const style = document.createElement('style');
  style.textContent = `
    #travSkatesApp {
      position: fixed; inset: 0; z-index: 1000;
      background: #000;
      display: none; flex-direction: column;
    }
    #travSkatesApp.open { display: flex; }
    #travSkatesApp .ts-bar {
      flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between;
      gap: 12px; padding: 8px 14px;
      background: linear-gradient(#0f2a1b, #08140d);
      border-bottom: 2px solid #1f8a4c;
      padding-top: calc(8px + env(safe-area-inset-top, 0px));
    }
    #travSkatesApp .ts-title {
      color: #fbe600; font: bold 14px monospace; letter-spacing: 0.5px;
      white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    }
    #travSkatesApp .ts-close {
      flex: 0 0 auto; cursor: pointer;
      background: rgba(31,138,76,0.25);
      border: 1.5px solid rgba(60,200,120,0.9);
      color: #eaffee; border-radius: 8px;
      padding: 7px 16px; font: bold 13px monospace;
      -webkit-user-select: none; user-select: none;
    }
    #travSkatesApp .ts-close:active { background: rgba(60,200,120,0.5); }
    #travSkatesApp iframe {
      flex: 1 1 auto; width: 100%; border: 0; background: #0b1020;
      touch-action: none;
    }
  `;
  document.head.appendChild(style);

  travSkatesOverlayEl = document.createElement('div');
  travSkatesOverlayEl.id = 'travSkatesApp';
  const bar = document.createElement('div');
  bar.className = 'ts-bar';
  const title = document.createElement('div');
  title.className = 'ts-title';
  title.textContent = 'TRAV SKATES \u2014 TALENT';
  const closeBtn = document.createElement('div');
  closeBtn.className = 'ts-close';
  closeBtn.textContent = '\u2190 BACK TO THE SHOP';
  bindTap(closeBtn, closeTravSkatesApp);
  bar.appendChild(title);
  bar.appendChild(closeBtn);
  travSkatesOverlayFrame = document.createElement('iframe');
  travSkatesOverlayFrame.setAttribute('allow', 'autoplay');
  travSkatesOverlayEl.appendChild(bar);
  travSkatesOverlayEl.appendChild(travSkatesOverlayFrame);
  document.body.appendChild(travSkatesOverlayEl);

  window.addEventListener('message', (e) => {
    if (!travSkatesOverlayFrame || e.source !== travSkatesOverlayFrame.contentWindow) return;
    if (e.data && e.data.travSkates === 'close' && state === 'travSkatesApp') closeTravSkatesApp();
  });
}
createTravSkatesOverlay();

// Called from MINIGAME_ACTIONS.travskates (E on the skateboard sign, or tapping it).
function openTravSkatesApp() {
  travSkatesReturnState = state;
  travSkatesOverlayFrame.srcdoc = TRAV_SKATES_HTML;
  travSkatesOverlayEl.classList.add('open');
  state = 'travSkatesApp';
  travSkatesOverlayFrame.addEventListener('load', () => {
    try { travSkatesOverlayFrame.contentWindow.focus(); } catch (e) { /* a tap will focus it */ }
  }, { once: true });
  history.pushState({ travSkatesApp: true }, '');
  travSkatesHistoryPushed = true;
}

// Tears the iframe down (stopping its audio/loop) and returns to TALENT.
// fromPopState: true when the browser's back button already consumed the
// history entry, so we must not call history.back() again.
function closeTravSkatesApp(fromPopState) {
  travSkatesOverlayEl.classList.remove('open');
  travSkatesOverlayFrame.removeAttribute('srcdoc');
  travSkatesOverlayFrame.src = 'about:blank';
  reclaimGameFocus(travSkatesOverlayFrame);
  state = travSkatesReturnState;
  if (!fromPopState && travSkatesHistoryPushed) {
    travSkatesHistoryPushed = false;
    history.back();
  } else {
    travSkatesHistoryPushed = false;
  }
}


// ARKAIIK IMPACT -- a skateboard painting studio (pick ink, drag to paint a
// deck, stickers, eraser, undo, export a PNG) set out on the concrete plaza
// of LEVEL 3 (SKATEPARK), triggered by a floating paint brush (see the
// skatepark map's `minigames` list in makeSkatepark()). Same "full-screen
// DOM overlay with an <iframe>" pattern as the Hip Hop Library/chess/the
// beat bot/the organ/.../Filter Lab above.
//
// Ships as ONE bundled, self-contained file (inline CSS and JS, host art
// embedded as a data URI, no external fonts, CDNs, or network calls at all)
// (embedded below as ARKAIIK_IMPACT_APP_HTML and loaded via iframe srcdoc,
// so no separate file is needed). Being fully local rather than a live
// remote site means it loads and works identically with or without a
// connection, so there's no online/offline branching needed here. Painting and PNG export are pure
// client-side canvas work, so those work offline too.
// The whole paint studio is embedded right here as a string and handed to the
// iframe via `srcdoc`, so there is NO separate instruments/arkaiik-impact/
// file to go missing (that missing file was what made the app error out on
// load). Nothing is fetched, so it loads and runs fully offline.
const ARKAIIK_IMPACT_APP_HTML = "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no\">\n<title>ARKAIIK IMPACT</title>\n<style>\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml,body{margin:0;height:100%;background:#efe8dc;color:#1b1209;font:bold 12px/1.2 monospace;overflow:hidden;-webkit-user-select:none;user-select:none}\n#app{display:flex;flex-direction:column;height:100%}\n#stage{flex:1 1 auto;min-height:0;min-width:0;display:flex;align-items:center;justify-content:center;padding:8px;\n  background:repeating-linear-gradient(45deg,#e6dcc9 0 14px,#efe8dc 14px 28px)}\n#view{display:block;touch-action:none;cursor:crosshair;filter:drop-shadow(0 6px 10px rgba(0,0,0,.35))}\n#tools{flex:0 0 auto;max-height:46%;overflow-y:auto;background:#1b1209;color:#f7f3ea;padding:8px 10px;border-top:3px solid #ff4d00}\n.row{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:0 0 7px}\n.lbl{color:#ff9a66;font-size:10px;letter-spacing:1px;min-width:46px}\nbutton{font:bold 12px monospace;color:#f7f3ea;background:#3a2414;border:1.5px solid #6b4326;border-radius:7px;padding:7px 10px;cursor:pointer;touch-action:manipulation}\nbutton:active{background:#ff4d00}\nbutton.on{background:#ff4d00;border-color:#ffd2b8;color:#fff}\n.sw{width:28px;height:28px;padding:0;border-radius:50%;border:2px solid #f7f3ea55}\n.sw.on{border:3px solid #fff;box-shadow:0 0 0 2px #ff4d00}\n.dk{width:30px;height:22px;padding:0;border-radius:5px}\ninput[type=range]{flex:1 1 120px;min-width:90px;accent-color:#ff4d00}\n#stickRow{display:none}\n#stickRow.show{display:flex}\n#modal{position:fixed;inset:0;background:rgba(0,0,0,.82);display:none;flex-direction:column;align-items:center;justify-content:center;gap:10px;z-index:9;padding:14px;text-align:center;color:#f7f3ea}\n#modal.show{display:flex}\n#modal img{max-height:62%;max-width:90%;object-fit:contain;background:repeating-conic-gradient(#ccc 0 25%,#fff 0 50%) 50%/16px 16px;border-radius:8px}\n#modal a{display:inline-block;background:#ff4d00;color:#fff;text-decoration:none;padding:9px 16px;border-radius:8px}\n@media (orientation:landscape) and (min-width:560px){\n  #app{flex-direction:row}\n  #tools{max-height:none;width:290px;border-top:0;border-left:3px solid #ff4d00;order:2}\n}\n</style></head><body>\n<div id=\"app\">\n  <div id=\"stage\"><canvas id=\"view\"></canvas></div>\n  <div id=\"tools\">\n    <div class=\"row\"><span class=\"lbl\">TOOL</span>\n      <button data-tool=\"brush\" class=\"on\">BRUSH</button>\n      <button data-tool=\"spray\">SPRAY</button>\n      <button data-tool=\"eraser\">ERASER</button>\n      <button data-tool=\"sticker\">STICKER</button>\n    </div>\n    <div class=\"row\" id=\"stickRow\"><span class=\"lbl\">STAMP</span>\n      <button data-stk=\"star\" class=\"on\">STAR</button>\n      <button data-stk=\"bolt\">BOLT</button>\n      <button data-stk=\"heart\">HEART</button>\n      <button data-stk=\"smile\">SMILE</button>\n      <button data-stk=\"tag\">ARK TAG</button>\n    </div>\n    <div class=\"row\" id=\"inkRow\"><span class=\"lbl\">INK</span></div>\n    <div class=\"row\"><span class=\"lbl\">SIZE</span><input id=\"size\" type=\"range\" min=\"4\" max=\"60\" value=\"18\"></div>\n    <div class=\"row\" id=\"deckRow\"><span class=\"lbl\">DECK</span></div>\n    <div class=\"row\"><span class=\"lbl\">&nbsp;</span>\n      <button id=\"undo\">UNDO</button>\n      <button id=\"clear\">CLEAR</button>\n      <button id=\"save\">SAVE PNG</button>\n    </div>\n  </div>\n</div>\n<div id=\"modal\"><div>Deck exported! If it didn't download, press and hold the image to save it.</div><img id=\"out\" alt=\"Your painted deck\"><div><a id=\"dl\" download=\"arkaiik-impact-deck.png\" href=\"#\">DOWNLOAD PNG</a> <button id=\"mclose\">CLOSE</button></div></div>\n<script>\n(function () {\n  'use strict';\n  var W = 500, H = 1600;\n  var art = document.createElement('canvas'); art.width = W; art.height = H;\n  var actx = art.getContext('2d');\n  var view = document.getElementById('view'); view.width = W; view.height = H;\n  var vctx = view.getContext('2d');\n  var INKS = ['#ff4d00', '#ffd400', '#00b7ff', '#e6007e', '#17c964', '#7a3cff', '#111111', '#ffffff', '#8a5a2b', '#ff8fb3'];\n  var DECKS = ['#e8d5a8', '#1b1b1b', '#f7f3ea', '#2a5caa', '#c0392b', '#2e8b57'];\n  var color = INKS[0], size = 18, tool = 'brush', stk = 'star', deckColor = DECKS[0];\n  var undoStack = [], MAXU = 12, drawing = false, last = null;\n  var STORE = 'arkaiikImpactDeck_v1';\n\n  function deckPath(c) {\n    var x = 12, y = 12, w = W - 24, h = H - 24, r = w / 2;\n    c.beginPath();\n    c.moveTo(x, y + r);\n    c.arc(x + r, y + r, r, Math.PI, 0);\n    c.lineTo(x + w, y + h - r);\n    c.arc(x + r, y + h - r, r, 0, Math.PI);\n    c.closePath();\n  }\n  function paintDeck(c, withShadow) {\n    deckPath(c); c.fillStyle = deckColor; c.fill();\n    c.save(); deckPath(c); c.clip();\n    c.drawImage(art, 0, 0);\n    // truck bolts\n    c.fillStyle = 'rgba(0,0,0,.28)';\n    [[0.17], [0.83]].forEach(function (p) {\n      var yy = H * p[0];\n      [[-48, -30], [48, -30], [-48, 30], [48, 30]].forEach(function (o) {\n        c.beginPath(); c.arc(W / 2 + o[0], yy + o[1], 6, 0, 6.2832); c.fill();\n      });\n    });\n    c.restore();\n    deckPath(c); c.lineWidth = 7; c.strokeStyle = 'rgba(27,18,9,.85)'; c.stroke();\n  }\n  function render() { vctx.clearRect(0, 0, W, H); paintDeck(vctx); }\n\n  function fit() {\n    var st = document.getElementById('stage');\n    var aw = st.clientWidth - 16, ah = st.clientHeight - 16;\n    if (aw < 40 || ah < 40) return;\n    var s = Math.min(aw / W, ah / H);\n    view.style.width = Math.floor(W * s) + 'px';\n    view.style.height = Math.floor(H * s) + 'px';\n  }\n  window.addEventListener('resize', fit);\n  window.addEventListener('orientationchange', function () { setTimeout(fit, 150); });\n\n  function pushUndo() {\n    try {\n      undoStack.push(actx.getImageData(0, 0, W, H));\n      if (undoStack.length > MAXU) undoStack.shift();\n    } catch (e) { /* ignore */ }\n  }\n  function pos(e) {\n    var r = view.getBoundingClientRect();\n    return { x: (e.clientX - r.left) * W / r.width, y: (e.clientY - r.top) * H / r.height };\n  }\n\n  function drawSticker(c, type, x, y, s, col) {\n    c.save(); c.translate(x, y);\n    c.fillStyle = col; c.strokeStyle = '#1b1209'; c.lineWidth = Math.max(2, s * 0.07); c.lineJoin = 'round';\n    c.globalCompositeOperation = 'source-over';\n    c.beginPath();\n    if (type === 'star') {\n      for (var i = 0; i < 10; i++) {\n        var a = -Math.PI / 2 + i * Math.PI / 5, rr = i % 2 ? s * 0.22 : s * 0.5;\n        c[i ? 'lineTo' : 'moveTo'](Math.cos(a) * rr, Math.sin(a) * rr);\n      }\n      c.closePath(); c.fill(); c.stroke();\n    } else if (type === 'bolt') {\n      var p = [[0.1, -0.5], [-0.28, 0.08], [-0.02, 0.08], [-0.14, 0.5], [0.3, -0.1], [0.04, -0.1], [0.26, -0.5]];\n      p.forEach(function (q, k) { c[k ? 'lineTo' : 'moveTo'](q[0] * s, q[1] * s); });\n      c.closePath(); c.fill(); c.stroke();\n    } else if (type === 'heart') {\n      var u = s / 2;\n      c.moveTo(0, u * 0.9);\n      c.bezierCurveTo(-u * 1.5, -u * 0.2, -u * 0.6, -u * 1.1, 0, -u * 0.35);\n      c.bezierCurveTo(u * 0.6, -u * 1.1, u * 1.5, -u * 0.2, 0, u * 0.9);\n      c.closePath(); c.fill(); c.stroke();\n    } else if (type === 'smile') {\n      c.arc(0, 0, s * 0.5, 0, 6.2832); c.fill(); c.stroke();\n      c.fillStyle = '#1b1209';\n      c.beginPath(); c.arc(-s * 0.17, -s * 0.12, s * 0.06, 0, 6.2832); c.fill();\n      c.beginPath(); c.arc(s * 0.17, -s * 0.12, s * 0.06, 0, 6.2832); c.fill();\n      c.beginPath(); c.arc(0, s * 0.03, s * 0.28, 0.15 * Math.PI, 0.85 * Math.PI); c.lineWidth = Math.max(2, s * 0.06); c.lineCap = 'round'; c.stroke();\n    } else {\n      c.font = 'bold ' + Math.round(s * 0.42) + 'px Impact, Arial Black, sans-serif';\n      c.textAlign = 'center'; c.textBaseline = 'middle';\n      c.lineWidth = Math.max(3, s * 0.09);\n      c.strokeText('ARKAIIK', 0, 0); c.fillText('ARKAIIK', 0, 0);\n    }\n    c.restore();\n  }\n\n  function strokeTo(a, b) {\n    actx.save();\n    if (tool === 'eraser') actx.globalCompositeOperation = 'destination-out';\n    if (tool === 'spray') {\n      actx.fillStyle = color;\n      var steps = Math.max(1, Math.ceil(Math.hypot(b.x - a.x, b.y - a.y) / (size * 0.5)));\n      for (var s = 0; s <= steps; s++) {\n        var cx = a.x + (b.x - a.x) * s / steps, cy = a.y + (b.y - a.y) * s / steps;\n        for (var i = 0; i < 14; i++) {\n          var ang = Math.random() * 6.2832, rad = size * 1.5 * Math.sqrt(Math.random());\n          actx.globalAlpha = 0.55 + Math.random() * 0.4;\n          actx.fillRect(cx + Math.cos(ang) * rad, cy + Math.sin(ang) * rad, 2.5, 2.5);\n        }\n      }\n    } else {\n      actx.strokeStyle = color; actx.lineWidth = size; actx.lineCap = 'round'; actx.lineJoin = 'round';\n      actx.beginPath(); actx.moveTo(a.x, a.y); actx.lineTo(b.x, b.y); actx.stroke();\n    }\n    actx.restore();\n  }\n\n  view.addEventListener('pointerdown', function (e) {\n    e.preventDefault();\n    try { view.setPointerCapture(e.pointerId); } catch (x) { /* ignore */ }\n    pushUndo();\n    var p = pos(e);\n    if (tool === 'sticker') { drawSticker(actx, stk, p.x, p.y, size * 4, color); render(); persist(); return; }\n    drawing = true; last = p; strokeTo(p, { x: p.x + 0.01, y: p.y }); render();\n  });\n  view.addEventListener('pointermove', function (e) {\n    if (!drawing) return;\n    e.preventDefault();\n    var p = pos(e); strokeTo(last, p); last = p; render();\n  });\n  function end() { if (drawing) { drawing = false; last = null; persist(); } }\n  view.addEventListener('pointerup', end);\n  view.addEventListener('pointercancel', end);\n  view.addEventListener('lostpointercapture', end);\n\n  function persist() {\n    try { localStorage.setItem(STORE, JSON.stringify({ img: art.toDataURL('image/png'), deck: deckColor })); } catch (e) { /* storage unavailable: fine */ }\n  }\n  function restore() {\n    try {\n      var d = JSON.parse(localStorage.getItem(STORE) || 'null');\n      if (!d) return;\n      if (d.deck) deckColor = d.deck;\n      if (d.img) { var im = new Image(); im.onload = function () { actx.drawImage(im, 0, 0); render(); }; im.src = d.img; }\n    } catch (e) { /* ignore */ }\n  }\n\n  function undo() {\n    var s = undoStack.pop(); if (!s) return;\n    actx.putImageData(s, 0, 0); render(); persist();\n  }\n  function clearAll() {\n    pushUndo(); actx.clearRect(0, 0, W, H); render(); persist();\n  }\n  function exportPng() {\n    var out = document.createElement('canvas'); out.width = W; out.height = H;\n    paintDeck(out.getContext('2d'));\n    var show = function (url) {\n      document.getElementById('out').src = url;\n      var a = document.getElementById('dl'); a.href = url;\n      document.getElementById('modal').classList.add('show');\n      try { a.click(); } catch (e) { /* user can tap the link */ }\n    };\n    try {\n      if (out.toBlob) out.toBlob(function (b) { show(b ? URL.createObjectURL(b) : out.toDataURL('image/png')); }, 'image/png');\n      else show(out.toDataURL('image/png'));\n    } catch (e) { show(out.toDataURL('image/png')); }\n  }\n\n  // ---- UI wiring\n  function mark(sel, el) {\n    Array.prototype.forEach.call(document.querySelectorAll(sel), function (b) { b.classList.remove('on'); });\n    el.classList.add('on');\n  }\n  var inkRow = document.getElementById('inkRow'), deckRow = document.getElementById('deckRow');\n  INKS.forEach(function (c, i) {\n    var b = document.createElement('button'); b.className = 'sw' + (i ? '' : ' on'); b.style.background = c; b.setAttribute('aria-label', 'ink ' + c);\n    b.onclick = function () { color = c; mark('#inkRow .sw', b); if (tool === 'eraser') setTool('brush'); };\n    inkRow.appendChild(b);\n  });\n  DECKS.forEach(function (c, i) {\n    var b = document.createElement('button'); b.className = 'dk' + (i ? '' : ' on'); b.style.background = c; b.setAttribute('aria-label', 'deck ' + c);\n    b.onclick = function () { deckColor = c; mark('#deckRow .dk', b); render(); persist(); };\n    deckRow.appendChild(b);\n  });\n  function setTool(t) {\n    tool = t;\n    Array.prototype.forEach.call(document.querySelectorAll('[data-tool]'), function (b) { b.classList.toggle('on', b.getAttribute('data-tool') === t); });\n    document.getElementById('stickRow').classList.toggle('show', t === 'sticker');\n    setTimeout(fit, 0);\n  }\n  Array.prototype.forEach.call(document.querySelectorAll('[data-tool]'), function (b) { b.onclick = function () { setTool(b.getAttribute('data-tool')); }; });\n  Array.prototype.forEach.call(document.querySelectorAll('[data-stk]'), function (b) {\n    b.onclick = function () { stk = b.getAttribute('data-stk'); mark('[data-stk]', b); };\n  });\n  document.getElementById('size').oninput = function () { size = +this.value; };\n  document.getElementById('undo').onclick = undo;\n  document.getElementById('clear').onclick = clearAll;\n  document.getElementById('save').onclick = exportPng;\n  document.getElementById('mclose').onclick = function () { document.getElementById('modal').classList.remove('show'); };\n\n  window.addEventListener('keydown', function (e) {\n    if (e.key === 'Escape') { try { parent.postMessage({ arkaiikImpact: 'close' }, '*'); } catch (x) { /* ignore */ } }\n    else if ((e.ctrlKey || e.metaKey) && (e.key === 'z' || e.key === 'Z')) { e.preventDefault(); undo(); }\n  });\n\n  restore();\n  // keep the deck-colour swatch in sync with whatever was restored\n  var di = DECKS.indexOf(deckColor);\n  if (di > -1) mark('#deckRow .dk', deckRow.children[di + 1]);\n  render(); fit(); setTimeout(fit, 60); setTimeout(fit, 300);\n})();\n<\/script></body></html>\n";
let arkaiikImpactOverlayEl = null, arkaiikImpactOverlayFrame = null;
let arkaiikImpactReturnState = 'play';
let arkaiikImpactHistoryPushed = false; // mirrors hiphopLibraryHistoryPushed/... -- see openArkaiikImpactApp()/closeArkaiikImpactApp()

function createArkaiikImpactOverlay() {
  const style = document.createElement('style');
  style.textContent = `
    #arkaiikImpactApp {
      position: fixed; inset: 0; z-index: 1000;
      background: #000;
      display: none; flex-direction: column;
    }
    #arkaiikImpactApp.open { display: flex; }
    #arkaiikImpactApp .aki-bar {
      flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between;
      gap: 12px; padding: 10px 14px;
      background: linear-gradient(#2a1208, #150a04);
      border-bottom: 2px solid #ff4d00;
      padding-top: calc(10px + env(safe-area-inset-top, 0px));
    }
    #arkaiikImpactApp .aki-title {
      color: #f7f3ea; font: bold 14px monospace; letter-spacing: 0.5px;
      white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    }
    #arkaiikImpactApp .aki-close {
      flex: 0 0 auto; cursor: pointer;
      background: rgba(255,77,0,0.15);
      border: 1.5px solid rgba(255,77,0,0.9);
      color: #f7f3ea; border-radius: 8px;
      padding: 7px 16px; font: bold 13px monospace;
      -webkit-user-select: none; user-select: none;
    }
    #arkaiikImpactApp .aki-close:active { background: rgba(255,77,0,0.45); }
    #arkaiikImpactApp iframe {
      flex: 1 1 auto; width: 100%; border: 0; background: #efe8dc;
    }
  `;
  document.head.appendChild(style);

  arkaiikImpactOverlayEl = document.createElement('div');
  arkaiikImpactOverlayEl.id = 'arkaiikImpactApp';

  const bar = document.createElement('div');
  bar.className = 'aki-bar';
  const title = document.createElement('div');
  title.className = 'aki-title';
  title.textContent = 'ARKAIIK IMPACT \u2014 PAINT LAB';
  const closeBtn = document.createElement('div');
  closeBtn.className = 'aki-close';
  closeBtn.textContent = '\u2190 BACK TO THE PARK';
  bindTap(closeBtn, closeArkaiikImpactApp);
  bar.appendChild(title);
  bar.appendChild(closeBtn);

  arkaiikImpactOverlayFrame = document.createElement('iframe');

  arkaiikImpactOverlayEl.appendChild(bar);
  arkaiikImpactOverlayEl.appendChild(arkaiikImpactOverlayFrame);
  document.body.appendChild(arkaiikImpactOverlayEl);

  // [Esc] pressed while the iframe itself has keyboard focus never reaches
  // this page's keydown handler, so the app posts a message instead.
  window.addEventListener('message', (e) => {
    if (!arkaiikImpactOverlayFrame || e.source !== arkaiikImpactOverlayFrame.contentWindow) return;
    if (e.data && e.data.arkaiikImpact === 'close' && state === 'arkaiikImpactApp') closeArkaiikImpactApp();
  });
}
createArkaiikImpactOverlay();

// Opens the ARKAIIK IMPACT overlay and switches state to 'arkaiikImpactApp'.
// Called from MINIGAME_ACTIONS.arkaiikimpact (E on the paint brush, or
// tapping its floating sign), same entry points every other mini-game uses.
function openArkaiikImpactApp() {
  arkaiikImpactReturnState = state;
  arkaiikImpactOverlayFrame.removeAttribute('src');
  arkaiikImpactOverlayFrame.srcdoc = ARKAIIK_IMPACT_APP_HTML;
  arkaiikImpactOverlayEl.classList.add('open');
  state = 'arkaiikImpactApp';
  // Same throwaway-history-entry trick as openHipHopLibraryApp() etc.
  // above, so the browser/OS back gesture closes the overlay instead of
  // leaving the game entirely.
  history.pushState({ arkaiikImpactApp: true }, '');
  arkaiikImpactHistoryPushed = true;
}

// Tears the iframe back down and returns to ordinary gameplay in the park.
// fromPopState mirrors closeHipHopLibraryApp()'s parameter -- true when
// triggered by the browser's back button (whose history entry is already
// consumed), so we must not call history.back() again in that case.
function closeArkaiikImpactApp(fromPopState) {
  arkaiikImpactOverlayEl.classList.remove('open');
  arkaiikImpactOverlayFrame.removeAttribute('srcdoc'); // srcdoc wins over src, so drop it first
  arkaiikImpactOverlayFrame.src = 'about:blank';
  reclaimGameFocus(arkaiikImpactOverlayFrame);
  state = arkaiikImpactReturnState;
  if (!fromPopState && arkaiikImpactHistoryPushed) {
    arkaiikImpactHistoryPushed = false;
    history.back();
  } else {
    arkaiikImpactHistoryPushed = false;
  }
}

// PRECISION POINTS -- a one-button, timing-based basketball shooting game
// (hold to charge, release in the sweet spot, string together swishes)
// parked at center court of the little basketball court at the bottom of
// the SKATEPARK level (see the skatepark map's `minigames` list). Same
// "full-screen DOM overlay with an <iframe>" pattern as ARKAIIK IMPACT /
// the Hip Hop Library above.
//
// Ships as ONE bundled, self-contained file (inline CSS and JS, every sprite
// embedded as a data URI, sound effects synthesized with WebAudio, no
// external fonts, CDNs, or network calls at all) at
// instruments/precision-points/index.html -- the exact same local-file
// pattern ARKAIIK_IMPACT_APP_URL/HIPHOP_LIBRARY_APP_URL/... use. Being a
// same-origin local asset rather than a live remote site means it loads and
// works identically with or without a connection, so there's no
// online/offline branching needed here. High scores are saved with
// try/catch-wrapped localStorage, so that works offline too (and just
// doesn't persist if storage is unavailable).
const PRECISION_POINTS_APP_URL = 'instruments/precision-points/index.html';
let precisionPointsOverlayEl = null, precisionPointsOverlayFrame = null;
let precisionPointsReturnState = 'play';
let precisionPointsHistoryPushed = false; // mirrors arkaiikImpactHistoryPushed -- see openPrecisionPointsApp()/closePrecisionPointsApp()

function createPrecisionPointsOverlay() {
  const style = document.createElement('style');
  style.textContent = `
    #precisionPointsApp {
      position: fixed; inset: 0; z-index: 1000;
      background: #000;
      display: none; flex-direction: column;
    }
    #precisionPointsApp.open { display: flex; }
    #precisionPointsApp .pp-bar {
      flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between;
      gap: 12px; padding: 10px 14px;
      background: linear-gradient(#2b1440, #160f26);
      border-bottom: 2px solid #ffc72c;
      padding-top: calc(10px + env(safe-area-inset-top, 0px));
    }
    #precisionPointsApp .pp-title {
      color: #f4ecff; font: bold 14px monospace; letter-spacing: 0.5px;
      white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    }
    #precisionPointsApp .pp-close {
      flex: 0 0 auto; cursor: pointer;
      background: rgba(255,199,44,0.15);
      border: 1.5px solid rgba(255,199,44,0.9);
      color: #f4ecff; border-radius: 8px;
      padding: 7px 16px; font: bold 13px monospace;
      -webkit-user-select: none; user-select: none;
    }
    #precisionPointsApp .pp-close:active { background: rgba(255,199,44,0.45); }
    #precisionPointsApp iframe {
      flex: 1 1 auto; width: 100%; border: 0; background: #0b0714;
    }
  `;
  document.head.appendChild(style);

  precisionPointsOverlayEl = document.createElement('div');
  precisionPointsOverlayEl.id = 'precisionPointsApp';

  const bar = document.createElement('div');
  bar.className = 'pp-bar';
  const title = document.createElement('div');
  title.className = 'pp-title';
  title.textContent = 'PRECISION POINTS \u2014 SLAM DUNK';
  const closeBtn = document.createElement('div');
  closeBtn.className = 'pp-close';
  closeBtn.textContent = '\u2190 BACK TO THE PARK';
  bindTap(closeBtn, closePrecisionPointsApp);
  bar.appendChild(title);
  bar.appendChild(closeBtn);

  precisionPointsOverlayFrame = document.createElement('iframe');

  precisionPointsOverlayEl.appendChild(bar);
  precisionPointsOverlayEl.appendChild(precisionPointsOverlayFrame);
  document.body.appendChild(precisionPointsOverlayEl);

  // [Esc] pressed while the iframe itself has keyboard focus never reaches
  // this page's keydown handler, so the app posts a message instead.
  window.addEventListener('message', (e) => {
    if (!precisionPointsOverlayFrame || e.source !== precisionPointsOverlayFrame.contentWindow) return;
    if (e.data && e.data.precisionPoints === 'close' && state === 'precisionPointsApp') closePrecisionPointsApp();
  });
}
createPrecisionPointsOverlay();

// Opens the PRECISION POINTS overlay and switches state to
// 'precisionPointsApp'. Called from MINIGAME_ACTIONS.precisionpoints (E on
// the basketball, or tapping its floating sign), same entry points every
// other mini-game uses.
function openPrecisionPointsApp() {
  precisionPointsReturnState = state;
  precisionPointsOverlayFrame.src = PRECISION_POINTS_APP_URL;
  precisionPointsOverlayEl.classList.add('open');
  state = 'precisionPointsApp';
  // Same throwaway-history-entry trick as openArkaiikImpactApp() etc.
  // above, so the browser/OS back gesture closes the overlay instead of
  // leaving the game entirely.
  history.pushState({ precisionPointsApp: true }, '');
  precisionPointsHistoryPushed = true;
}

// Tears the iframe back down (which also stops the game's loop and audio)
// and returns to ordinary gameplay on the court. fromPopState mirrors
// closeArkaiikImpactApp()'s parameter -- true when triggered by the
// browser's back button (whose history entry is already consumed), so we
// must not call history.back() again in that case.
function closePrecisionPointsApp(fromPopState) {
  precisionPointsOverlayEl.classList.remove('open');
  precisionPointsOverlayFrame.src = 'about:blank';
  reclaimGameFocus(precisionPointsOverlayFrame);
  state = precisionPointsReturnState;
  if (!fromPopState && precisionPointsHistoryPushed) {
    precisionPointsHistoryPushed = false;
    history.back();
  } else {
    precisionPointsHistoryPushed = false;
  }
}

// ---------------------------------------------------------------- J2S PRO SKATER (LET'S SKATE billboard)
// J2S PRO SKATER -- a gamepad-first 3D skateboarding game (Three.js) launched
// from the blinking LET'S SKATE billboard below the plaza in LEVEL 3
// (SKATEPARK); see the skatepark map's `minigames`/`skateBillboard` in
// makeSkatepark() and drawMinigameSkateBillboard(). Same "full-screen DOM
// overlay with an <iframe>" pattern as ARKAIIK IMPACT / PRECISION POINTS /
// TRUTH KNOCKS above, with the same "still key-art splash first" flow Truth
// Knocks uses: stepping up to the billboard shows the Santos Shred splash
// (state 'j2sProSkaterSplash'), and E / a tap from there opens the app.
//
// Ships as ONE bundled, self-contained file (inline CSS and JS, Three.js
// bundled INTO the page, the warehouse banner textures and title art embedded
// as data URIs -- no CDN, no external fonts, no network calls at all, and no
// ES-module <script> so it also runs when the game is opened from file://) at
// instruments/j2s-pro-skater/index.html -- the exact same local-file pattern
// every other app here uses. Being a same-origin local asset rather than a
// live remote site means it loads and plays identically with or without a
// connection, so there's no online/offline branching needed. The splash card
// itself is a plain local image (assets/j2s_pro_skater_splash.png).
const J2S_PRO_SKATER_APP_URL = 'instruments/j2s-pro-skater/index.html';
let j2sProSkaterOverlayEl = null, j2sProSkaterOverlayFrame = null;
let j2sProSkaterReturnState = 'play';
let j2sProSkaterSplashReturnState = 'play';
let j2sProSkaterHistoryPushed = false; // mirrors arkaiikImpactHistoryPushed/precisionPointsHistoryPushed -- see openJ2sProSkaterApp()/closeJ2sProSkaterApp()

// Called from MINIGAME_ACTIONS.j2sproskater (E on the billboard, or tapping
// it). Remembers where to return to, then flips to the splash card. State
// stays off 'play', so movement/interaction are blocked while it's up, the
// same way every other splash state works.
function openJ2sProSkaterSplash() {
  j2sProSkaterSplashReturnState = state;
  state = 'j2sProSkaterSplash';
}

// Full-screen splash card -- same "scale art to fully cover the view, blink
// a continue prompt at the bottom" shape as drawTruthKnocksSplash(). Drawn on
// top of the ordinary skatepark render() pass, so the park stays visible/
// dimmed underneath exactly like the other splashes do over their worlds.
function drawJ2sProSkaterSplash() {
  ctx.fillStyle = 'rgba(8,6,12,0.6)';
  ctx.fillRect(0, 0, VIEW_W, VIEW_H);

  if (j2sProSkaterSplashImg.complete && j2sProSkaterSplashImg.naturalWidth) {
    const iw = j2sProSkaterSplashImg.naturalWidth, ih = j2sProSkaterSplashImg.naturalHeight;
    const scale = Math.max(VIEW_W / iw, VIEW_H / ih);
    const dw = iw * scale, dh = ih * scale;
    const dx = (VIEW_W - dw) / 2, dy = (VIEW_H - dh) / 2;
    ctx.drawImage(j2sProSkaterSplashImg, dx, dy, dw, dh);
    ctx.fillStyle = 'rgba(8,6,12,0.30)';
    ctx.fillRect(0, 0, VIEW_W, VIEW_H);
  } else {
    // fallback text-only version, in case the art hasn't loaded in yet
    ctx.textAlign = 'center';
    ctx.fillStyle = '#ffcf3a';
    ctx.font = 'bold 26px monospace';
    ctx.fillText('J2S PRO SKATER', VIEW_W / 2, VIEW_H / 2 - 10);
    ctx.fillStyle = '#f4ecd8';
    ctx.font = '14px monospace';
    ctx.fillText("Let's skate.", VIEW_W / 2, VIEW_H / 2 + 16);
  }

  ctx.textAlign = 'center';
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'rgba(0,0,0,0.85)';
  ctx.font = 'bold 16px monospace';
  const prompt = '- PRESS E TO SKATE -';
  ctx.strokeText(prompt, VIEW_W / 2, VIEW_H - 24);
  ctx.fillStyle = Math.floor(performance.now() / 400) % 2 ? '#bfff32' : '#f4ecd8';
  ctx.fillText(prompt, VIEW_W / 2, VIEW_H - 24);
  ctx.font = 'bold 11px monospace';
  ctx.strokeText('TAP / E: PLAY    ESC / X: BACK', VIEW_W / 2, VIEW_H - 8);
  ctx.fillStyle = '#d8d2c4';
  ctx.fillText('TAP / E: PLAY    ESC / X: BACK', VIEW_W / 2, VIEW_H - 8);
}

function createJ2sProSkaterOverlay() {
  const style = document.createElement('style');
  style.textContent = `
    #j2sProSkaterApp {
      position: fixed; inset: 0; z-index: 1000;
      /* The splash art doubles as the loading backdrop, so there's never a
         black flash between the splash card and the game's own title screen. */
      background: #06080e url('assets/j2s_pro_skater_splash.png') center / cover no-repeat;
      display: none; flex-direction: column;
    }
    #j2sProSkaterApp.open { display: flex; }
    #j2sProSkaterApp .j2s-bar {
      flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between;
      gap: 12px; padding: 10px 14px;
      background: linear-gradient(#1c1a14, #0d0c08);
      border-bottom: 2px solid #ffcf3a;
      padding-top: calc(10px + env(safe-area-inset-top, 0px));
      position: relative; z-index: 2;
    }
    #j2sProSkaterApp .j2s-title {
      color: #f7f3ea; font: bold 14px monospace; letter-spacing: 0.5px;
      white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    }
    #j2sProSkaterApp .j2s-close {
      flex: 0 0 auto; cursor: pointer;
      background: rgba(255,207,58,0.15);
      border: 1.5px solid rgba(255,207,58,0.9);
      color: #f7f3ea; border-radius: 8px;
      padding: 7px 16px; font: bold 13px monospace;
      -webkit-user-select: none; user-select: none;
    }
    #j2sProSkaterApp .j2s-close:active { background: rgba(255,207,58,0.45); }
    #j2sProSkaterApp iframe {
      flex: 1 1 auto; width: 100%; border: 0; background: transparent;
      opacity: 0; transition: opacity 0.25s ease-out;
    }
    #j2sProSkaterApp.loaded iframe { opacity: 1; }
    #j2sProSkaterApp .j2s-loading {
      position: absolute; left: 0; right: 0; bottom: calc(24px + env(safe-area-inset-bottom, 0px));
      text-align: center; color: #bfff32; font: bold 16px monospace; letter-spacing: 1px;
      text-shadow: 2px 2px 0 #000, 0 0 10px rgba(0,0,0,0.9);
      animation: j2sBlink 1s steps(2, start) infinite; pointer-events: none;
    }
    #j2sProSkaterApp.loaded .j2s-loading { display: none; }
    @keyframes j2sBlink { to { visibility: hidden; } }
  `;
  document.head.appendChild(style);

  j2sProSkaterOverlayEl = document.createElement('div');
  j2sProSkaterOverlayEl.id = 'j2sProSkaterApp';

  const bar = document.createElement('div');
  bar.className = 'j2s-bar';
  const title = document.createElement('div');
  title.className = 'j2s-title';
  title.textContent = 'J2S PRO SKATER \u2014 WAREHOUSE FREE SKATE';
  const closeBtn = document.createElement('div');
  closeBtn.className = 'j2s-close';
  closeBtn.textContent = '\u2190 BACK TO THE PARK';
  bindTap(closeBtn, closeJ2sProSkaterApp);
  bar.appendChild(title);
  bar.appendChild(closeBtn);

  const loading = document.createElement('div');
  loading.className = 'j2s-loading';
  loading.textContent = 'LOADING...';

  j2sProSkaterOverlayFrame = document.createElement('iframe');
  j2sProSkaterOverlayFrame.setAttribute('allow', 'autoplay; gamepad');
  // Reveal the game (and hand it keyboard/gamepad focus) the moment it has
  // loaded. The 'open' guard ignores the load event of the about:blank that
  // closeJ2sProSkaterApp() points the frame at.
  j2sProSkaterOverlayFrame.addEventListener('load', () => {
    if (!j2sProSkaterOverlayEl.classList.contains('open')) return;
    j2sProSkaterOverlayEl.classList.add('loaded');
    try { j2sProSkaterOverlayFrame.contentWindow.focus(); } catch (_) {}
  });

  j2sProSkaterOverlayEl.appendChild(bar);
  j2sProSkaterOverlayEl.appendChild(loading);
  j2sProSkaterOverlayEl.appendChild(j2sProSkaterOverlayFrame);
  document.body.appendChild(j2sProSkaterOverlayEl);

  // [Esc] pressed while the iframe itself has keyboard focus never reaches
  // this page's keydown handler, so the app posts a message instead.
  window.addEventListener('message', (e) => {
    if (!j2sProSkaterOverlayFrame || e.source !== j2sProSkaterOverlayFrame.contentWindow) return;
    if (e.data && e.data.j2sProSkater === 'close' && state === 'j2sProSkaterApp') closeJ2sProSkaterApp();
  });
}
createJ2sProSkaterOverlay();

